/* 平成22年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h22.committeeSessions.push(...[{"id":"h22-20100510-7","meetingId":"h22-cm05","date":"2010年5月10日","dateIso":"2010-05-10","committee":"厚生委員会","time":"午後１時０２分～午後２時０１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"１ゆたかシルバーセンターの改修","agenda":"１ゆたかシルバーセンターの改修","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ちょっと細かいところで恐縮なんですが、セットバックというのは何cmぐらいになるのか。それから、説明会が行われたということなんですが、行うに当たってどんな周知をされたのかということと、当日の参加人数、主にどんな方が参加されたのか、それから、主に出された意見、質問でもいいんですが、どんな内容だったのかお伺いします。","respondent":"間部高齢者いきがい課長","answer":"主な参加者は、利用者の方が８割ほど、２割ほどが近隣の方々です。主な意見につきましては、先ほどもご説明いたしましたが、やはり休館中は使えなくなるので、活動場所の確保の件と、３月以降、リニューアルオープンしたときの優先予約の状況についてのご質問があったです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"２階なんですが、今回、カーペット敷きに変更して洋室化するということなんですけれども、洋室の大広間と洋室というのがありますけれども、現行は、定員人数は大体何人の部屋で、今回、洋室化ということになると、いすやテーブルなども用意されるかなと思うんですが、それは何人分ぐらい用意される予定なのでしょうか。","respondent":"間部高齢者いきがい課長","answer":"今回、当然、ゆたかに登録されていて、使えなくなるということで、例えば旗の台に移られる場合だと、旗の台でももう一度登録をしていただいていますので、そちらからまたこちらに帰ってくる際には、平成２２年度に使用している団体につきましては、最初に優先的にお受けして。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"２階に限らないんですが、もう少し大きな人数が利用できるようなスペースがなかなか近隣にないということで、もう少し広く使いたい、大きな人数が集まれる会場がないでしょうかという声や要望も聞いているんです。例えば、この２階をパーテーションか何にして、横断的にぶち抜いて使えるような状況はつくれないかなと思うんですけれども、いかがでしょうか。","respondent":"間部高齢者いきがい課長","answer":"２階は、大きな人数が集える場所にならないか、パーテーションで仕切れないかというお話なんですが、洋室大広間と洋室で囲まれたサロンという場所につきましては、現在、ビリヤードの台を置いているところでございまして、物理的には、今、委員がおっしゃられた案については。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"どういう形でやるかは置いておいても、そういった要望も聞いておりますので、このシルバーセンターをそういうふうな内容にするのかどうか、ほかのところで何か代替施設があればいいんですけれども、なかなかない中で、そういった要望も聞いておりますので、ちょっと研究していただいて、何とか少しご検討していただければと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"石田委員","kind":"質問","question":"改修内容のところで、廊下等の段差解消というのがあるんですが、シルバーセンターということからも、できれば段差がないほうがいいというのは、お考えにあると思うんですが、ほかのシルバーセンターも、今までも、改修時に主に段差解消をされてきていると思うんですが、ほかのシルバーセンターで、段差がいまだに残っているところはあるんでしょうか。それが１点。その２点、教えてください。","respondent":"間部高齢者いきがい課長","answer":"先ほども申しましたように、今回のゆたかシルバーセンターについては、昭和３３年の開設ということだったんですが、多くのシルバーセンターが昭和４０年から５０年にかけて建設されているということで、徐々に、古い順に改修工事、また耐震が必要なところは。","voiceIndex":12,"id":"exchange-005"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"２階が、介護予防の拠点設備ということにおいて、今、マシーンを使うことがあるとありましたが、その辺が、どういうお部屋の使い方になるのか。先ほど、１０から２０のサークルの団体があると聞いたんですが、いろいろなサークルがあるわけで、踊りとかもあるわけですけれども、その辺との兼ね合いが、予防事業行われると、どういうふうにすみ分けをされるのかという点を、教えてください。","respondent":"間部高齢者いきがい課長","answer":"第１点目のエレベーターは、今回、なぜ設置されないのかという理由なんですけれども、もともと我々、区としても、エレベーターにつきましては、基本的には設置するものだと、必要性があると認識をしているところではあります。","voiceIndex":15,"id":"exchange-006"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"もしどうしてもだめだったら、階段を工夫して、昇降機をつけるとか、自立した高齢者と言っても、私もよくいろいろな会合に呼ばれて行くんですけれども、立ったり座ったりがすごく大変で、ひざ、腰、足首とか、いろいろ治療を受けながら、それでも元気に通っていらっしゃるという方が多いので、ぜひエレベーターを再検討していただきたいと、もう１回お願いしたい。","respondent":"間部高齢者いきがい課長","answer":"再度のエレベーターの件ですが、私どもも、今後の工事に際しましては、いろいろな要素を検討いたしまして、できる限り設置をするような努力はしていきたいと考えています。ただ、先ほど申しましたように、いろいろな制約があるということも、ご理解いただければと思います。","voiceIndex":17,"id":"exchange-007"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"和室を洋室にすることで、先ほど、机といすが入りますということだったんですが、いろいろな施設を使ってみると、テーブルもいすも、重さとか、操作の仕方とか、すごくいろいろ違っていて、使いよかったり、悪かったりで、特に高齢者なので、使い勝手がよくて、軽く出し入れしやすいものを、ぜひ、選んでいただきたいとお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問","question":"二、三点あるんですが、１点目は、平成２３年１月から、また登録がされるということなんですけれども、ほかのシルバーセンターで、改築して、今までの団体がほんとうに登録できるかと、いまだに心配しているところもあるので、その辺、丁寧に、例えばその時期には、どこかほかを使っていることもわかるでしょうから、そちらのほうにもお声をかけていただいて、ぜひ漏れのないようにお願いしたいと思います。","respondent":"間部高齢者いきがい課長","answer":"先ほどの優先登録の件につきましては、現在、南品川シルバーセンターにつきましても、８月の再オープンということで、今月の下旬から来月の上旬に関して、やっぱり同じような優先登録の手続に入ってまいります。","voiceIndex":20,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"エレベーターの件で、私も質問したいと思ったんですけれども、忘れてしまいまして、やっぱり高齢者向けの施設ですから、ここにエレベーターがつかないというのは、ほかの施設に比べても、何としても努力をしていかなくちゃいけないところなのではないかと思って聞いていたんです。それから、今回の改修費用全体はどのぐらいを見込んでいるのか、ちょっとそれだけ聞かせてください。","respondent":"間部高齢者いきがい課長","answer":"エレベーター１基つけると幾らかというお話ですが、その形状とか、階層の内容にもよりますし、中付けか外付けかでも異なりますが、おおむね数千万円はかかると認識をしています。","voiceIndex":24,"id":"exchange-010"}]},{"id":"topic-02","title":"２番目の日本脳炎ワクチン予防接種の勧奨再開","agenda":"２番目の日本脳炎ワクチン予防接種の勧奨再開","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"１期、初回目の満３歳児には接種票を郵送するということなんですが、満４歳と９歳のときは、そういった接種票の郵送などは行わないのでしょうか、お伺いします。","respondent":"吉田保健予防課長","answer":"対象者ですが、今般、３歳児ということの解釈が、実は大変に難しゅうございまして、国に問い合わせたところ、３歳の年齢に相当する者という回答しかいただいておりません。","voiceIndex":31,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"わかりました。ちょっと初歩的なことで恐縮なんですが、３歳、４歳、９歳のときに予防接種を受けないと効果が出ないものなのでしょうか。それであるならば、ほかの定期予防接種がどういうふうに通知されているのかも、ちょっとご説明いただきたいんですが、そうであるならば、通知が必要なのかなと思うんですが、いかがでしょうか。","respondent":"吉田保健予防課長","answer":"定期予防接種につきましては、品川区といたしましては、対象の年齢の方、お誕生日を迎えた月の大体上旬になりますが、その方たちに予診票を送らせていただくといった対応をとっております。","voiceIndex":33,"id":"exchange-012"},{"speaker":"金野委員","kind":"質問・要望","question":"２期目に接種をする満９歳を迎える子どもたち。ですが、２回目の段階では、先の話ですけれども、その年齢に当たっての対応が、国としてはどうなっているのか、動向を見ていくということも考えられるのでしょうが、ワクチンの製造、あるいは供給、こういったもののから見ると、今後、どうなっていくのか、少し流れがわかれば、教えていただきたいと思います。","respondent":"吉田保健予防課長","answer":"ですから、今、使えるものといたしましては、１期の方のみということになっております。２期につきましても、今後、知見を集積して対応を図ると、国は申しておりますので、その対応を見守っていきたいと考えています。","voiceIndex":35,"id":"exchange-013"},{"speaker":"金野委員","kind":"質問","question":"漏れた方への対応を、今、検討してくださっているということなんですが、そうなると、それが出た段階で随時、対象者に、区としては通知をして、接種をしていただくようになるのか。そこが１点。そうすると、１期目の薬と２期目の薬と違うということなんでしょうか。同じ日本脳炎を予防するのに、ワクチンが違うというのが、そこら辺がわからないので、ちょっと教えてください。","respondent":"吉田保健予防課長","answer":"ご指摘のように、このように、違うワクチンを打つことによる健康被害への影響とか、健康への影響、あるいは、効果といったものについても、厚生科学審議会等で検討すると聞いておりますので、そちらも注意深く見守ってまいりたいと考えています。","voiceIndex":37,"id":"exchange-014"},{"speaker":"金野委員","kind":"意見","question":"平成１７年から２１年の間、接種がなされてこなかったお母さん、あるいは子どもに対して、これが再開をされることによって、自分たちがどうなのかと、ちょっと不安になる方もあるやに思います。","respondent":"吉田保健予防課長","answer":"接種を希望される方へのご案内と申しますか、そういうアナウンスにつきましては、ホームページ等、あるいは医療機関等にお願いをして、ご希望の方には周知を図っていこうと考えています。実際、近いうちに、品川区内の医師会とは、方法については検討していく予定です。","voiceIndex":39,"id":"exchange-015"},{"speaker":"金野委員","kind":"意見","question":"きめ細かな対応でお考えだと思いますが、ぜひ、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これは、５年間ではなくて、もっと先まで影響が出ていくと思うんですけれども、５年間だからどうとは言い切れないところがあるんですけれども、その辺がどうなっているのか、ちょっと教えていただきたい。もう１点、ワクチン接種の費用は、今、お幾らぐらいになっているんでしょうか。","respondent":"吉田保健予防課長","answer":"ただ、６カ月から９０カ月を外れた方につきましては、自己負担が生じるという任意接種の扱いになってしまいますので、自己負担が生じるということになります。その際には、１回、約８,５００円程度かかるということになります。","voiceIndex":42,"id":"exchange-017"},{"speaker":"鈴木委員","kind":"質問・要望","question":"だから、区でやりなさいということは、今、求めていませんけれども、その辺、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-018"},{"speaker":"飯沼副委員長","kind":"質問","question":"インターネットで見たら、昔に比べると、抗体の保有率が下がっているというか、年齢的に、３０歳から６０歳後半ぐらいの人がすごく下がっているとか、昔はもうちょっと、年齢にかかわりなく抗体を持っていたということを見たんですけれども、その辺で、ワクチンの接種率とか、抗体の保有状況とかが、年齢別に見て、わかっていたら、教えてください。","respondent":"吉田保健予防課長","answer":"発症率ですが、感染した方の１００人から１,０００人に１人ぐらい。ですから、１％から０.１％の方が発病すると言われております。ほとんどの方は無症状なんですが、まれに脳炎を起こすことがあるです。","voiceIndex":45,"id":"exchange-019"},{"speaker":"飯沼副委員長","kind":"質問","question":"今回は、接種の勧奨が再開されたけれども、３歳になる人と、なった人ということで、先ほど、ワクチンの数量的な問題であるということでしたが、親の立場で聞くと、５年間受けないでいて、その年齢に入った方は受けられるんだったら、すぐにでも受けたい、受けないとどうなんだろうかと、ほんとうに心配をされると思うので、早くその辺のめどを立てていただいて、きちんとお知らせをしてほしいと思うんです。","respondent":"吉田保健予防課長","answer":"ということで、今回、ワクチンの勧奨再開という運びになったと認識しております。","voiceIndex":47,"id":"exchange-020"},{"speaker":"鈴木委員","kind":"確認","question":"広域連合のほうの処理なので、品川区は直接ではないと思うんですけれども、郵送が届いた中で、品川区に対しての質問はなかったのかということが１点。それから、今後の対策として、回収に全力を尽くすと出ているんですが、これは広域連合でやるんですよね。品川区に、例えば品川区に何人いるから、その方をお願いしますというようなことが来るのか、どうか。その２点、確認だけ。","respondent":"本城国保医療年金課長","answer":"１点目の、品川区へのお問い合わせ等ですが、連休前の時点ですが、二重に振り込まれた方から約２０件ほどお問い合わせがあり、それから支給がおくれたことに対しては、１０件ほどのお問い合わせが、直後の１週間ぐらいの間にありました。現在は落ち着いている状況です。","voiceIndex":54,"id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問・要望","question":"後のほうはわかりました、広域連合で頑張ってもらうしかない。ただ、品川区にやっぱり問い合わせがあるという中では、これからもまた大変かと思うんですが、よく説明をお願いしたいと思います。これは要望にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"返納の方法はどういう方法なのでしょうか。返納しなかった場合、どうなるのかということを知りたいので、教えてください。そういった今回のケースで、対応は可能なのかどうか、お伺いします。","respondent":"本城国保医療年金課長","answer":"返納の方法ですが、先ほど、ご説明させていただいたことと重なりますが、納入通知書をご本人あてに送付して、それでお金を返していただくということで対応するです。","voiceIndex":57,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後のほうは、広域連合の話ではあるんですけれども、直接、区民にかかわってきますので、ぜひ、品川区としても情報収集などしていただきたいんですが、データの上書き保存をして消えてしまったというのは、何か個人がそういうミスをしてしまったのか、よくわからないのですが、かなり原始的な、初歩的なミスのように聞こえてならないので、こうしたミスが多いような状況もあると思うので、ないように。","respondent":"本城国保医療年金課長","answer":"広域連合に対しまして働きかけですが、広域連合の協議会の幹事会というところがございまして、ちょうど今週にありますので、２３区の部長会の代表のほうから、今回の件の適切な対応等、それから再発防止策の徹底等について申入れを行うと確認しています。","voiceIndex":59,"id":"exchange-024"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"件数は伺ったんですが、総額で幾らぐらいになったのか、教えていただきたい。この財源は、名目的には、後でちょっと決算書なんかを見たいんですけれども、どこから出ているのか。それから、決算のところで響かないのか、ちょっとそこを教えてください。","respondent":"本城国保医療年金課長","answer":"財源については、給付費ということで、保険給付の一環としての給付ということで、返還してもらうことによって、基本的に年度中に解決していくと考えていると認識しています。今回、５月末をめどにご返還いただくというスケジュールで進んでいると伺っているところです。","voiceIndex":61,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3266#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":18996,"voices":67}},{"id":"h22-20100510-8","meetingId":"h22-cm05","date":"2010年5月10日","dateIso":"2010-05-10","committee":"建設委員会","time":"午後１時０２分～午後３時１５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"でございます。初めに、１のしながわＥＣＯフェスティバル２０１０の開催","agenda":"でございます。初めに、１のしながわＥＣＯフェスティバル２０１０の開催","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"今回でＥＣＯフェスティバルは何回目になるのかということが１点と、目的について書いてないんですけれども、もう何回もやっているからわかっているでしょということで目的を書かないのかと思うんですけれども、改めてこのフェスティバルの目的についてお伺いします。","respondent":"工藤環境課長","answer":"１点目のＥＣＯフェスティバルの回数ですけれども、中央公園に移りまして６回目となります。ただ、こちらはさかのぼりますとかなり前からやってございまして、西大井広場で「環境リサイクルフェア」という形で始めたのがきっかけです。","voiceIndex":7,"id":"exchange-001"},{"speaker":"藤原委員","kind":"質問","question":"毎年やっているから今年もやろうではいけないと思うんですね、そういう答弁はいただいていないですけれど。それから、今、課長がおっしゃってくれた目的がありますが、その目的がどのように実現されているのか、区民に対してどういう効果があったのかというのは、何で調べているのか。調査しているとか、どこで判断をしているのかちょっとわからないので、その辺について教えてください。","respondent":"工藤環境課長","answer":"それでいただいたご意見を私どもも一覧にしまして、また次年度にやるときにはその一覧の中で検討をして、レベルアップをしていくという仕組みになっております。","voiceIndex":9,"id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"出店者からの意見はわかるんですけれども、来てくれる区民のほうの効果はどうなんでしょうかということと、組織になってしまうんですけれども、環境課が主体でなさっているとは思うんですけれど、特に建設委員会にも出ている住宅課とも、エコで何かできることなどが出てくるのではないか。この２点を伺います。","respondent":"工藤環境課長","answer":"ご質問がありました住宅課との連携も、事業の施策で必要になってきます。その部分に関しましては、今回太陽エネルギー見本市というものを同時に開催しますので、その中でブースを出していきながら、区役所一体となってＰＲをしていくという方針で考えております。","voiceIndex":11,"id":"exchange-003"},{"speaker":"武内委員","kind":"質問","question":"今、太陽エネルギー見本市のお話が出たのでお聞きしますが、たしか去年は単独でやられたんですよね。あれは単独でやっていたのでしようがないのでしょうけれど、今年は連携ということで、せっかくＥＣＯフェスティバルをやるんだから一緒にやろうというのはいいのかなと思うんですけれど、去年より小規模になっちゃうことについて何か工夫とかがあるのかどうか教えてください。","respondent":"工藤環境課長","answer":"２点目の来年度以降の見通しですけれど、今回ＥＣＯフェスティバルと同時開催した中で、来年度以降はまたいろいろと考えていきたいと考えております。","voiceIndex":13,"id":"exchange-004"},{"speaker":"武内委員","kind":"質問・要望","question":"よくわかりました。時期の選定とか、なぜ一緒にやるかというのはわかりました。これは要望です。","respondent":"工藤環境課長","answer":"見本市に関しましては今回のＥＣＯフェスティバルとの同時開催ということで終わるわけですけれど、私どもの環境学習講座という中で、小さな太陽光パネルを使って工作教室をやったり、そういった新しい企画も行ってまいりますので、太陽エネルギー。","voiceIndex":15,"id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"教えてもらいたいんですけれど、さっき藤原委員の質問に対する答弁でアンケートの話がありましたけれども、そのアンケートというのは、いわゆるその年にやったＥＣＯフェスティバルに対するアンケートという意味なんですか。","respondent":"工藤環境課長","answer":"アンケートに関しましては、よかったという部分ではなくて、どんなイベントを望んでいるのか、時期的にどうなのかとか、いわゆるＥＣＯフェスティバルについての感想を書いていただくような簡単な形式のものです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、この取り組みを通じて生活スタイルを見直してもらう契機にするんだと事務事業概要の中で書かれていますけれども、そういうものを積み重ねる調査というのはないんですか。","respondent":"工藤環境課長","answer":"そういったところから、結果としてどうなったかというアンケートに関しましても今後考えていきたいと考えていますけれど、今はそのような取り組みを始めたばかりですので、取り組みの一歩を始めたということでご了承いただきたいと考えています。","voiceIndex":19,"id":"exchange-007"}]},{"id":"topic-02","title":"２の放置禁止区域の拡大","agenda":"２の放置禁止区域の拡大","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"警視庁から来ていただいて１カ月ということですけれども、この放置自転車ということに関しては、基本的に押さえておかないといけない点が１点あると思います。品川区における通勤・通学などの自転車等の使用に関して、品川区として基本的な考えがあると思うんですけれども、その辺は事業部長とか警視庁に戻られた前任の課長とかから、品川区の考え方について伺っていますか。","respondent":"藤木交通安全担当課長","answer":"そこで、できる限り不要不急の自転車のご利用は自粛をしていただくという観点であると聞いております。","voiceIndex":25,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"基本的には２年間かわからないですけれど、いてくださるとは思うんですけれども、ここだけは押さえていただきたいと思うのは、品川区で特筆されるのは、いわゆる電車の駅の数がある、だから基本的には歩きなさいというのが品川区の基本的な姿勢だということを、今日はお休みですけれども岩田事業部長がいろいろな答弁の中でお話しされています。","respondent":"藤木交通安全担当課長","answer":"今、委員のご指摘にございましたとおり、条例等にもそのように明記されておりますので、その点を踏まえまして今後のいろいろな施策、事業に生かしていきたいと考えているところです。","voiceIndex":27,"id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"理由のところでちょっとお聞きしたいんだけれども、放置禁止区域外のところで放置自転車が発生していると考える理由と、３点目の有料駐輪場の新設・増設に伴うものというのはどういう意味合いなのか、ちょっとよくわからないので教えてもらえますか。","respondent":"藤木交通安全担当課長","answer":"１点目の放置禁止区域外の放置自転車の発生ですけれど、大井町駅周辺ですと、警備員の方ですとかシルバー人材センターの放置自転車の指導員、あるいはホームページでの周知等により、大体、自転車を利用されている方が、ここまでぐらいだったら。","voiceIndex":29,"id":"exchange-010"},{"speaker":"菊地委員","kind":"意見","question":"区はこれまで駐輪場を有料化して整備して、それぞれ置くところを決めて、放置自転車は実質上少なくなったと言ってきているんですよね。だけどここに来て、ほとんど有料化されてきた現状の中で改めてこうやって言われると、では、今まで言っていたのは一体何なのという感じがするんですけれども、もう少しその辺を出していただけますか。","respondent":"藤木交通安全担当課長","answer":"中には要望書などを出していただいた町会などもあったんですけれど、このような要望がある中で特に問題があるのではないか、実際に車の通行に支障が出るのではないかというところにつきまして指定させていただいたところです。","voiceIndex":31,"id":"exchange-011"},{"speaker":"菊地委員","kind":"質問・要望","question":"ただ、有料化をずっと続けてきたことによって駐輪台数そのものも、従来無料のときには入れるだけ入れていたのが、有料化されてこれだけの台数を管理しますよということになって、これまで実質入っていた台数よりも整備することで台数は少なくなるけれども、放置自転車は基本的に発生していませんよと言われてきたのが、ここに来て。","respondent":"藤木交通安全担当課長","answer":"したがいまして今後もいろいろと指導、啓発関係には力を入れまして、完全にクリアするのは非常に難しいところだとは思いますけれど、少しでも台数を減らそうと、今回新たに区域を設定したです。","voiceIndex":33,"id":"exchange-012"},{"speaker":"菊地委員","kind":"質問","question":"駐輪場が有料化されてきて、１００％になっていない駐輪場もあるというのももちろん聞いています。やはりその辺の根本を考えていかないと、実質的には改善されない話なのではないかと思うんですね。もしそのことで答弁があればお願いします。","respondent":"藤木交通安全担当課長","answer":"昨年１２月にも利用者の方に、それぞれの駐輪場でアンケートもとったりしておりまして、料金体系はどうだとか、あなたにとって安いか高いかとか、いろいろと調査を進めているところです。","voiceIndex":35,"id":"exchange-013"},{"speaker":"武内委員","kind":"質問","question":"今ちょっと料金の話が出ましたが、去年ですか、この建設委員会だったか忘れたんですが、時間貸しのところの料金設定を管理会社が検討しているというような答弁をいただいたことがありました。それは、もしわかればどうなっているのか教えてください。逆に通報とかない限りはそのままなのか。その辺のルールみたいな原則があったら教えてください。","respondent":"藤田水とみどりの課長、藤木交通安全担当課長","answer":"ただ区営の駐輪場で今までやっていないというのは、地元のお店の関係、商店街であるとかさまざまな関係がありますので、指定管理者がいろいろ検討する中で、区の意見の調整等も今後十分に行いながら。放置禁止区域外につきましても、現行の条例でも撤去することは可能でございまして、交通の妨害となっているのではないかという場合は警告札をつけて、７日程度たったら撤去する。","voiceIndex":37,"id":"exchange-014"},{"speaker":"武内委員","kind":"質問","question":"前段のほうは、では引き続きそういう方向に行く可能性はあるということですね。立ち消えになっているということではないですね。わかりました。そうするとやはり、おそらく札をつけていただいてある程度の期間は様子を見て、それでもという場合は撤去ということになるんでしょうか。その辺はケース・バイ・ケースということでいいんでしょうか。","respondent":"藤木交通安全担当課長","answer":"ケース・バイ・ケースですけれども、もちろんごみのような自転車であれば即時に撤去していることもありますが、原則としてはまず警告をして、撤去するというのが現状です。","voiceIndex":40,"id":"exchange-015"},{"speaker":"武内委員","kind":"質問・要望","question":"要望ですけれど、もちろん全部持っていってしまえばいいかというと、そうも言えないし、かといってどこまでというのは判断が難しいと思うんですけれど、特に地元とか地域の苦情が多いところはやはり思い切って、あまり長引かせずに撤去することも必要なのかなという状況もありますので、それは要望でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-016"},{"speaker":"市川委員","kind":"質問","question":"ここが禁止エリアになりましたということは、区民の方たちにどのように周知するのでしょうか。","respondent":"藤木交通安全担当課長","answer":"自治体によっては駅から半径２００ｍとか３００ｍとかという決まりがあるところもあるんですが、品川区の場合は、交通の妨害となっていれば区長が放置禁止区域を設定できるということで、現行のものも非常にわかりづらいかなという面も一部にはあるんですけれど。","voiceIndex":43,"id":"exchange-017"},{"speaker":"市川委員","kind":"質問","question":"そうなったとき、またエリアを拡大して撤去していくということを繰り返していくのか、違法駐輪については品川区はどういう考え方を持っているのか、質問したいと思います。","respondent":"藤田水とみどりの課長","answer":"そういう考え方の中では、自転車の量がこれからどんどん増えていき、区内全域を放置禁止区域にするということではなく、これまでと継続する形で駐輪場の整備、指導啓発、それから撤去活動という３本柱を、これからも充実して進めていくべきと考えています。","voiceIndex":45,"id":"exchange-018"},{"speaker":"市川委員","kind":"質問・要望","question":"そういう転換がないと、自転車を撤去することにずっとなっていくのではないかと思うんです。今は地下の駐輪場を検討しているという報告も、品川区ではないですけれど研究している区もあるとかいろいろ聞きますので、ぜひ将来的なことを考えて、品川区でもそういう駐輪場の整備についても検討していただきたいと思うんですけれど、その辺はどんなお考えでしょうか。","respondent":"藤田水とみどりの課長","answer":"可能な場所にはそういった駐輪場を考えていくことも必要だとは思いますが、現状の中ではなかなかそういった場所もございませんので、駐輪場の整備、指導啓発、撤去というやはり３本柱をあわせ持って進めていくことが、放置自転車対策の基本だと考えておりますので。","voiceIndex":47,"id":"exchange-019"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"無理です。あそこに入りません。ですので、その五反田についての考え方を教えていただきたいというのが１点です。ここ５年ぐらいで自転車の使い方は大きく変わってきているように感じるんですけれども、最近の調査でなければまた新たに、自転車がどういった使われ方をしているのか、もう一度調べ直す必要があるのではないかと思うんですがいかがでしょうか。その２点です。","respondent":"藤田水とみどりの課長","answer":"ただ、利用の実態についてはいろいろな場面で調査していくことが大切だと思いますので、所管といろいろ調整する中で、調査する方法があるのか、調査する場面があるのか、いろいろな形の中で今後も検討していかなければいけないと考えています。","voiceIndex":49,"id":"exchange-020"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"１点目の特に五反田に関してですけれども、行政の不作為とまで言ったら申しわけないんですけれども、結果的に必要な駐輪場を用意できていない。そうすると、利用者の意識が低いといったことだけではなくて駐輪場が用意できなくてごめんねという気持ちも、行政側にあってしかるべきだと思うんですね。要望です。それから２つ目の調査ですけれども、駅によって相当実態が違うと思います。これも要望です。","respondent":"齋藤道路公園課長","answer":"こういう命題です。今後どういう形で自転車の台数を抑制するか、あるいは活用できるかというのは、長い、重いテーマでありますので、引き続き検討させていただきたいと思います。","voiceIndex":51,"id":"exchange-021"},{"speaker":"原委員","kind":"質問","question":"抑止の効果は行政が頑張っておられるということがわかったのでいいのかなと思ったんですけれど、今、副委員長からお話があったのでそれに関連して言うと、隣接区との関係。ですからＪＲだったり東京都だったりすると思うんです。ですから隣接区および組合関係、再開発エリア、当然敷地の関係があるので大手企業とか中堅企業との連携、その辺についてお教えいただければと思います。","respondent":"藤木交通安全担当課長、片田防災まちづくり事業部長","answer":"再開発等につきましても、いろいろな計画が持ち込まれるたびに、こちらのほうでも駐輪場の設置義務などもありますし、たびたび話をする機会はありますので、同じようによりよい方向に進めるように考えていきたいと思います。ただそうは言っても近隣区との関係も、今お話をいただきましたような目黒区あるいは大田区との関係もございまして、その利用実態がどういう状況で、区民だけではなく他区の区民の方もご利用されているわけですから。","voiceIndex":53,"id":"exchange-022"}]},{"id":"topic-03","title":"３の陶器・ガラス・金属ごみの収集回数変更に伴うモデル収集","agenda":"３の陶器・ガラス・金属ごみの収集回数変更に伴うモデル収集","exchanges":[{"speaker":"武内委員","kind":"質問","question":"最近はあまり私は直接聞いていないんですけれど、例えばそういう実態は、これが減ったというのはわかったんですけれど、燃やすほうが逆に増えたということについては、あるいは収集を増やしたほうがいいのかどうかという検討はされているんでしょうか。","respondent":"太田品川区清掃事務所長","answer":"しかしながら、それでは、燃やすごみの収集回数をどうするかということについては、現在のところではそこまでの量にはなっていないだろうと認識しています。","voiceIndex":62,"id":"exchange-023"},{"speaker":"原委員","kind":"質問・要望","question":"やはりこの分別ごみが４分の１になったということは、非常に地道な歩みをされてきた努力の成果だと私は認識しております。実際に２３区の中では分別されていないエリアもあるわけですよね。それから先ほどの再利用の件もわかります。そこで聞かせていただきたいのはまず１点、モデル地区の２カ所はなぜここに設定したかということ。始めたあとの問題ですが、その辺のことを教えてください。","respondent":"太田品川区清掃事務所長","answer":"２点目の今後のスケジュールということでよろしいかと思うんですが、私どもは基本的に月２回の収集で十分対応ができると思ってありますが、品川区の特徴は、燃やすごみとこの陶器・ガラス・金属ごみについては各戸収集を実施していますので。","voiceIndex":64,"id":"exchange-024"},{"speaker":"原委員","kind":"確認","question":"確認と質問ですが、理解しました。モデル地区ということでこの２カ所になったということですが、品川区はそれこそ住商工がまざっているものですから、地域的に回収方法が難しいのもよくわかるんですね。要は、個人のごみと、企業関係だけど個人みたいでよくわからない、その境の部分はなかなか難しいと思うんですけれど、もしお考えがありましたら教えていただけますか。","respondent":"太田品川区清掃事務所長","answer":"一律にどうこうということではなく、出ているごみの内容といいますか、それに応じて協力をお願いしています。","voiceIndex":66,"id":"exchange-025"},{"speaker":"原委員","kind":"質問・要望","question":"これは最後に要望ですけれども、非常に現場が苦労されているということはしみじみ感じますので、その辺を特に加味して、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-026"},{"speaker":"藤原委員","kind":"確認","question":"確認ですが、４分の１程度に減ったというのは、平成２０年１０月からそれまで分別していたごみも分別しないで可燃ごみと一緒でいいですよという形にしたから、必然的にこの陶器・ガラス・金属ごみという物が４分の１になりましたよということでいいんでしょうか。","respondent":"太田品川区清掃事務所長","answer":"本件についてはくどいようですが資源化した上で、リサイクルできない物は燃やすごみということですから、旧不燃ごみで出ていた物が資源あるいは燃やすごみへ当然行くわけですから、その結果として減ったです。","voiceIndex":69,"id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"ということは、全体の量も減っているかもしれませんけれども、先ほど武内委員からもお話が出ていましたけれど残りの４分の３は、ごみ全体という意味では減っているかもしれないけれども、４分の３はどこかで増えているわけですよね。この４分の３がどこに行ったのかというのを改めて教えていただけますか。","respondent":"太田品川区清掃事務所長","answer":"資源の部分でいいますと、平成２１年度でプラスチック製容器包装は約１,０７０ｔほど収集しています。燃やすごみについては、平成２０年度が約６万６,６００ｔだったのが、約７万１,７００ｔということで５，０００ｔほど増えているです。","voiceIndex":71,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"ということは、この施策は理にかなっているんですね。４分の１しか出ないから毎週だったのを月２回にしますよというのはいいんですけれど、そうすると、毎週収集していたのを月２回モデル地区でやって、よければ全区で展開されていくと思うんですが、月２回にするということは、やらなくなった週は何をするんですか。それとも休ませるんですか。","respondent":"太田品川区清掃事務所長","answer":"これが週１回から月２回になりますと当然稼働状況は減りますが、全体のごみ量が確定しますと、通常８月ぐらいから翌年度の作業計画をつくってまいります。","voiceIndex":73,"id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"単純に考えると、全体の仕事量としてはいろいろなことを精査してバランスをとっていくということですから、全体を考えれば仕事量という意味では変わらないということですね。回数は減るけれども、仕事量で言えば変わらないということなんですね。","respondent":"太田品川区清掃事務所長","answer":"これが何台というのは今申し上げられませんが、そのことに伴って台数が減れば１台の収集エリアが当然広がるわけですから、そういう意味では稼働の範囲、状況は変わらなくなるということでご理解いただければと思います。","voiceIndex":75,"id":"exchange-030"},{"speaker":"市川委員","kind":"質問","question":"現状のことをお聞きしたいんですけれど、陶器・ガラス・金属ごみの収集を行っていて、指導に当たるような例というのはあるかどうか、お聞きいたします。","respondent":"太田品川区清掃事務所長","answer":"量というよりは分け方の部分でお願いをしているんですが、中には一部、他の金属ごみ等と一緒になっているケースがたまにあるという程度かと思います。","voiceIndex":77,"id":"exchange-031"},{"speaker":"市川委員","kind":"質問","question":"そういうときは出されたごみに何か、「これは回収できません」とか何か貼っていくような対策をとっておられるんですか。","respondent":"太田品川区清掃事務所長","answer":"ご指摘のとおり、不適切な出し方をされていれば、基本的には各戸収集ですから、排出場所がわかるところについては訪ねて、いらっしゃれば状況を説明して、分別の仕方をお話しして協力を求めます。","voiceIndex":79,"id":"exchange-032"},{"speaker":"市川委員","kind":"質問","question":"もう１点お聞きしたいんですけれども、モデル地区に５月下旬から６月中旬にかけて職員が回りまして周知を図っていくということですが、この職員は訪問をして何をするのか。収集日が変わりましたというお知らせをするために訪問されるのか、この訪問の内容というか、どういうことを実際にするのか教えてください。","respondent":"太田品川区清掃事務所長","answer":"基本的には、先ほど申し上げましたように収集回数が変更になるということで、具体的な月２回の曜日を、訪問する際には別途簡単な１枚のチラシを用意して、それをお渡ししながら、例えば第１・第３土曜日になります、あるいは第１・第３月曜日になります。","voiceIndex":81,"id":"exchange-033"},{"speaker":"市川委員","kind":"質問・要望","question":"収集日が変わるというお知らせをされるということですけれども、ぜひこういう機会に、まだプラスチック製容器包装が燃やすごみに入っていたり、ペットボトルがまざっていたりということがあると聞いておりますので、この機会にそういう品川区の分別収集の考え方をきちんとお知らせできればと思います。これは要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-034"},{"speaker":"阿部副委員長","kind":"質問","question":"広い家であればいいんでしょうけれど、年間で何度もあることではないので、第１・第３・第５とかにはならないものなんですか。３週間同じごみを置いておくのはちょっと勘弁してくれという気持ちもないではない、モデル地区の方はそんなことおっしゃらないのかもしれないですけれど、本音としてはそういう気持ちがありますが、そういうご検討はされたのでしょうか。","respondent":"太田品川区清掃事務所長","answer":"ただ量的に４分の１に減っているということを踏まえますと、月２回がいいのか、あるいは月１回でもどうかなという検討もありましたけれど、車の積載状況等を考えると、その日のうちに収集していかなければいけないということもありますので。","voiceIndex":84,"id":"exchange-035"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"そうすると、推進員の家に小さい子どもがいるかどうかわからないですけれど、子どもがいる家庭だと、割れたごみを３週間置いておくというのはちょっと嫌だなという気持ちがあります。なければ要望です。国道沿いとかちょっと入ったようなところで、どうも遠隔地から車で通勤されている方が、我が家のごみをその辺のごみが出ているところに一緒に置いていって困っているということは、区には特にないですか。","respondent":"太田品川区清掃事務所長","answer":"１点目の問題は、そういう部分も私どもでも当然認識はしていますけれども、やはり一方では効率的な収集体制も考えていかなければならないということもありますので、モデル実施等を通してみて、そういった声も参考にしていきたいとは思っています。","voiceIndex":86,"id":"exchange-036"}]},{"id":"topic-04","title":"４の区民住宅（あき家）入居予定者登録募集","agenda":"４の区民住宅（あき家）入居予定者登録募集","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"この募集のパンフレットはどのぐらい印刷するのか。区で印刷する部数、それとできたらその金額と、どのぐらい配られないで余るのでしょうか。","respondent":"柏原住宅担当課長","answer":"印刷の部数ですが、手元に細かい数字がないのですが、区民住宅につきましては約５００冊子ぐらいです。細かい数字はまた後ほどご報告いたしますけれど、大体８割以上ははける状況になってあります。印刷の単価もちょっと今手元にないものですから、後ほどご報告します。","voiceIndex":92,"id":"exchange-037"},{"speaker":"武内委員","kind":"意見","question":"ちょっと関連しますが、今回２０団地で４２６戸分の募集で５００冊ということですけれど、４２６戸を募集するならもうちょっと多く印刷するのかなと思ったんですけれど、その辺はどうなのか。","respondent":"柏原住宅担当課長","answer":"募集の正式な数が今手元にないのですが、４２６戸というのは管理戸数でございまして、実際はこの戸数分ということではございません。実際はその団地ごとに応募されるんですけれども、それがどのぐらいいらっしゃるかというのを見ながら募集の冊子数を印刷するです。","voiceIndex":97,"id":"exchange-038"}]},{"id":"topic-05","title":"５の平成２２年度水防訓練参加組織および実施内容の報告","agenda":"５の平成２２年度水防訓練参加組織および実施内容の報告","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"２枚目の地図ですが、西大井一丁目の２ですか。お気づきでないかもしれないですけれど、今はＪタワーですよね。品川区の、いわゆる防災とかまちづくりとか土木関係の部署の資料で、何年前の住宅地図を使っているんでしょうか。どこからこの地図を持ってきて、また区のこういう資料というのはどうなっているんでしょうか。","respondent":"佐藤防災安全担当課長","answer":"大変申しわけありません。この地図については例年の資料をそのままつけさせていただいたので、今後につきましては最新の地図をつけるように注意をしてまいりたいと思います。大変申しわけありませんでした。","voiceIndex":103,"id":"exchange-039"},{"speaker":"藤原委員","kind":"意見","question":"部長、どう思いますか。区のいわゆる建設、土木、まちづくりをしている部署が。Ｊタワーができて何年たちますか。","respondent":"片田防災まちづくり事業部長","answer":"いろいろな過去の事例とかそういうものを使い回す上で、所管のほうでは新しい地図がなかったところもあろうかと考えていますが、同じ部の中ですので、きちっとした形で適正なもの、新しいものを、使用していきたいと思いますので、よろしくお願いしたいと思います。","voiceIndex":105,"id":"exchange-040"}]},{"id":"topic-06","title":"６の橋梁長寿命化修繕計画","agenda":"６の橋梁長寿命化修繕計画","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"今ご説明いただいた最後の部分の財源確保ですけれども、国土交通省からの財源ということで補助のお金は、今の時点で何か決まっているものがあるのでしょうか。","respondent":"藤橋都市整備下水道課長","answer":"社会資本整備総合交付金に変わっても、この２分の１の仕組みは変わらない予定になっておりまして、来年度もできるだけ点検と修繕にかかる費用の２分の１につきましては、国の補助をいただけるように取り組むです。","voiceIndex":111,"id":"exchange-041"},{"speaker":"藤原委員","kind":"確認","question":"確認ですけれども、２分の１は国の補助でこの事業ができると考えて間違いはないということですね。","respondent":"藤橋都市整備下水道課長","answer":"私どもはそういう気持ちなんですけれども、最終的に国で認めてもらえるかどうかは国土交通省の判断になります。","voiceIndex":113,"id":"exchange-042"},{"speaker":"藤原委員","kind":"質問","question":"ちょっと話が違ってきてしまいますよね。今までは２分の１が、点検についても直すことに関してもお金が出ていたんですよね、平成２１年度は。だから、これはもらうしかないじゃないですか。そのための努力というか、課長の答弁だと気持ちをどのように伝えていくか、そこに重要性があると思うんですけれども、この辺についてはどう考えていらっしゃるのか。","respondent":"藤橋都市整備下水道課長","answer":"説明がちょっと至らないところがあったんですけれども、昨年度まで区が橋梁の点検をしたり補修をする場合は、すべて区の持ち出しでやっておりました。これまで国の補助をもらってやったという事例はございません。","voiceIndex":115,"id":"exchange-043"},{"speaker":"藤原委員","kind":"質問・要望","question":"この事業でなくて、例えば２３区初となっております事業、東京都と共同で下水道管の耐震化をやっていくという形で、東京都からうまくお金を引き出したじゃないですか。２分の１って大きいですからね。その辺をどうにか、課長がいてくださる期間に決めていっていただきたいと思うんですが、その辺についてはいかがでしょうか。","respondent":"藤橋都市整備下水道課長","answer":"２３区の中でもこの計画は早くつくっている状況です。東京都にも昨年度から、来年度以降この計画をつくって事業化しますよという話をしておりますので、財源確保は強力に推し進めていくということで考えてあります。","voiceIndex":117,"id":"exchange-044"},{"speaker":"武内委員","kind":"質問","question":"基本的なところだけ教えてください。区が管理している橋は７０ということだったので、これは全部区の所有物ということでいいのか。それから、国とか都の橋については当然国とか都がお金を出すと思うんですけれど、その辺の考え方と、それと国や都では今回品川区が考えているような対処療法型でない予防保全型のほうに、考え方として同じような方向で計画を立てられているのかどうか。それを教えてください。","respondent":"藤橋都市整備下水道課長","answer":"都道につきましては既に東京都が修繕計画を策定済みですので、この計画に基づいて個別に対応していくというふうに聞いております。","voiceIndex":119,"id":"exchange-045"},{"speaker":"武内委員","kind":"質問","question":"わかりました。それと、区の７０橋梁については定期点検はこれからやるということなんですか。","respondent":"藤橋都市整備下水道課長","answer":"点検につきましては平成２０年度に一度全部の橋梁を点検しています。今後は５年ごとに、平成２５年を目途にもう１回、７０橋梁すべてを点検をしていく、それを５年ごとに同じことを繰り返すというスタンスです。","voiceIndex":121,"id":"exchange-046"},{"speaker":"武内委員","kind":"質問","question":"そうすると、橋梁の場合は専門的な角度で点検をしなければいけないのかなと思うんですけれど、区のスタッフだけで対応するのか、どこかに委託してやっているということなんですか。","respondent":"藤橋都市整備下水道課長","answer":"いわゆる法律的なやり方でやるということになっております。その点検につきましては、橋梁点検の専門的なノウハウを持っている民間のコンサルタント業者に委託して実施いたしまして、今後についても専門業者に委託して実施するものです。","voiceIndex":123,"id":"exchange-047"},{"speaker":"菊地委員","kind":"質問","question":"１つだけ聞きたいんですけれども、この中で橋梁の寿命が平均５０年から６０年と書かれていますよね。この長寿命化そのものは必要なことだと思うんですけれど、要は途中、途中でこれまで以上にコストをかけていきますよという話ですよね。最終的にどうかは別として、途中でコストをかけましょうと。そうすると、それによって平均５０年、６０年と言われる寿命を実際にどこまで延ばそうという話なんでしょうか。","respondent":"藤橋都市整備下水道課長","answer":"区では、何年もたせましょうというところまで明確に言える技術的なものは今現在ないので、データもないので、当面、５０年以上たっている橋梁もあるんですけれども、今よりも小まめに修繕することで長もちするという予測までは現在できましたので。","voiceIndex":125,"id":"exchange-048"},{"speaker":"菊地委員","kind":"意見","question":"それはもちろん確定的にこれをやると、何年後にかけ替えしなければならないのが何十年もつとか、そこまで出るのかどうかよくわかりませんけれども、区としてもそういうデータを持った上で一つ一つの橋梁に対して配分していくということだと思うんですけれど、そうすると当然目標として、これだけコストをかけるんだからこれだけ増しますよみたいな、何かそういうものがないと。","respondent":"藤橋都市整備下水道課長","answer":"計画の１６ページ、１７ページをお開きいただけますか。１７ページの先ほどご説明しました図－９です。品川区の計画は何年という目標ではなくて、縦軸をご覧いただきたいんですけれど、アルファベットでＡ、Ｂ、Ｃ、Ｅ１、Ｅ２と書いてあります。","voiceIndex":127,"id":"exchange-049"},{"speaker":"菊地委員","kind":"意見","question":"そういう意味であれば、Ｃに落ちる前に手をかければ、Ｃまで落ちるのが何年延びますよという目算のもとにやるんだと思うんですね。そうすると、この橋梁はＣからＥ１、Ｅ２に行くまでにこれだけ延びますよというのは当然あるんだと思うんですね。そこがちょっと、ここまでの経過は持ち合わせていませんと言われても、それじゃあコストはどうなるのという話が出てくると思うんですが。","respondent":"片田防災まちづくり事業部長","answer":"なおかつ長寿命化することによって環境にも十分配慮したものになるだろうということを考えていくということなので、それをやったからあと何年延びるんだということは、ここで説明できるようなものではありません。","voiceIndex":129,"id":"exchange-050"},{"speaker":"原委員","kind":"質問・要望","question":"この７０橋梁の一番大きいというか長い橋はどのぐらいなのか。もしわかればでいいんですけれど、教えていただきたい。ですから、藤原委員からもあったようにしっかり２分の１は確保しろと、私もそう思います。ただ、今までは非常にいい展開だと私は思っておりますけれども、一番長いというか規模的に大きい橋はどのぐらいなんでしょうか。その辺をお伺いいたします。","respondent":"藤橋都市整備下水道課長","answer":"ただ現在私たちのほうで計画している中では、一番大きい勝島橋の修繕に一番にかかるかというと、そういう計画にはなっておりませんで、最終的に先ほど申しました健全度と重要度という観点から判断すると、区内には鉄道にかかる橋、それから川にかかる橋が多うありますので。","voiceIndex":131,"id":"exchange-051"},{"speaker":"原委員","kind":"質問","question":"そうすると、先ほどの１１ページですけれども、このデータをとるのは民間の専門のところというお話ですけれども、それを今度はデータとして実際につくっていく、入れ込んでいく、この作業もやはり民間なんですか。","respondent":"藤橋都市整備下水道課長","answer":"データの入れ込みについてですけれども、１８ページ、１９ページ、２０ページの帳票をご覧いただきたいんですけれども、例えば１８ページにデータの登録・管理、補修工法・費用の算定とあります。","voiceIndex":133,"id":"exchange-052"},{"speaker":"原委員","kind":"質問・要望","question":"ですから今のご答弁にあったように民間の専門家に、ある種の特殊性がありますのでそういうところをお使いになるのであれば、入力のチェックは区だよということであれば、これは橋に限ったことではないですけれど、１行間違えて全部ずれてしまったら、総合的な判断でしょうから大変なことになってしまう。実際に橋なんて中東とかに売り込んでいますから。","respondent":"藤橋都市整備下水道課長","answer":"そのため、現場を預かる立場といたしましては、技術力の維持、向上に向けて、今現在品川区では技術会議というものを設定しまして、それによる人材育成の取り組みを実施しておりますけれども、そのほかにもやはり日常業務の中できちんと。","voiceIndex":135,"id":"exchange-053"},{"speaker":"阿部副委員長","kind":"質問","question":"今のことと関連するところですけれど、橋梁担当の職員の方がいらっしゃると思うんですが、その方は、業者の方が現場で点検されるのにある程度立ち会ったりということもあるんでしょうか。それとも出てきた数字や書面だけで総合的判断ということになるんですか。ちょっと細かいことですが教えてください。","respondent":"藤橋都市整備下水道課長","answer":"すべての橋梁の点検に立ち会うことは平成２０年度の点検のときもしておりませんでしたが、主だった橋、代表的な橋につきましては立ち会うことをいたしました。特徴的な損傷があったりする場合ももちろん立ち会って、実際に見ることはしています。","voiceIndex":137,"id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3974#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":37466,"voices":142}},{"id":"h22-20100510-9","meetingId":"h22-cm05","date":"2010年5月10日","dateIso":"2010-05-10","committee":"文教委員会","time":"午後１時０２分～午後４時４９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"伺いたいのは、処理の日程の概要の説明がありましたけれども、教科書採択については、だれが決めるのか、そして決める基準は何なのか、この仕組み上からのこともあるでしょうけれども、そこをご説明いただけますか。","respondent":"冠木指導課長","answer":"教科書の採択につきましては、教育委員会で採択をしていただく。その基準については、採択の基準等の要綱を定めまして、その要綱に基づいて決定をしていただくという流れになってあります。","voiceIndex":7,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は、現場の教員の意向が反映する、また、特別展示や法定展示、地域の方々、広く多くの区民や保護者の方がここで参加をすることができるわけですけれども、そういう広い参加を保証していく、そういう仕組みが必要だと思うんですけれども、いかがでしょうか。","respondent":"冠木指導課長","answer":"今回の採択の要綱については、まだ最終的に決定をしてございませんけれども、考え方としては、内容、それから構成等で品川区の教育を進めていくのにふさわしいものというようなところで要綱は定めてまいりたいと思ってあります。","voiceIndex":9,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"現場の中で採用権というか、そういう形で明記されているのかということと、それから、展示会でアンケートを実施するということなんですが、このアンケートの利用方法というんですか、意見をいただいて、今後どういうふうに利用しようとされているのかを教えてください。","respondent":"冠木指導課長","answer":"特別支援学級に通うお子さんの教科用図書ですけれども、先ほどもちょっと説明させていただきましたが、まず第一には、通常の学級でも使っている教科書が使えるかどうか。","voiceIndex":11,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"特別支援学級の使用図書、これはリストを提示して、これを使いましょうという判断というのは、調査研究会がするんですか。検討委員会がするんですか。それとも特別支援学級の担任の先生が決めていいんでしょうかということなんです。どういう形で、せっかくご意見をいただくものですから、それをある程度有効的に活用していただくことが必要かと思うんですが、いかがでしょうか。","respondent":"冠木指導課長","answer":"それに基づいて決定をしてまいるということになります。そういったご意見を校長、それから設置学級の担任の先生からなる委員会で検討いたしまして、決定をして、私どもの教育委員会のほうに出していただいて、そこで最終的に決定するという流れになってあります。","voiceIndex":13,"id":"exchange-004"},{"speaker":"井上委員","kind":"質問","question":"ちょっとこの採択のところからは外れてしまうかもしれないんですが、教科書を使うというときに、普通学級とかでも弱視の子とか、いろいろそういう子どもたちがいて、今、点字の教科書とか、拡大の教科書とかをＮＰＯの人たちが担って出していたりとか、そういう子どもに合った教科書を提供しようということがありますけれども、品川区の場合には、そういうところの、以前だと、点字のところでは。","respondent":"冠木指導課長","answer":"そういった事例が生じることは十分に可能性としてありますので、そういった場合には、都立の特別支援学校の視覚障害の部分と、コーディネーター等の交流の中でどんな教材が必要かというようなことを考えていったり、あるいは、弱視の特別支援学級のある区がありますので。","voiceIndex":15,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"今の対応というのは、前向きに品川区として対応してくださるというふうに伺ってよろしいのでしょうか。","respondent":"冠木指導課長","answer":"いずれにいたしましても、特別支援学級にお通いになるのか、通常学級にお通いになるのか、それとも特別支援学校が適切なのかというようなところの就学相談というようなところにまずは私どもの相談の機会がありますので、これはどの障害種でも同じですけれども。","voiceIndex":17,"id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"この原則４年というのが崩れる場合、こういう学習指導要領が変更になった場合は当然あると思うんですけれども、それ以外に何かほかの要因で早めに採択をする、そういうようなことは発生するものなのかどうかというところを教えていただければと思います。","respondent":"冠木指導課長","answer":"教科書採択については、今、委員のお話の４年というのは、これは法の定めでございまして、原則は４年ごとにということになってまいります。今回のように学習指導要領が改訂された場合には、当然これは教科書も変わりますので、今回のような改訂ということになります。","voiceIndex":19,"id":"exchange-007"},{"speaker":"浅野委員","kind":"質問","question":"実際には、もう少し時間がたってから来年度の教科書を使う、去年ですと８月にそういう報告があったかと思うんですけれども、そのときはやはり来年度使う教科書をどうするかということについての報告はされる、そういうような流れになっているのかなというふうに思うんですけれども、ちょっとそこの流れをもう一度教えていただければと思います。","respondent":"冠木指導課長","answer":"中学校につきましては、４年ごとの採択という基本的な形で行きますと、前回の採択が昨年度でございました。","voiceIndex":21,"id":"exchange-008"},{"speaker":"林副委員長","kind":"確認","question":"確認をしたいんだけれども、品川区で教育改革をして品川区の小中一貫の指導要領があって、ここに載っている１番の小学校の使用教科用図書というものが、２番の表の中の４月２７日、採択についてのいろいろな概要が出てきているわけだけれども、品川区という自治体の中で、この教科書を採択していくというのは、よその自治体の教育委員会が採択していくのと違う点があったら教えてください。","respondent":"冠木指導課長","answer":"品川区では、小中一貫教育要領をつくりまして、小中一貫教育を推進していますので、今回、採択する教科書におきましても、他の自治体とは違って、小中一貫教育を推進していくにふさわしい教科書というようなところでの採択になってまいります。","voiceIndex":23,"id":"exchange-009"},{"speaker":"林副委員長","kind":"質問","question":"そうすると、日本の文部科学省というところが品川区のそういう他の自治体と違うんだということを、いわゆるこれは法定で決められているものなので、そうすると、品川の小中一貫教育というのをはっきりともう文部科学省でも認めているというふうにとっていいんですか。","respondent":"冠木指導課長","answer":"この制度につきましては、ここ３年間と思ってあります。その前は特区ということでやらせていただいておりましたけれども、文部科学省の教育課程特例校ということで私ども申請いたしまして、それを認めていただいているです。","voiceIndex":25,"id":"exchange-010"},{"speaker":"林副委員長","kind":"質問","question":"そうすると、ちょっとへそが曲がっているもので聞き方がいけなかったら注意をしてください。１番の（１）の教科書の区別というか、種別がずらっと国語から保健まで並んでいるんだけれども、市民科という科目に入ってくる教科書、それからもう１つは英語、小学校用、小学生用というか、英語というのは、指導要領にもきちんとあるわけで、それが入っていないというのは何か意味があるんですか。","respondent":"和氣小中一貫教育担当課長","answer":"これを追加して使っているです。さらに、英語科についてはそのまま使う、算数についてもそのまま使うということで、継続して使うということで検討しています。ですから、検定教科書はあくまでも検定教科書で、国の学習指導要領に合わせてつくっております。","voiceIndex":27,"id":"exchange-011"},{"speaker":"林副委員長","kind":"質問","question":"ちょっと回転が鈍くなっているのであれなんだけれども、そうすると、ここに書いてあるのは品川区用の、区用のと言ったらちょっと語弊があるのかな、品川区としての教科書を選定していくのに、今言われたように、市民科とか英語とかということについて、なぜ載せないんですか。","respondent":"若月教育長","answer":"今回は、法に基づいた教科書の採択をするという作業ですから、当然そこには市民科とか英語といったようなものは、当然本区ではつくりますけれども、しかし、この教科書採択の俎上には乗ってこない、こういうことです。","voiceIndex":29,"id":"exchange-012"},{"speaker":"林副委員長","kind":"確認","question":"そうすると、先ほどの前半で確認をすると、特例として小中一貫教育、市民科も英語も含めて小中一貫教育というのは、特例で、品川の場合はもう認められているんだと言いながらも、いわゆる指導要領に入ってこない勉強については、教科書は国では定めなくて、品川区は品川区として考える中で決めていっていいですよという、これも特例、指導要領も特例なんでしょうけれども、特例としますよということを。","respondent":"若月教育長","answer":"だから、一貫教育をうちはやりますから、場合によっては中学校の勉強の内容を小学校６年生に持ってきているものもあるんです。これは本来はその特例がなければ、それは違反になるわけです。しかし、特例を受けているから、うちはそれができるわけです。","voiceIndex":31,"id":"exchange-013"},{"speaker":"中塚委員","kind":"確認","question":"わかりやすく言うと、通信簿の中でＡ、Ｂ、Ｃだったり、１、２、３だったり、学年によってさまざまでしょうけれども、ということは、市民科や英語は教科ではないから評価の対象ではないと、そういう形になるのか確認をしたい。あわせて、特例の話があったので、特例で市民科や英語を教科にするということは可能なのか、いや、そこはだめだという縛りなのか、そこもあわせてお伺いします。","respondent":"若月教育長","answer":"１点目です。市民科とか英語といったようなものは、さっきもお話ししたように、評価、要するに、テストをやったり、点数をつけたりというものでは全くないわけです。ですから、先ほど副委員長にお答えをしたとおりであります。では、特例に基づいてそれが教科にできるか。","voiceIndex":33,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"この園別在籍状況の説明の中で、在園率とおっしゃったんですか、パーセントの話が説明としてあったんですけれども、それはどういう率なのか、いわゆる定員と在籍数で弾力化の部分をあらわす言葉なのか、在園率というのがよくわからなかったので、そこを教えていただきたいのと、あと、待機児の説明の中で、１,７７１人の中で決定に至らなかった人で、転園希望と認証の在籍の話がありましたけれども。","respondent":"吉岡保育課長、伊崎待機児童対策担当課長","answer":"在園率ですけれども、在籍児童数を定員で除したものです。その他ですけれども、こちらはあいている保育園があるのにどちらも希望されていらっしゃらないというような、自己都合で、例えば１園だけしか希望していらっしゃらない方とか。","voiceIndex":40,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"それぞれの数字の意味はわかりました。つまり、品川区は緊急対策として待機児解消策を掲げたわけでして、その評価について、改めてこの待機児解消策の目的は何なのか、そしてこの４月の結果を受けてどう評価していらっしゃるのか、今後の課題を何か考えていればそれは何なのか、評価を教えていただけますでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"今後につきましては、今年度、２園の認証保育所の誘致は確定をしておりまして、そこでの待機児の受け入れがまずできるということ、それから来年度に向けましては、既存の保育施設の活用を含めたさらなる受け入れの拡大を、今、検討しています。","voiceIndex":43,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、実感的には今年も保育園の入園は厳しかったなというのが率直な実感なんですけれども、もはや区内全域にわたっているなと思うんですけれども、保護者の方に伺うと、とりわけ五反田や大崎の地域が保育園の入園が厳しいというお話を伺いますけれども、特に入園の希望が多い地域、逆に言うと、入園希望がかなわない地域、かないにくい地域というのは。","respondent":"伊崎待機児童対策担当課長、吉岡保育課長","answer":"乳幼児の人口動向につきましては、現在、微増であるところではありますが、今後ずっと拡大していくわけではないと見込んでいることもありますので。一方、八潮地区につきましては、若干の、あくまで比較の話ですけれども、比較をすれば入園の希望はかなっているのかなということもありますので、地区によっての若干のばらつきはありますけれども。","voiceIndex":45,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"真に保育というところのご説明の中で、親族が保育ができる環境がある人や育児休暇がある方というお話がありましたけれども、ちょっと何が言いたかったのかよくわからなかったのでもう１回伺いたいんですけれども、近所というか、通える距離にお父さん、お母さんが保育ができる環境がある人は、まあまあ、ちょっと保育園はいいんじゃないか、待てるんじゃないですかという、そういう意味なのか。","respondent":"伊崎待機児童対策担当課長、吉岡保育課長","answer":"品川区の考え方といたしましては、保育に欠けるお子さんすべてを保育園で受け入れるという方針ではございません。西五反田保育園の０歳、１歳、２歳のそれぞれの申し込み、それから内定等の状況ですけれども、西五反田保育園につきましては、０歳児で申し込みをされた方が７９名、１歳児が７９名、２歳児が２８名で、０歳、１歳。","voiceIndex":48,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういう人が保育園が必要だと考えていらっしゃるのかがわからないんです。それを区の事情で区が勝手な事情で、おじいちゃん、おばあちゃんがいるなら、あなたはどうなんですかと、そこはちょっと違うんじゃないかなと思うんですけれども、そこはどう考えているのか伺いたいと思います。この状況をどう考えているんだということなんですけれども、ご説明いただきたいと思います。","respondent":"吉岡保育課長","answer":"ただいま保育を求めていらっしゃる方に対する区の考え方ということで、待機児童対策担当課長のほうからるるご説明いたしたところですけれども、ちょっと敷衍をしますと、区といたしましては。","voiceIndex":51,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"西五反田保育園の０歳児８人、１歳児３人、２歳児２人、内定者が出たわけですけれども、それぞれの最低指数というのか、点数というのか、それは幾つなのか教えていただきたい。４月に入れないから、保育園に入れない。いや、その人は認証に入っているからいいんだと、どう考えているのか伺いたいと思います。認可保育園の増設を柱に据えるべきだと思うんですけれども、いかがでしょうか。","respondent":"古川子ども未来事業部長、吉岡保育課長","answer":"児童福祉法第２４条におきましては、保育の実施基準は区市町村が持ってありますし、一義的には保育園を重視すべきであろうという考え方は当然持ってあります。各園の詳細な入園の申込状況については、今、資料を持っておりません。お許しいただきたいと思います。","voiceIndex":53,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"これはやっぱりひどいなと思います。今年についてはこれからというお話が最後にありましたけれども、一体じゃあ何が必要なのか、そこをもう１つ伺いたいと思います。私はやはり、みずからが保育園をつくっていく、認可保育園の増設で、待機児をゼロにしたいというのであれば、認可保育園の増設でなければ対応ができないということはいよいよ明らかだと思うんですけれども、そこはいかがでしょうか。","respondent":"古川子ども未来事業部長","answer":"そういう中で総合的な施策をとりながら、一人ひとりすべてのというのはなかなか難しい状況でありますから、必要性の高い、あるいは保育に欠ける要件の高い、そういう方々には、少なくとも何らかの形で対応策をとっていきたい、こういうことです。総論になります。","voiceIndex":56,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"幾つかお尋ねします。定員とは何でしょうかということ。それから２つ目は、今日の視察のところでの関連になってしまうんですが、中延保育園と西品川保育園のところですが、要は、小学校のあき教室を利用しての定員増というところによって、どのクラスがどういう形で増員をすることができたんですかということの割り振りを知りたいです。","respondent":"吉岡保育課長、伊崎待機児童対策担当課長","answer":"中延保育園と西品川保育園ですけれども、それぞれ５歳児を小学校の施設を利用して分園を設置したことによりまして、全体的にも定員を増やしているわけですけれども、結果といたしまして、中延保育園の場合は、０歳が３名、１歳が４名。学校を利用しての分園設置の話ですが、今、２園２校で実施しています。実施するに当たりまして、さまざまな事情がありますので、そういったところも含めて、今後また検討をしていくということは考えております。","voiceIndex":58,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問・要望","question":"定員の件ですが、弾力化をしてこの人数になったんですよということですね。ということは、平米数がいろいろあるわけじゃないですか。ということは、定数というふうに考え方を変えてもいいんじゃないですかと思ったんです。そういう意味では、どういう保育の方法をされているんですかと。その人数を増やしていけたというのは、どういうところで増やすことかできたのかというところを教えていただきたい。","respondent":"古川子ども未来事業部長","answer":"弾力化については、必ずしも４月１日の例えば職員の配置まで、５月、６月を最初から想定できませんので、その部分については、１年以内の中で一定の非常勤の活用でありますとか、場合によっては派遣による有資格の人の活用、さまざまな手段によって１年間の保育環境を整えていく。","voiceIndex":61,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"済みません、先ほどの質問の最後、中延保育園と西品川保育園の増やせた理由、保育の内容から考えたときに、どういう工夫をすることでこういう増員ができたのでしょうかということ、それは保育園によって違うとは思うんですけれども、考え方を教えてください。","respondent":"吉岡保育課長","answer":"保育に当たりましては、当然、人数の増えた分につきましては人員を配置していますので、その中でそれぞれ例えば９人のクラスが１２人になれば、人数が増えたなりのそれぞれのスペースを活用して。","voiceIndex":63,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"最後に１点だけお聞きします。先ほどの弾力化の件についてなんですが、この弾力化した４月１日の在籍、これがマキシマムと考えていいんですか。それとも今後、再度いろいろなことを考えた中で増えていくということもあり得るのか、そこの将来性の検討度合いも含めて、どういう感じなんでしょうか。","respondent":"古川子ども未来事業部長","answer":"当然、年度途中での退園なさる方、あるいは入園なさる方、さまざまな部分がありますけれども、園全体として持っている資源、広さ、あるいは人の手当ても今回出てきますし、今後、保育を必要とする方々をどう受けていくか、先ほどお答えしましたように。","voiceIndex":65,"id":"exchange-025"},{"speaker":"井上委員","kind":"質問・要望","question":"ちょっと数の確認なんですが、以前の審議の中で、４月１日の申し込みの中で認可保育園に入れなかった方というのは４９４人というふうに言われていたかと思うんですが、ここでは今回、４８７人の数ということなんですが、この差異が何によるものなのかというのが１点。そこのところを教えていただきたいということ。","respondent":"吉岡保育課長、伊崎待機児童対策担当課長","answer":"四百九十何人と前に話があったが４８７人になったのはなぜかということですけれども、中で申し上げましたけれども。認証保育所につきましては、４月現在で在籍をしている方の人数と比較をしますと、大体比率は同じような比率になっていると考えております。西五反田保育園の入園に至らなかった方がどういうふうになったかということについては、今現在、把握してございません。","voiceIndex":67,"id":"exchange-026"},{"speaker":"井上委員","kind":"質問","question":"もう１つ、短時間保育の件なんですけれども、これはフルタイムではなくてもニーズはあることは承知をしているんですが、実際に短時間保育と言っても、フルタイムの人がそこに待機児となっていて入っているのではないかということを思うんですけれども、そこの現状というのは、本当に短時間保育の、そういう方がそこに入れているのかどうなのか、この施策についての評価はどうなんでしょうか。","respondent":"吉岡保育課長、伊崎待機児童対策担当課長","answer":"そういう中で、一定、短時間就労であっても、保育を必要とされる方はいらっしゃるだろうという想定の中で、そういう方々に対しても一定の枠を確保して差し上げるというのが施策の目的でございまして。今の保育課長の答弁に補足をいたしますと、短時間保育室の申込条件の中に、８時間の保育時間でお迎えが間に合うという条件があります。","voiceIndex":71,"id":"exchange-027"},{"speaker":"井上委員","kind":"質問","question":"先ほどの教室を使った保育のところでも見られるんですが、やはりスペースというのは本当に重要だなというふうに思ってきているんですけれども、その中で、今回、定員を拡大した中で、定員の意味合いは本当に微妙で、今回の２０１０年の定員拡大については、弾力化でもうほとんどその部分は埋まっていたという状況が実際問題あるわけで、２０１０年の在籍人数を２００９年の定員で割り返してみると。","respondent":"吉岡保育課長","answer":"ただし、大前提になりますのが保育所の設置基準がございまして、定められております面積基準についてクリアをするというのが最低限の条件ですので、面積基準をクリアした上で必要な人員を配置して十分な保育を行うというのが区の考え方です。","voiceIndex":74,"id":"exchange-028"},{"speaker":"井上委員","kind":"質問","question":"面積基準をクリアしたというところで言えば、今回の定員拡大で、この先どういうふうな見通しを持っていらっしゃるのか、まだ拡大するキャパシティがあると考えているのか、もう今年は本当に細かい精査をした上で定員を選定したということは常々委員会でも答弁があったので、そこのところは、これでもう様子を見ていくんですよということで考えてよろしいのでしょうか。","respondent":"吉岡保育課長","answer":"というのは、先ほどお話にございましたけれども、面積基準を満たし、その中で質も落とさない保育をやっていくためということを考えたときに、ぎりぎり面積基準、本当の限界までやるのが望ましいかどうかというのはまた議論のあるところでございまして。","voiceIndex":76,"id":"exchange-029"},{"speaker":"井上委員","kind":"質問","question":"定員というところで数字を決定すれば、職員体制が当初から配置ができるということで、そうすると、人数的には大人が増えるということは、もっと密度が濃くなってしまう、過密になってしまうというところで、今回４月に定員を拡大した中で、子どものことなので、１カ月間、職員の方たちの報告とかお話で、事故について、大きな事故ではなくても、保護者の方に伺うと、今までよりも、今日はどこをぶちました。","respondent":"吉岡保育課長","answer":"どこの保育園でだれが去年に比べて多いと言っているのか私は承知しませんけれども、今のところでは私どもはそのようなことを情報としては把握してございません。今後につきましても、事故のないように、一層注意を払ってやってまいる所存です。","voiceIndex":78,"id":"exchange-030"},{"speaker":"井上委員","kind":"質問","question":"事故があったことがどうということではなくて、子どものいるところだけれども、やっぱり先ほどの園長先生のお話もあったんですけれども、思わぬトラブルというのはスペースによって起こるというのは、だれが考えても当然のことで、そういったところで変わっているのではないかということの心配に対して、どこのだれがどうだという、そういう個人的なことではないので。","respondent":"吉岡保育課長","answer":"ただし、一定いろいろな制約の中で保育をしていますので、そのためにも最低の基準というのが示されているわけで、その最低の基準をクリアしながら、その中で事故がないように、子どもたちが楽しく元気に育っていけるように保育をするのが保育園の保育士の務めでもありますし。","voiceIndex":80,"id":"exchange-031"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"確認","question":"確認だけさせてください。認証保育所、これはＢ型ですか、Ａ型ですかということが１点。それからあと、平塚小学校跡の施設なんですが、この幼保一体施設というのは、どういうタイプの幼保一体型か。それから、ちょっと今まで聞いたかもしれませんけれども、舞台がありますよね、ホールが。どういう目算があって計画されたのかなと。ここで関係ないのであればやめますので、お願いします。","respondent":"吉岡保育課長","answer":"それからあと、幼保一体施設なんですけれども、いわゆる幼保の分離型といいますか、０歳から３歳までの保育園と、４歳・５歳の幼稚園と、それから今度、第一日野のように、０歳から５歳までの保育園と、４歳・５歳の幼稚園を並立するという形で、今現在。","voiceIndex":88,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"それともう１つ、このポピンズナーサリーと小学館ですけれども、この入る建物というのは、ちょっと今日は地図を持ってきていないのでわからないんですけれども、再開発ビルのところですか。武蔵小山も小学館もそうなのかどうなのかよくわからなかったので、入るビルが何なのか教えていただきたい。","respondent":"吉岡保育課長","answer":"年齢ですけれども、東五反田のポピンズナーサリースクール東五反田については、０歳児が１０名、１歳児が１１名、２歳児が６名、３歳児が３名の合計３０名という現在の予定です。","voiceIndex":90,"id":"exchange-033"},{"speaker":"中塚委員","kind":"提案","question":"武蔵小山のほうは創業支援の中に入るということで、どちらも品川区ともかかわっている、補助金も出ている、そういう事業のところに認証保育園が入るわけですので、とりわけ五反田地域は保育園になかなか入れない状況があるということなんですけれども、この定員とか年齢について、区から何か要請なのか、要望なのか、お願いなのか、それはよくレベルはわからないですけれども。","respondent":"吉岡保育課長","answer":"区としての要望ですけれども、区としては、ある程度規模が大きいほうが、それだけ受け入れの人数が増えますのでありがたいということがございまして、そういうような方向でのお話は当然するんですけれども、ただ、いずれにしても、それぞれ実施をする場所がございまして。","voiceIndex":92,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまり、認可保育園を要望すれば、私は要望すべきだと思うんです。なぜ再開発組合に認可保育園の増設をお願いできなかったのか、それともお願いする考えもないのか、開設も建物も公共的なもの、税金が補助金として入っているものですから、区としてのスタンスがどうなのか、そこがよく見えないので、区が何を要望したのか、基本的スタンスが何なのか、そこを再度ご説明いただけますか。","respondent":"吉岡保育課長","answer":"当然、施設ができる場合につきましては、いろいろな人口圏のあり方があろうかと思います。その中で事業者が基本的にはこういう施設をつくりたいというお話ですので、その中でこの東五反田の件につきましては、認証保育所ということでお願いしたところです。","voiceIndex":94,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"やっぱり民間の認証保育所に区が、結局はお願いする姿勢すらないのかなと思うんですけれども、それでは区民要望の高い認可保育園の年齢、ここはカバーできないわけですよね。だからやっぱり私は品川区みずからが認可保育園をしっかりつくっていく、このことを柱にしない限り、保育園不足は解消しないと重ねて言いたいと思います。","respondent":"吉岡保育課長","answer":"東五反田のケースにつきましては、面積的に認可保育園を設置するには、やはりちょっと厳しい面積ということで、１８０m2前後の面積ということで聞いてありますので、やはり規模から言いますと認証保育所が適切といいますか、妥当な選択であろうかなというふうに考えております。","voiceIndex":96,"id":"exchange-036"},{"speaker":"林副委員長","kind":"質問・要望","question":"さっきから話を聞いていると、保育園の数の問題ばかり取り上げているけれども、本来、どうやって品川区の子どもを育成していくかという大事な話にまるっきり進まないで寂しい思いをしながら聞いていましたけれども、この次世代育成をこれから品川区はどういうふうに進めたいと思っている意気込みがあるのかを聞かせていただきたいのと、概要のところで、問い合わせ先が青少年育成課ということになっている。","respondent":"小林青少年育成課長","answer":"今後も庁内の検討機関には、私ども子ども未来事業部のほか、もちろん健康を管理しているものや福祉もありますが、それと同時に、大きな柱になっているのは教育委員会ですので、そういった関係各課が庁内連絡会をもちながら。","voiceIndex":98,"id":"exchange-037"},{"speaker":"林副委員長","kind":"質問","question":"もちろん教育委員会、小学校、中学校で、小中一貫の９年間という子どもたちのスパンをしっかり育成していく。そんな中で、後期の次世代育成が始まるわけですから、ぜひいろいろな折を見て、文教委員会に報告をし、あるいは意見を聞いていくということも忘れずにお願いしておきます。よろしくどうぞお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4698#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":36323,"voices":103}},{"id":"h22-20100510-5","meetingId":"h22-cm05","date":"2010年5月10日","dateIso":"2010-05-10","committee":"総務委員会","time":"午後１時０２分～午後１時５６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"１の地上デジタル放送への切り替えの周知","agenda":"１の地上デジタル放送への切り替えの周知","exchanges":[{"speaker":"土井委員","kind":"質問","question":"説明等は、先ほどもお話があったように、総務省の受信者支援センターの方からお越しいただいてなされるということなんですけれども、逆に、そういうところからお越しになると、品川の実情といいますか、ケーブルテレビがこれだけ普及している、そういう状況で品川区は金も出しているんですよというのと無関係にお話をされる可能性があるようにも思うんだけど、我々の施策的にはいかがですか。","respondent":"久保田行財政改革担当課長","answer":"そうした事情を何回か繰り返し打ち合わせをする中で、品川区の実情もわかってもらいながら進めているところでございまして、例えば、現に昨年行いました個別の説明会等では、総務省が主催でデジサポが説明を行うんですけれども。","voiceIndex":5,"id":"exchange-001"},{"speaker":"本多委員","kind":"質問","question":"例えば、４項目の周知をこれからしていただくということなんですが、特に受信障害のエリアに対する周知ですか、もちろん受信可能なところにも同じようにチラシなどが配布されると思うんですけれども、一番重要なのが、現在受信障害になっているところへの周知ということだと思います。そういった重点的な周知とかというのはできないんですか。","respondent":"久保田行財政改革担当課長","answer":"総務省の方と連携いたしまして、そういった方を対象とした説明会を開催していきたいと考えておりまして、現に平成２２年度に行います、この資料の２枚目の６月３０日まで行います相談会の内容としましては。","voiceIndex":7,"id":"exchange-002"},{"speaker":"山元委員","kind":"質問","question":"今までいろいろと開催していただいて、町会等でも回覧が回っているんですが、一つは、それでも知らなかったなんていう方が実はいらっしゃるんです。例えば、「今何某集会所で説明をやっています」という案内の車を出していただくというか、そのようなことはしていただけますでしょうか。いかがでしょうか。","respondent":"久保田行財政改革担当課長","answer":"今の予定では、車で回るというところまでは予定してございませんで、ホームページとか、あとは広報しながわはもちろんのことですけれども、それぞれ地域センターの方にそういった案内のチラシを置いてもらうとか、それぞれの地区で行いますので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"認知度は８９.６％ということなんですけれども、逆に言うと、まだ１０％ちょっとの方は知られていないということですが、およそどういう方が知られていないか。そういう分析等はされているんでしょうか。アンケートをとっているので、一定程度、どこら辺の認知度が弱いとか、どういう部分を強化する必要があるかとか、そういう分析はされているんでしょうか。そこのところを教えてくださいますか。","respondent":"久保田行財政改革担当課長","answer":"ケーブルテレビとの関係ですけれども、先ほどもご説明しましたように、８３.５％の世帯でケーブルテレビが引かれておりますので、そういう世帯の方につきましてはアンテナ等の設置工事は必要ないということでございまして、あとはご自分で地上デジタルのチューナーなり。","voiceIndex":11,"id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"一番問題だと言われているのは、情報弱者への対応をどうするかということなんですけれども、１０％ちょっとの方はどういう方なのか。こういう切り替えというのは行政の都合でやるわけですから、取り残されることがあってはいけないと思うわけです。私は国だけではなくて、地方自治体もあわせて対応しなきゃいけないんじゃないかと思うんですけど、そこら辺は何か考え方はあるんでしょうか。","respondent":"久保田行財政改革担当課長","answer":"そういった考え方に基づいて周知活動を一定進めてきたところでございまして、平成２３年７月に向けて引き続き継続していきたいと考えているところです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問・要望","question":"しかし、私が言っているのは、いろいろお知らせ等をやっても、まだ１割強の方が「知らない」と答えているという現実だと思うんです。もしかしたらそういう方を相手にしなきゃいけないのかなと思うんですね。くどいようですけれども、「言ってたつもり」という対応にならないようにしていただきたい。行政を挙げて取り組んでいっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"取り残されるのはいいんですが、今度取り残されたらどうなるんでしょうか。どうすればいいんですか」という混乱が起きるんじゃないかと私は思うんですね。実際、平成２３年ということですから、これからまだ時間はあると思うんですが、区の方としては確かに国によって与えられて今やっている事業なんですが、そういう弱者に対して個別にやっていくということは全く考えられていないんでしょうか。","respondent":"久保田行財政改革担当課長","answer":"これは国の方のお話なんですけれども、デジタル化の切り替えが近づいて、ある一定の時期になりますと「アナログ放送は停波します」というようなテロップがテレビ番組の中に出てくるというようなことも考えているようですので、テレビを見ている方であれば。","voiceIndex":16,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"何しろ、本当に日々使っているものですから、最後は区の方に対応を求められちゃうと思うんですね。混乱するかと思いますので、国に要請して、できるだけ混乱が起きないように対応していただきたいと思います。ということは、現実論、歩行困難だとか、介護支援を受けている動けないような方に対しては、行けなければ全く受けられないという状況と今の段階では見なきゃいけないんですか。","respondent":"久保田行財政改革担当課長","answer":"ですから、わからなければ企画財政課なり民生委員さんなりにお問い合わせいただいて、そういった申請書をそろえて、ご自分なり、どなたかに手伝っていただいて郵送でやればそういったことは可能になると考えております。","voiceIndex":18,"id":"exchange-008"}]},{"id":"topic-02","title":"２の平成２２年度区政モニターの委嘱","agenda":"２の平成２２年度区政モニターの委嘱","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"応募者が９８名、増えたということで、ただ、実際区民の人数からするとその数がどうなのか。要するにモニターさんで出しているのはそれもわかるんですが、参加した人に書いていただければすごく多くの人数のご意見というのが集約できて、書いてくれない人もいるかもしれないですけれども、それはかなりの区民がそのアンケートに答えるわけですから、そういう手法というのも別途にあるんですか。","respondent":"中川原広報広聴課長","answer":"これはあくまで区政モニターに限ったことでして、講演会とか講座とかをやりますと、必ず参加者アンケートというのを所管の方でとりまして、それを参考にさせていただきまして事業運営をやっているところです。","voiceIndex":24,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"モニターは人数的に定員５０名ということなんですが、その方たちにいろいろ見ていただくというのもあるんですが、実際モニターとしての適正な数ですか、いろいろな意味で、これはどういうものを基準にして決めたんですか。予算の問題なんですか。それを簡単に教えてください。","respondent":"中川原広報広聴課長","answer":"このほかにも広聴の仕組みとしては、タウンミーティングとか説明会とかいろいろなものがありますので、これは２年間の中で、区政全般にわたって理解を深めていただく一つの手法ということでご理解ください。","voiceIndex":26,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"質問ではないんですが、グループワークとしてとらえているのかもしれませんが、趣旨はわかりました。これから改善等いろいろしていくと思いますが、よりよい区政モニターの意見を集約できるように工夫していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-011"}]},{"id":"topic-03","title":"３の平成２２年７月１１日執行想定参議院議員選挙執行要領","agenda":"３の平成２２年７月１１日執行想定参議院議員選挙執行要領","exchanges":[{"speaker":"土井委員","kind":"質問","question":"選挙執行そのものですからそういうことなんでしょうけれども、一般的には投票してくださいという宣伝、ＰＲ等の車を出したり、いろいろやりますよね。そういうものに対しては、これはそのものじゃないからここにはないんでしょうけれども、当然またお考えを出していただけるんでしょうか。","respondent":"早津選挙管理委員会事務局長","answer":"選挙の啓発活動につきましては、通常どおり行ってまいるところなんですが、これ慣例的に選挙管理委員会で決定をして、何をするかというのを決めているんですが、総務委員会に何をするというようなことまでは報告していなかったのが今までということで。","voiceIndex":33,"id":"exchange-012"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"若林副委員長","kind":"質問","question":"１年間大変ありがとうございました。お疲れ様でした。副区長はじめ各事業部長、事務局長と大変お世話になりました。これから平成２２年度以降、財政も含めてますます大変な状況になると思います。質問もしっかりと、ある意味では力をあわせて、区政の発展に、個人的にはまた取り組みたいと思いますので、まずは１年間大変ありがとうございました。各委員の皆さん、お疲れ様でございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1852#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":16969,"voices":39}},{"id":"h22-20100511-14","meetingId":"h22-cm05","date":"2010年5月11日","dateIso":"2010-05-11","committee":"行財政改革特別委員会","time":"午後１時０３分～午後２時４９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"１の区施設の活用に関することとしまして、区施設中長期改修計画","agenda":"１の区施設の活用に関することとしまして、区施設中長期改修計画","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"対象建物の考え方についてお伺いしたいんですが、１ページのところで、「民間併設施設等」ということで訂正があったんですけども、そこにちょっとかかってくるのかなと思うんですけど、例えば一覧の中にヘルスケアタウンにしおおいなどは入っていないんですけども、対象建築物、例えば東大井のケアホームですとか、西五反田のケアホームなどは入っていないんですけども。","respondent":"日下部企画部長","answer":"いろいろそういう意味では多角的な検討をしっかりやって、それで整備を進めていくということが必要だろう。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"法人に対して貸し付けている、民間施設の扱いですからというところなんですけど、なかなかちょっと腑に落ちない点もあるんですが、といいますのは、そういったところの中長期改修計画というのは当然立てられなくてはいけないんですけども、そこに区がかかわれないというか、かかわらないというのはちょっとどうなのかなと思うので。","respondent":"日下部企画部長","answer":"区のほうとしては、基本的に段差解消も含めて、あとエレベーターもできるだけつけられるものにはつけましょうということで、この間取り組みを進めてきておりますし、その辺の基本的な考え方は変わってございません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"個々の施設で、どうこのバリアフリー的な観点をつなげていくのかというのは、本当に個々の検討になっていくと思うんですけども、ぜひここに書いているような観点で一層の推進を図るというところをこれからもぜひ貫いていってほしいなと。なるべく、できるだけ、最後まで執念を持ってこの観点を貫ける方策はないのかというところでぜひこれからも努力していただきたいなというふうに私は要望したいと思います。","respondent":"日下部企画部長","answer":"あまり土地で切り分けをするというのは、そういう説明はしたくないんですが、少なくともさっきのようにヘルスケアタウンにしおおいにつきましては、社会福祉法人に貸し付けをして、社会福祉法人が自分自身の責任で資金を調達して運営に当たっているということですから。","voiceIndex":9,"id":"exchange-003"},{"speaker":"阿部委員","kind":"質問・要望","question":"それを例えば大規模改修とか建て替えの時期とリンクをさせながら、例えば用途を入れかえたり、この土地は手放してしまって、こっちでこの用途を再生するといったような、ソフトというか、用途の面での中長期的な配置の考え方というのもあるかと思うので、その辺についてはどうお考えでしょうか。","respondent":"日下部企画部長","answer":"そういう意味では、ハード面の計画が中長期の改修計画、一方で、ソフト面、いろんな変化への対応ということでいくと、今年取りまとめをする区有施設のあり方についてもやる、表裏一体のものとして私どもは考えているというものです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"阿部委員","kind":"質問・要望","question":"それについて一言お願いします。再配置の考え方、それから今おっしゃったみたいに少子高齢化に対応したような再配置、そういったこともある程度目に見える計画の形で今後つくっていかれて、これとリンクさせることになっていくのか、それとも大規模改修や建て替えのとき、そのときそのときに、じゃあこれは何をしましょうかというような議論になっていくのか、お考えを教えてください。","respondent":"日下部企画部長","answer":"それからそれに基づいて実施計画も導入してきましたけれども、その中でもこういう基本的な考え方は一応取り入れてはいるんですが、今回やっぱりある意味で非常に重要な時期にも入りますので、しっかりと計画として体系化を図ったというのが１点目です。","voiceIndex":13,"id":"exchange-005"},{"speaker":"阿部委員","kind":"質問","question":"そういったことを計画として全体像を持って、なかなか難しいとは思いますけれども、そういう発想で進められていく方向であるのかということを教えてください。","respondent":"日下部企画部長","answer":"この間委員会でも一応お答えしてきた点がありますけれども、いずれにしろ、一つ一つの施設を今年計画策定の中でどうするかというよりも、基本的には今委員がおっしゃったように、例えば当面こういう機能でいくけれども、例えば５年先。","voiceIndex":15,"id":"exchange-006"},{"speaker":"須藤委員","kind":"質問","question":"今質問があったように、計画の性格というところにあるように、その辺を今度ソフトとどうやって対応させていくのかというのが非常に大切になろうかと思うんだけども、ソフトの面については、どの辺ぐらいまで考え方がまとまっているんですかね。計画の性格というところにきちんとうたってあるんだけど、そのあたりはどの辺まで考えられているのか。","respondent":"日下部企画部長","answer":"ソフトとの対応ですけれども、目的の一番下のほうにもありますように、今回の計画策定の目的は、「今後の施設のあり方や資産の有効活用等の検討資料として効果的に活用していくということ」と明記していますが、そういう意味では、今回ハード面の中長期の改修計画。","voiceIndex":17,"id":"exchange-007"},{"speaker":"川西委員","kind":"質問","question":"それで一つ伺っておきたいんですが、例えばこの資料の中に、例を挙げますと、大井保育園は４８年経過しているけれども、大規模修繕をしたばかり、２年前にしたと思いますけれども、それから荏原保育園については４７年経過しているけれども、平塚にできる幼保一体施設が開設されるのが平成２５年、そういうことなので、あそこが開設されるまでは荏原保育園は手がつけられないだろうという判断もあります。","respondent":"日下部企画部長","answer":"やはり実施計画、これはお金の問題もしっかりちゃんと見据えなければいけませんから実施計画、それから当然それをもとにした毎年度の予算への計上、そんな感じで具体化を図っていくということで考えております。","voiceIndex":19,"id":"exchange-008"}]},{"id":"topic-02","title":"２の跡地活用に関すること","agenda":"２の跡地活用に関すること","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"それぞれの施設については、これまでの委員会でもいろいろ申し上げてきましたが、１点だけ。期間が限定的ですので、あまり多彩な用途というのはないかとは思うんですけれども、地域の状況等もかんがみながら、できるだけ柔軟に活用できるような方向で考えていただければと思うんですが、いかがでしょうか。","respondent":"久保田行財政改革担当課長","answer":"荏原平塚中学校につきましては、基本的に平成２３年の５月から地域センターとして活用するということを予定しておりまして、一貫校開校後も含めまして、校庭と体育館につきましては従来どおりスポーツ開放という形でお使いをいただきたいというふうに考えているところであります。","voiceIndex":25,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"３点だけ質問したいと思います。最後の３点目は、５と６の杜松小学校と荏原第四中学校のところで、平成２２年度より検討というふうに書いてあるんですけども、改めて平成２２年度のいつぐらいから、どういう形で検討するのか、今の区の考え方をお伺いします。","respondent":"久保田行財政改革担当課長","answer":"それと、杜松小学校と荏原第四中学校につきましては、やはり大規模な貴重な区有財産ですので、その一方で、やはり区としても長期基本計画等で掲げるような施策の展開にも資していかなければいけないというところで考えておりますので、まずは区としまして。","voiceIndex":27,"id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5882#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":20952,"voices":38}},{"id":"h22-20100513-15","meetingId":"h22-cm05","date":"2010年5月13日","dateIso":"2010-05-13","committee":"環境対策特別委員会","time":"午後１時０３分～午後２時３８分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"水辺とみどりの整備に関することとして、「緑確保の総合的な方針（案）」に対するパブリックコメントの結果","agenda":"水辺とみどりの整備に関することとして、「緑確保の総合的な方針（案）」に対するパブリックコメントの結果","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"１番目のところの総合的な方針の中で、以前にも説明があったのかもしれないんですけれども、改めて教えていただければと思いますが、民地の緑が抱える課題というのは具体的にどういうものなのかを改めて教えていただきたいのと、それから、その下のほう東京都および島しょを除く方針であるとなっているんですけれども、東京都のこの５３区市町村というのは東京都全体の中にあるわけで。","respondent":"藤田水とみどりの課長","answer":"説明の仕方が悪うございまして、すみません。後段の部分のほうを先に説明しますが、東京都と５３市区町村で取りまとめたという意味でございまして、その中に島は入っていないという意味です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"確認","question":"あまり後段のところがよくわからなかったんですけれども、私の理解は、この概要の一番最初、開いたところのトップに、「既存の民有地の緑はこれを上回って減少します」と書いてあるので、それは農地の問題だとか、宅地化されたりとか、そういうことで減っちゃっているんだなと、だれでも自然にそういうふうに理解するんだと思うんですけれども、それはいろいろな経済活動とか農業をやっている中で。","respondent":"藤田水とみどりの課長","answer":"まちづくりの中での共通認識等の関係ですが、緑確保の総合的な方針のほうの大前提は、都市の中でのまちづくりというか、生活をこれまで同様に継続することを前提にしつつも、緑を守っていくと。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"確認","question":"共通認識をしっかりお互いに確認しながらと思うんですけれども、それは市町村ごとに、自治体ごとに行われながら、東京都全体で進めていくという関係になっているのかなと思うんですけれども、全体的な動きというのは、全体的な状況、それから、そういう共通認識と緑の保全確保がどういうふうに進んでいるかということを全体的に見るときには、どういうところでどういうふうに掌握しているから。","respondent":"藤田水とみどりの課長","answer":"そういうことで、これも本来は緑を守っていくための話としては多摩のほうが中心なのではありますけれども、２３区も含めて、例えば多摩のほうの緑を守るための区としての手助けが何かできないかとか、そういった視点も取り入れながら取りまとめているものですので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"確保候補地というのが２５で８.７４haあると書いてあって、意外に２５という数字は私の印象としては多いなと思ったんですけれども、後でここの箇所をどこなのか教えていただきたいと思っているんですけれども、そういう都心に位置しているところとしては、それなりの緑がある地域なのかなと改めて実感したんですけれども、それにしてもやっぱり道路と集合住宅がたくさんできているから。","respondent":"藤田水とみどりの課長","answer":"保存樹、保存樹林の制度がありますが、こうした保存樹林については、私どもも一定の担保性は持っているとは考えてありますが、その担保性が今回の水準に合わせると若干低いのかなと考えていますので、まずそういう保存樹林にしているものを。","voiceIndex":11,"id":"exchange-004"},{"speaker":"石田委員","kind":"意見","question":"その中でも特に民有地の緑をなくしていくというのは、地主さんが何らかそこを有効活用しようと思っているからなくなっていくわけで、そういう中でどのような、例えば税の優遇をするだとか、そういったどのような施策を打っていって持ち主さんに理解をしてもらうのかというのが一番だと思うんですけれども、その辺は都としての考えなのでちょっとあれなのかもしれないんですけれども。","respondent":"藤田水とみどりの課長","answer":"その中では今お話にもありました税の優遇等も既に行っている部分もありますが、その辺の枠の拡大が図れないか、それから、先ほども少し申し上げました維持管理等になかなか手が回らない、そのために地域の方にご迷惑をかけてしまうということもありますので。","voiceIndex":13,"id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"今、課長がおっしゃった補助金の制度という話がありまして、あくまで都の事業、都と特別区、市町村ということの事業なんですけれども、今、いろいろな意味でおのおの事業評価なんかをやっているわけですけれども、国も今やっているもろもろの土木といいますか、こういう部分に関する事業の仕分けによって影響を受けることって当然出てくると思いますけれども、そういうのってあり得るんでしょうか。","respondent":"藤田水とみどりの課長","answer":"ただ先ほど申したのはあくまでも東京都の制度で、今年度新たに立ち上げた制度ですので、今年度については間違いなく実施されるものと考えています。","voiceIndex":15,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"だから、今言ったこれから具体的に進めていく中にあって、現実にはさまざまなことがあるでしょう。それを見直しをやっていくと言ったのだけれども、こういうことを議会に言って、パブリックコメントもやったわけだから、例えば来年度はこうしていくとか、品川区としてこうしていくとか、より具体的な品川区の方向性というのは聞けないんですか。そういう形でお話をいただければと思います。","respondent":"藤田水とみどりの課長","answer":"しかしながら、これの着手までにはもう少し時間がかかりますので、今年度についてもこれからまた事業評価といいますか、事業のあり方についての検討、それから実施計画等の策定も控えておりますので、そういった中で先取りをして。","voiceIndex":19,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問・要望","question":"すごくわかるんですけれども、都心部で２５カ所も緑の面積を増やしていくというのは、間違いなく民間の方にも協力をお願いしなければいけない。そうなると、やっぱり権利関係が生じてくる話であって、それは２５カ所が進めないということは私は思っていないんです。その計画をどれぐらい胸に品川区としては考えていって、その具体的な展開をしていくのかという見通しについてお聞かせいただきたいと思います。","respondent":"藤田水とみどりの課長","answer":"その後半５年間でもこれをしっかりやっていくんだということで位置づけられております。そういった中で、私どもとしては１日も早く具体的な取り組みが進められるよう進めていきたいと考えています。","voiceIndex":21,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今後のことにつながっていくと思うんですけれども、東京都と区市町村と連携をして全体を見直していくという視点がものすごくこれから求められていくなと考えていますけれども、今も質問にもあったんですが、品川区は新・水とみどりのネットワーク構想というのが既に基本構想から立ち上がって進められているんですけれども、これとの関係というのが今後どういうふうに反映されていくのかというのと。","respondent":"藤田水とみどりの課長","answer":"既存の緑を守る方針のところが先ほどからお話のある２５カ所をとりあえず区として今、挙げているものですが、緑のまちづくり指針につきましては、区のほうで行っている公園づくりの事業に加えて、品川区で申し上げますと、例えば防災まちづくりででき上がる公園。","voiceIndex":23,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"インターネットで１０年後の東京の構想の中にこの緑確保が入っているということで、ちょっと見たら、結構臨海エリアの開発のところとか、新たな緑の創出とか、品川も表玄関という部分の緑についてとか、結構いろいろな構想が示されているんだなと思ったので、その辺との品川との整合性というか、一体となってやることがあるのかどうか、ちょっとその辺も伺いたかったのと、あと新・水とみどりのところでは。","respondent":"藤田水とみどりの課長","answer":"区内でいろいろ考えてみますと、例えば街路樹の倍増計画ですとか、あるいは校庭の芝生化ですとか、そういったものも１０年後の東京の中で策の中に示されてございまして、可能な場所については、都道についても街路樹を今、東京都のほうで追加をしたり、区の学校についても。","voiceIndex":25,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今日の資料の中でも東京クラインガルテン事業とか、東京都はこれをやる前にアンケートもとっていて、すごくいろいろな助成の制度を充実してほしいとか、都民、区民がいろいろ参加できる部分を増やしてほしいという意見もアンケートの中にかなりいろいろ載っていたので、すごく関心が高い部分だし、参加しやすい部分でもあるのかなと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"回答の内容とかが出されると思いますが、その後に都区市町村の考え方も明示と出ているんですけれども、これはどのような内容なのかなと。都の考え方、それとも品川区としての考え方を何か個別に出すものなのか、それとも全体としての話なのか、もし区としてのコメントというか、そういう考え方が出るのであれば、今どのような内容を考えられているのか教えていただけますか。","respondent":"藤田水とみどりの課長","answer":"総論的には緑確保の総合的な方針については、おおむねそういう考え方で進めていいんじゃないかというご意見ですので、緑を確保するために都区市町村が一体となってこれから取り組んでいきたいということ、それから、先ほどちょっと申し上げました都民、ＮＰＯ。","voiceIndex":28,"id":"exchange-012"},{"speaker":"浅野委員","kind":"質問・要望","question":"それとあと東京都の広報と広報しながわでも発表されるんですけれども、このときには広報ですから多分概要版か何かになるのか、そのぐらいのイメージなのか、全文になると広報が相当厚くなると思いますので、多分概要版だと思いますけれども、そのレベルを教えていただきたいのと、あとこの中に今、お話があったパブリックコメント、これが区の受け付け分ということなので。","respondent":"藤田水とみどりの課長","answer":"広報の関係ですが、大変ボリュームも多いものでございまして、今回そういったものの取りまとめができましたという程度の、大変申しわけないんですが、広報の記事になる予定です。","voiceIndex":30,"id":"exchange-013"},{"speaker":"浅野委員","kind":"質問","question":"ちょっと質問が前後して申しわけなかったですけれども、パブリックコメントが今回、品川区が受け付けたのが２件で１通ということだったんですけれども、これは品川区の区民の方が品川区に対して出していただいたものだと思うんですけれども、ちょっとどういうシステムかというのをはっきり認識していなかったんですけれども、例えば東京都に直接出せたのか。","respondent":"藤田水とみどりの課長","answer":"広報しながわのほうなんですが、紙面の関係もございまして、あくまでもパブリックコメントをやって、それでこういったような冊子がまとまったというご案内までしか、大変申しわけございませんが、今回できませんで、それぞれの意見に対するご回答等については。","voiceIndex":32,"id":"exchange-014"},{"speaker":"浅野委員","kind":"質問・要望","question":"広報にさわりという形で載せられるということですけれども、いろいろな機会でこのようなことを区がやっているということは、ぜひとも機会を見て区民の方にもお知らせしていただきたいということと、先ほど、今後、行動計画とか実施計画ということをつくられるということですので、ぜひとも実りある今回の緑確保の総合的な方針に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-015"}]},{"id":"topic-02","title":"を行います。 初めに１太陽エネルギー見本市の開催","agenda":"を行います。 初めに１太陽エネルギー見本市の開催","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"１点だけなんですけれども、見本市を開催するのはもちろんいいんですが、品川区の地球温暖化対策地域推進計画がありますよね。そのことについて、例えば区民に対するＰＲとか、そういうことをここですると非常に効果が上がると思うんですが、いかがでしょうか。","respondent":"工藤環境課長","answer":"昨年つくった地球温暖化対策の推進会議のＰＲの件につきましては、私どもいわゆる区の専用のブースというのをこの会場の中につくる予定です。","voiceIndex":39,"id":"exchange-016"},{"speaker":"浅野委員","kind":"意見","question":"このチラシの見方もおもしろいなと思ったんですけれども、見本市のほうに出ているということは、見本市だけで２,０００kwｈという数字なのかどうかというところについて、増やしたなら増やした理由ですとか、前回の結果も踏まえて、今回の取り組みについてお願いできればと思います。","respondent":"工藤環境課長","answer":"こちらのほうのパンフレットは見開きで見ていただくということで、少しわかりにくいかと思いますけれども、このイベント２つで２,０００kwｈということで、よろしくお願いいたします。","voiceIndex":41,"id":"exchange-017"},{"speaker":"浅野委員","kind":"質問・要望","question":"２つあるから倍ということではなくして、例えばこのグリーン電力証書システムは、こういうイベントにはこれからも積極的に増やしながら使っていくのか、それともレベルとしては１回あたりこの程度の利用というんでしょうか、その方針でいくのかというところの考え方を教えていただきたいと思います。","respondent":"工藤環境課長","answer":"考え方としては今お示しした大きな事業で対応していくことは変わらないんですけれども、今年度につきましては、区民まつりの会場の中でアピールしていきたいという方向で今、考えているところです。","voiceIndex":43,"id":"exchange-018"}]},{"id":"topic-03","title":"２次世代自動車導入促進助成","agenda":"２次世代自動車導入促進助成","exchanges":[{"speaker":"石田委員","kind":"質問","question":"２点ほどお伺いしたいんですが、まずこの助成額なんですが、ガソリン車と電気自動車の差額の８分の１と書いてありますけれども、なかなかこれを見てもピンとこないのかなというのがあるので、できたらこういうときには例を１つでも挙げていただいて、例えば幾らの自動車を購入したときにという例を書いていただくと。","respondent":"工藤環境課長","answer":"１点目の助成額が実際どれぐらいになるのかということをわかるように、ＰＲされたほうがいいのではないかですけれども、私どものほうでは今、パンフレットの作成を進めておりまして、まだ次世代自動車導入の勧めということで、国の補助、東京都の補助等も併用可能となりますので。","voiceIndex":50,"id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問・要望","question":"言っているニュアンスはわかりますか。だけどガソリン車両となるとピンからキリまである。その差額の８分の１と設定したんだけれども、ガソリン車両価格は、この申請の方が求められた電気自動車について、ガソリン車の価格をどういうふうにして判断していくんですか。そこの基準で随分と、上限は決まっているから、そこのところはあるけれども、ガソリン車両価格との差額についてはどう考えていますか。","respondent":"工藤環境課長","answer":"説明が詳しくなかったもので、このようなことになったかと思いますけれども、電気自動車の型というのは、今、大体４２０万円ぐらいです。今、市場で出ているのが三菱自動車のｉ－ＭｉＥＶと富士重工のプラグイン・ステラというもので、いずれも４２０万円ぐらいのものです。","voiceIndex":52,"id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問","question":"その車両が出たけれども、これから電気自動車が多分出てくるでしょうから、その個々の価格とベースになる車両価格がこうで、今、お話があったように国、東京都の助成が入って、残りはこうだから、それについてこういうふうにしましょうというところまで話を落とし込んでいかないと、申し込む方だって、一体どれだけの負担があるのか、もしくは助成していただけるのかわかりにくいかと思いますので。","respondent":"工藤環境課長","answer":"私どももその部分で導入を進めるということで、このご案内とプラスアルファで、伊藤委員からお話がありましたように、例えば電気自動車が４００万円の場合にどんなモデルケースになるのかという部分をしっかりわかりやすいように。","voiceIndex":54,"id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問","question":"もう１点だけ。自動車を導入するのはいいんだけれども、品川区の地球温暖化対策地域推進計画との整合性、これがポッと出たような感じがするんですけれども、助成が。先にこの計画を決めているわけだから、この中でおそらく記述があると思うんだけれども、どうなんですか。","respondent":"工藤環境課長","answer":"いろいろと私どももエコドライブ講習会をやりましたり、ＥＣＯフェスティバルの中で電気自動車の試乗会をやりましたりとか、いろいろな形でそういった啓発も進めているんですけれども、そういった意味では計画の中の１つのメニューという形で新しく考えておりまして。","voiceIndex":56,"id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、もっといろいろな具体的な計画をこれから出していかないと、ここでうたわれているものが具体的に活動できないということについて、最後に伺いますが、これを今、急に出してきたかということと、またこれから、この後、一般の方々もそうでしょうし、当然区民の方々もあるでしょうし、それからいろいろな方々がこのことについては取り組んでいかなければならないだろうと。","respondent":"工藤環境課長","answer":"４台という部分では本当にごくわずかな台数ではありますけれども、区がこういったものに、次世代自動車に助成を始めるということは意義があるものだと思っておりまして、区が直接、補助するだけではなくて。","voiceIndex":58,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今回、買い換え購入、普通のガソリンを新しい次世代にかえるための助成と書いてあるので、その点を１つお伺いしたいのと、あと低公害車にかえていくということで電気自動車およびプラグインハイブリッド自動車、この辺のエコ度合いというのか、公害を抑えている比較というのが、電気自動車とプラグインハイブリッド車、あと普通のハイブリッド車と比べると、どの程度地球にやさしいのかという。","respondent":"工藤環境課長","answer":"エコカー自体の定義を次世代自動車の購入助成事業と、従来、私ども低公害車の融資あっ旋事業というのを継続して実施しておりまして、これを含めてエコカー導入助成事業と呼んですので、プレスのときにはそのようなタイトルをつけさせていただいたです。","voiceIndex":60,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"片一方とこれが一緒という受けとめ方でいいんですか。プレスの中ではエコカー導入促進というところで２つ、次世代の自動車と低公害車と、それはわかりました。その次世代自動車のところに購入助成のところに新規という書き方をしているので、ちょっとそこを聞きたかったんです。そこの違いがあるのかないのか、ちょっとそこを教えてください。","respondent":"工藤環境課長","answer":"申しわけございません。新たに購入することではなく、新規事業であるということで新規とうたっております。","voiceIndex":64,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"助成のところはわかりました。予算が次世代自動車購入助成で１６０万円になっているんですが、これって国からの助成を見越しているんじゃなくて、区の独自のを書いているということなんでしょうか。","respondent":"工藤環境課長","answer":"この４０万円ですけれども、ご質問のとおり、区からのすべての財源になります。４台につきましては、今後状況等、メーカーの導入状況、あと消費者の動向等を踏まえまして、今後も検討していきたいと思います。","voiceIndex":70,"id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"その辺についてはどうなんでしょうか。考え方としてと、今の現状がどういうふうになっているのか。清掃車なんかはそういうふうに買い換えているということで承知しておりますけれども、そのほかの事業のところでの関係はどうなっているのかを改めて知りたいし、促進させていくべきだと考えていますので、その辺について伺います。","respondent":"工藤環境課長","answer":"今年の年末には日産のほうから普通自動車の電気自動車が出るという状況ですが、まだまだ市場にそこまで出回っていませんので、そういった部分まで私どものほうで制限といいますか、そこまで要求するという部分は、まだまだ先ではないかと考えていますけれども、今後。","voiceIndex":72,"id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"私も率直に４台じゃ、デモンストレーションで品川区はこういう対策もやっていますよという、そういうレベルで今のこの時代にいいのかなというのがあるので、これからの推移を見守って、できるだけ増やしていくという方向をぜひ打ち出していただきたいという思いの中で、いろいろ質疑を聞いていたときに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-028"},{"speaker":"浅野委員","kind":"質問・要望","question":"何点か質問させていただきたいんですけれども、今回の助成制度について、国のほうの制度の中にこの電気自動車とプラグインハイブリッド自動車が含まれているんですが、それ以外に例えばクリーンディーゼルですとか、充電器の設置事業にも補助制度が出ている。補助制度。こちらのほうのほかの部分をやらないのか、それとも今後検討されるのか、それについてまず教えていただきたいと思います。","respondent":"工藤環境課長","answer":"東京都のほうでも充電スタンド、当然次世代自動車を普及させるためには、インフラの整備という部分がセットとなっているということで、それを拡充しなければいけないという考えの中で行われているというのは、私どもも認識しております。","voiceIndex":75,"id":"exchange-029"},{"speaker":"浅野委員","kind":"質問・要望","question":"都のほうはもう５台で終わっていました。国のほうは何台という規定は多分ないかと思いますけれども、そこら辺のただし書きというんでしょうか、そういうところも気をつけなければいけないのかなと思います。確かに電気自動車は区内とかで使う分には済むかと思いますけれども、プラグインハイブリッド自動車への要望も多い中で、どのように考えていかれるのかなと思いますので、どのようなお考えなのか。","respondent":"工藤環境課長","answer":"そういった意味では、多分東京都もそのような動向を見て５台にしているという部分だと私どもも認識しておりますので、そういった意味で３００対５という数字が出ているのではないかなと考えています。","voiceIndex":77,"id":"exchange-030"},{"speaker":"浅野委員","kind":"質問・要望","question":"確かにプラグインハイブリッド自動車はこれからの車ですので、どのぐらいの規模で出てくるか、価格的も問題もあるかと思いますけれども、都の動きをしっかりつかまれているということですので、ぜひとも区民の皆様に紹介する中で、リスクがある場合には、ぜひともしっかりとそこら辺を都に進言するなり、また区として独自に何らかの方策をとるなりしていっていただければと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6186#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":28179,"voices":84}},{"id":"h22-20100520-8","meetingId":"h22-cm05","date":"2010年5月20日","dateIso":"2010-05-20","committee":"建設委員会","time":"午前１１時０２分～午後３時３０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3976#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":2128,"voices":10}},{"id":"h22-20100601-6","meetingId":"h22-cm06","date":"2010年6月1日","dateIso":"2010-06-01","committee":"区民委員会","time":"午後１時０３分～午後２時４１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の２番目、事務事業概要","agenda":"の２番目、事務事業概要","exchanges":[{"speaker":"菊地副委員長","kind":"意見","question":"ちょっとお聞かせ願いたいんですけれど、地域振興事業部の場合、どちらかというと区民の皆さんの日々の生活に直結するような施策、事業が多いのではと思うんですけれども、今、それぞれの課別で説明を願ったんですけれども、今年度事業部として、これをとにかく最大限力を入れていくんだというような、その辺の考え方みたいなところがあればお聞かせ願いたいんですけれども。","respondent":"宮地地域振興事業部長","answer":"特に私どもの事業部でいいますと中小企業、商店街の振興策、これは引き続き力を入れていくということで、緊急融資あっ旋の３年間無利子という、先ほど課長からもありましたけれども、平成２２年度も継続、それからプレミアム付商品券ですけれども、昨年度は春に２億円。","voiceIndex":41,"id":"exchange-001"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"今、部長がおっしゃられたように、経済状態が決して好転はしていないですし、ましてや区内の中小企業の人たちは大変な状況にあるということで、中小企業の振興策についてはもちろん、今、部長がおっしゃられたようにいろいろな形で充実をしていくということでありますけれども、支援はさらに、ぜひこれからの委員会の中で、いろいろな形で報告を出していっていただきたいと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-002"},{"speaker":"山内委員","kind":"意見","question":"日程は皆さん大丈夫だということなので、その辺は正副委員長でお考えいただいて、あと視察先、テーマも含めてなんですが、これもやはり正副委員長と理事者の方との相談でよろしいのかなと思います。基本的にはそういう形で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-003"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"先ほどの部長のご答弁にもあったように、中小企業問題というのは、商業にしても工業にしても相変わらず大変な状況にあるということで、ぜひこの経営支援を含めて、中小企業問題というのを年間を通した調査事項に乗せていっていただきたいと、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2580#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":31093,"voices":58}},{"id":"h22-20100601-7","meetingId":"h22-cm06","date":"2010年6月1日","dateIso":"2010-06-01","committee":"厚生委員会","time":"午後１時０２分～午後４時０２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"山元委員","kind":"意見","question":"同じく公明党の山元です。どうぞ、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要を行います。 これにつきましては、改選後の初めての委員会で、各所管の各事業概要","agenda":"事務事業概要を行います。 これにつきましては、改選後の初めての委員会で、各所管の各事業概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"５点目でしょうか、施設基盤整備ですから８１ページですが、八潮は来年春に竣工で、オープンになるわけですが、一番下の都営大井林町アパート跡の施設のところで、先ほど、丁寧に説明はいただいたんですが、施設に入所される方々の人数が、私が聞き落としたのか、わからなかったので、どういう規模で計画をされているのか、実施設計ということなので、その辺も伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"４５ページの虐待防止ネットワークの部分ですが、最終的に、施設のことでご心配というお話だと思いますが、区民の方の部分でも、在宅介護支援センターを中心に、もちろん私どもの各支援係がすぐに対応できるような仕組みを持っております。","voiceIndex":50,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、今まで、１,３００円ぐらいかかっていたのが、７００円から８００円ぐらいかかるということで、１,０００円から５００円に変わったということを強調して、実際に使うと、もっと予定した以上にお金がかかるということではあれですから、私はやっぱり、思い切って、他区のように、少なくとも通話料は無料にするとか、５００円の料金を無料にするとか、そういうふうなことは。","respondent":"冨岡高齢者福祉課長","answer":"９月につきましては、高齢者の場合は、正直申し上げて、一つには亡くなられる方も多い、それから同じ方で軽度の方が、少し重くなってまた申し込まれる、いろいろトータルをつかむのが難しい部分がございまして、表示をしておりますが。","voiceIndex":52,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、そういうことプラス通話料がかかるという点では、申込みするときに、そのときに既にどこまで自分が頑張って耐え切れるかということを計算しながら申し込むという方が結構大勢いらっしゃるので、負担が半減したわけですから、それはそれで結構大きなものだと思いますけれども、他区の状況なんかを見ると、ほんとうに無料に近いような百数十円とかいう料金を設定しているところも結構ありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-004"},{"speaker":"中塚副委員長","kind":"質問","question":"つまり、今、区民生活は、ご承知のとおり、大変厳しい状況に置かれています。こういう状況が広がっている中で、品川区自身は、こういう区民の実態をどう分析しているのか、そして、今年１年、何を重点施策といいますか、どこの施策に力を入れようとしているのか、ちょっとそこを、健康福祉事業部と品川区保健所と、それぞれお考えを伺いたいと思います。","respondent":"木下健康福祉事業部長、本保品川区保健所長","answer":"これは、言ってみれば、全国でかなりばらばらな認定審査を、もう少し単純化して統一していこうという考え方のもとに進められたわけでありますけれども。問題点もなかったわけではありませんけれども、死亡率自体も、他国に比べますと非常に低く推移をしたという、日本の医療体制自体のアクセスのよさ、それからタミフルの備蓄なども含めて、対応がよかったということです。","voiceIndex":55,"id":"exchange-005"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"つまりは、特別養護老人ホームへの入居待ちが、今、大変深刻になっている。その先の計画は見えてこない。やっぱり、特別養護老人ホームの増設計画を、しっかり具体化すべきだと思いますけれども、今、困っている人たちについては、どうお考えなのか、伺いたいと思います。先ほどの点を、１点、伺いたいと思います。一日も早く具体化すべきだと思うんですけれども、そこについてご説明いただきたいと思います。","respondent":"木下健康福祉事業部長、永尾障害者福祉課長","answer":"具体的には、特に高齢者福祉の部分について、今、現実に困っている方への早急な対応ということだと思うんです。日程といたしましては、６月７日にやる予定になっておりますので、そこの中では、区の職員のほか、障害者団体の方、身体障害者、知的障害者の相談員も含めて検討をして。","voiceIndex":58,"id":"exchange-006"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"これは意見です。障害者福祉については、一日も早く請願の趣旨に沿って実現するように求めていきたいと思います。その一つの指標に、公的扶助といいますか、生活保護について、そこが端的にあらわれると思いますけれども、今日の報告でも、若干、状況が報告されておりましたけれども、品川区の現状について、特徴や傾向、今後の対応策、どう考えているのか、ちょっと伺いたいと思います。","respondent":"平澤生活福祉課長、木下健康福祉事業部長","answer":"公的扶助編の５ページをお開きいただきたいと思います。こちらに、先ほど、ご説明した年間の平均の保護者数が載っているところですが、2)をご覧いただきたいと思います。平成２０・２１年度の開始原因に当たるところの表です。今回、これから実施設計を詰めるわけでありますので、現実的にいいものにしていこうというときに、実際に運営するところに入って、一緒に計画を詰めていくほうがよりいいサービスが提供できると考えておりますので。","voiceIndex":61,"id":"exchange-007"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"生活保護も含めて、福祉については、暮らしについて、区民の実態から出発して進めていただきたいということ。引き続き、ちょっといろいろ、進みぐあいはしっかりと報告していただきたいと思います。最後に１点だけ、障害者と介護保険と両方あると思うんですけれども、いわゆるバリアフリーといいますか、住宅のリフォームを１割自己負担でやりますよね。","respondent":"冨岡高齢者福祉課長","answer":"この制度は、たしか、住宅リフォームの部分で、区内の事業者を利用されてリフォームされる場合に対象になるかと思いますが、そういう方たちが窓口にお見えになったときは、この制度については、当然、連携をしてご説明をしていくところです。","voiceIndex":64,"id":"exchange-008"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"大沢委員","kind":"意見","question":"具体的な都市名は、私もまだわからないんですが、先ほど来、健康福祉事業部長がおっしゃっているように、今度、第５期の介護保険の企画が、平成２４年に向けて変わってくるということで、その中で、先ほど来、何回かご発言されているように、地域包括ケアのあり方について、私たちは、それを研究、検証しながら、この計画についてのさまざまな検証を加えていく必要があるのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-009"},{"speaker":"南委員","kind":"意見","question":"特別養護老人ホームの件なんですけれども、先ほど、健康福祉事業部長がいろいろと考え方について示していただいたんですけれども、運営形態も含めて、どういうものだとか、どういうふうな考え方で、そこの地域の高齢者対策として持っているかというような、その辺をちょっといろいろ聴取おきたいと思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"委員長のお話を遮って申し訳ないんですけれども、所管事務調査のところも非常にかかってくると思うので、多分、この後に所管事務調査のことにも振ってくださると思うんですけれども、テーマを決めるに当たって、私の思いとしては、品川区でも随分、障害者福祉施設の建設の件で、やっぱり親なきあと施設というのが、各会派から声として随分挙がっていると思いますし、区民の方々の切実な要望でもあるので。","respondent":"鈴木委員長","answer":"所管事務調査につきましては、後ほどその他で振らせていただこうと思っていたのですが、委員会視察としても、当然、所管事務とあわせた上で考えていきたいと考えています。","voiceIndex":73,"id":"exchange-011"},{"speaker":"三上委員","kind":"質問・要望","question":"行政視察ですから、それなりに先進的に進められているところについて、今、手持ちとしては具体的なところは申し上げられませんけれども、所管事務調査という視点もあるかもわからないけれども、先進的な取り組みということを眼目にした行政視察にしていただきたい。のちに、委員長に、そういった点で、何点かあったら、至急提出したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3268#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":51958,"voices":81}},{"id":"h22-20100601-8","meetingId":"h22-cm06","date":"2010年6月1日","dateIso":"2010-06-01","committee":"建設委員会","time":"午後１時０３分～午後３時０４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、幹部職員紹介","agenda":"の１、幹部職員紹介","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"マスタープランのお話あったんですけれども、本年度基礎調査をしてということなんですが、新しくつくり直すということだと思うんですけれども、こちらの建設委員会所管の、区のほうで現在のまちづくりの基本としている計画の対応というんですか、どういう考えでまちづくりを事業部としては進めていっているんだという、現在のお考えとあわせて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"私はまちづくり全体のことについて聞いているので、そうした部分にちょっと回答がないような気がするので答えていただきたいと思うんですが、これからマスタープランを変えていこうというのであれば、これまではどういう方向でまちづくりを進めてきてというのを、まずしっかりと総括して、時には反省もするでしょうし、それを次に活かしていくということが必要だと思うので、私が先ほどお伺いしたのが。","respondent":"片田防災まちづくり事業部長","answer":"民間のいろいろな開発の事業がありますので、それをきちっと誘導した中で望ましいまちづくりのほうに進めていくということで考えているので、ぜひともご理解いただくことをよろしくお願いします。","voiceIndex":53,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう一つ、ちょっと道路のお話があったので、今日全体の概要ということなのでお伺いしたいんですけれども、道路整備率が都市計画道路が六十数％整備が進んでいますというお話、説明があったんですが、これから何か、２９号線というようなことも、そういうこともありますけれども、道路に関してもこれからの道路を車両の通行の需要について、どう区としてはお考えなのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-003"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"すみません。２件ほど伺いたい。９７ページ、これ大井プレイス、こういう書き方で載せていいんですかね。この考え方。それから、これは教えていただきたいんです。ＢＣＰにかかわる問題というのは、防災では一切かかわらないということなんでしょうか。その２点お願いします。","respondent":"三宅都市開発課長、中山防災課長","answer":"９７ページの広町地区の開発構想ですが、これは今時点ですぐ動くということではないのですけれども、この区の中心部において、開発の余地を残す大きな土地というのは厳然として残っておりまして。危機管理室に防災課があるというところも多いんですけれども、当然震災復興マニュアル、ガイドラインをつくっていますので、総務部と危機管理室と協議の上、多分防災課になると思いますけれども、調整はしてまいります。","voiceIndex":57,"id":"exchange-004"},{"speaker":"阿部副委員長","kind":"意見","question":"ＢＣＰをそういうことでいいのか。できるだけ早く分担と所管をきちんとしていただければと思います。大井プレイスのほうは、こういう形で置くと事務事業概要に載っているということ自体がどうなんだろう、ＪＲの関係じゃないか、これ、みたいなことになるかなと。私のほうはちょっと違和感がありました。","respondent":"片田防災まちづくり事業部長","answer":"ＢＣＰにつきましては、やはり防災課長から話がございましたように、一応まだ進めている事業では、精査されている部分もあり、明確になっていないところもありますので、一応危機管理のほうと十分調整しながら精査をして明確にしていきたいと、このように考えてあります。","voiceIndex":60,"id":"exchange-005"},{"speaker":"渡部委員","kind":"質問","question":"説明いただきましたどちらの部に関してもなんですけれども、昨年から事業部のほうがもう１回再編された中で、新たに今年また始めるに当たって、他課との連携とかというのはわかりました。なければもうなしでも結構なんですが、１年やった中で今年どういうふうに区としてやっていくというのがあればお願いいたします。","respondent":"中山防災課長、松代都市計画課長","answer":"思いました。私ども職員２４時間体制なんです。消防署と全く同じなんです。今日も松澤副団長とお会いしましたけれども、実は副団長も私も眠くてしようがない。４時前でございまして、この事業は非常に後を引くんですね。ここの中でちょっと申し上げますと、やさしいまちづくり推進、そういった面では、ハードにあわせてソフト的な対応を兼ね合わせてやっていこう、そういう取り組みが１つ言えるのではないかというふう思います。","voiceIndex":62,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"今日の質疑の件なんですけれども、事業概要の説明があって、概要に対して、その概要を聞いて全体的な質問しましたので、一昨年の議事録を見ましても、そういって観点での質疑というのはやっぱり行われているので、ぜひ、１年に１回の最初の委員会ですから、ここでしか聞けないところもあるわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-007"}]},{"id":"topic-02","title":"景観行政団体になること","agenda":"景観行政団体になること","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"２番目のところの景観審議会ですが、ちょっとわからなかったので、今回の条例策定のためにつくられるものなのか、それともこれからずっと続いていって、景観についていろいろ継続的に議論していく場なのか、ちょっとそこだけわからなかったので。","respondent":"藤田水とみどりの課長","answer":"今回の条例の中で、今後景観行政を進めていくためにいかに効率よく、あるいは広く第三者の意見も取り入れながら、皆さんにご理解いただけるように進めていくかという観点で、景観審議会を設置するというふうに考えてありますので。","voiceIndex":70,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"すみません。あわせて伺います。審議会というのも２名の区民委員以外にはどんなメンバーで、どれぐらいの人数を予定しているのかというところと、あわせて、ちょっとこれは端的にお伺いしたいんですが、景観行政団体になることでの区民にとっての、メリットというんですかね、その辺が単純にどういうところにあるのかというのは、区としてはどのようにお考えになっているのか、お伺いします。","respondent":"藤田水とみどりの課長","answer":"その地域に合わせて、きめ細かく景観づくりを考えていく必要があるというふうに考えてありますので、そういった面では区民にとって景観づくり、これに取り組んでいくことが地域のまちづくりを進めていく中で重要な位置づけになる。","voiceIndex":72,"id":"exchange-009"},{"speaker":"市川委員","kind":"質問","question":"２名の区民委員を募集するということで、今詳しいお話を伺ったんですけれども、募集して、もし非常にたくさんの応募があったという場合は、区民委員を増やすとか、そういうような形になるんでしょうか。","respondent":"藤田水とみどりの課長","answer":"作文を書いていただくというのも、その中で多くの方が当然景観についてこんなふうにしていきたい、あるいはこうあるべきだというような考え方をお持ちだとは思いますが、その中でもより深く考えていただいている方を選出をして。","voiceIndex":74,"id":"exchange-010"},{"speaker":"市川委員","kind":"質問・要望","question":"平日の会議に出席できる区民の方というふうになっているんですけれども、この辺平日の会議というところでは、非常に参加される方は限定されてしまうのかなというふうに思うんですが、この辺は何か、そうではないところと検討されたのかどうか、その辺を伺いたいと思います。","respondent":"藤田水とみどりの課長","answer":"平日の会議に出席できる方ですが、今回学識の経験者等、いろいろさまざまな審議会の委員に入っていただく予定をしておりまして、そういう中でさまざまな、曜日の関係も含めて検討はしたのですが、全体を考えた中で参加しやすい。","voiceIndex":76,"id":"exchange-011"},{"speaker":"若林委員","kind":"質問","question":"各景観法等を見ても、いわゆる建築基準法等々、いろいろなルール、縛りの中で、一方で景観法という、お互いのバランスというんですか、学識経験者は専門家ということで、いわゆる景観そのものを見られるわけです。そういういろいろな法等の規制等の中で調整をする方も必要かなと思うんですが、どういう構成、そういう部分では、専門分野で７名ですか、どういうバランスを保ってやられるんでしょうか。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"なるべくそういう方が、さまざまな場所に知識にたけた方も多いんですが、区内に在住をしている方もこの中に入れていきたいということで考えながら、今進めているところです。この景観審議会というのは、景観法の法定義務のある審議会ではないんですね。法律は予定しておりません。都市計画審議会のような、都市計画法が法律で設けなさいというふうに定めているような審議会ではありません。","voiceIndex":78,"id":"exchange-012"},{"speaker":"阿部副委員長","kind":"質問","question":"もちろんこの場でいきなりこの場所で、個々にポイントを挙げて、それで具体的に議論するというのは無理だと思うので、ただ、今現段階での問題意識、例えばこういうことについて視察してみたいというようなことが現段階であればできるだけ挙げていただいて、そういったことをもとに、また正副のほうでも、それが、じゃあ具体的にどういったものがあるかということを検討して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"希望を言います。実は過去も建設委員会に何回か所属したんですけれども、旭川の水族館ありますよね。あそこのアシカ館。旭山動物園ね。あそこは何回か行こうよと言ったんですけれども、ちょうどいつも視察時期が閉館しているんですよ。旭山動物園。今回たまたまこの時期ですので、できれば行ってみたいなと。水族館の今後の運営方法なんていいのではないですかね。北海道はあまりないんだよな。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-014"},{"speaker":"阿部副委員長","kind":"質問","question":"今回の行政視察になるのかどうか、遠いところであれば行政視察で行けばいいし、近いところであれば委員会の中でさっと行けばいいと思うんですけれども、例えば今年度、やはり景観行政団体になるということで、景観にかかわる、あるいは景観行政団体になっているところを見に行くということも１つ。やはり品川ですから、都市の防災、そういったところでいい事例があれば見に行きたいなとは思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-015"},{"speaker":"安藤委員","kind":"意見","question":"今の阿部副委員長の意見に私も賛成なんですが、景観行政団体になるということなので、先行的に、先ほど８区２市でやっているということがありましたので、ぜひ都市の中で参考になるような、既に景観団体になっているところで、実際になった後にどうだったのかということを含めて。そうしたら非常に有意義になるのではないかと思いました。","respondent":"原委員長","answer":"本日以降、ご意見がございましたら、ちょっと日にちを区切らせていただきまして、６月４日金曜日までに委員長まで。一応６月４日金曜までに委員長または事務局まで、これは書面でお願いをしたいということです。もう１回整理いたします。","voiceIndex":88,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"すみません。ちょっと区としては今年に入って増加しているということ自体をどういうふうに、何が原因で、これからどういう対策というのをお考えになっているのか、そこら辺の現状分析というか、お伺いしたいと思います。よろしくお願いします。","respondent":"中山防災課長","answer":"広報紙に、一応消防署と共同で火災予防の訴えを掲載する予定があります。","voiceIndex":92,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"多分いろいろな原因とかも、前あった火災も、今日のやつも今、捜索中なのかもしれないんですけれども、区としては何か現時点で、こういうところが主な出火の原因というか、要因につながっているというのは分析などは、発表できるものがあれば教えていただきたいなと思うんですけれども。","respondent":"佐藤防災安全担当課長","answer":"区につきましては、個人情報を含めてそういう情報をいただくことができませんので、その対応については先ほど防災課長もお話ししたとおり、火災予防の徹底について消防署と連携して徹底してまいりたいというふうに考えております。","voiceIndex":94,"id":"exchange-018"},{"speaker":"原委員長","kind":"提案","question":"ほかになければ、私のほうからご案内を申し上げます。今年度の委員会運営についてですけれども、建設委員会として年間を通じて協議したい話題や、常に意識しておきたい調査事項等、委員会の皆様のご意見、ご要望をお聞きして、今後の委員会運営の参考にさせていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":96,"id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3978#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":37018,"voices":97}},{"id":"h22-20100601-9","meetingId":"h22-cm06","date":"2010年6月1日","dateIso":"2010-06-01","committee":"文教委員会","time":"午後１時０２分～午後３時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"中身にはあまり入らないようにしますが、所管がどういう形でお答えいただけるのかということをお聞きしておきます。どういうものについては子ども未来事業部に伺うのか、指導課に話をするのか、庶務課でやるのかという、その区分けだけ教えていただきたいことが１つと、それからあと、３０ページの移動教室の中で、今、５年生と８年生が一緒に行っているものがあると思うんです。","respondent":"市川教育次長、富田学務課長","answer":"ご案内のとおり、これまで保育園と幼稚園にウエイトをかけた検討を先行させまして、現在、今度は小学校のほうにウエイトをかけた検討を進めて、今、モデル実施をしているわけでございまして。夏季施設というのは、夏季休業中に豊かな自然の中でさまざまな体験活動、団体行動をするということで実施しているものでございまして、小学校は５年生のときに実施しており、教育委員会としては。","voiceIndex":33,"id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"幼保小はわかりました。これからケースに応じてということでしたので、質問を終わりにします。済みません、細かい話をあんまり聞きたくはないんですけれども、独自でいろいろされるのはいいんですけれども、多分、移動教室という名前だと補助が出るんですよね。","respondent":"冠木指導課長","answer":"教育課程の内側の教育課程内でやっている学校行事につきましては、私どもの２つの課から対応があるですけれども、教育課程外については、基本的には学校独自で予算等も編成をしていただいてやっていただいているという考え方が基本です。","voiceIndex":36,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"そうなると、支援がありますよね。生活保護を受けている方、支援という考え方が、おそらく教育課程外になってしまうと、それが入らないということになるんですか。それだけ教えてください。","respondent":"富田学務課長、冠木指導課長","answer":"就学援助のことだと思いますけれども、就学援助は小学校５年生の夏季施設も対象になっております。６年生、７年生の移動教室も対象としています。それ以外のものは支給しておりません。もう一度整理いたしますと、移動教室については教育課程内ということでやらせていただいておりますので、区からの対応があります。夏季施設については、基本的には教育課程の外側ですので、対応は基本的にはございません。","voiceIndex":38,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"久しぶりの文教委員会なので幾つかお伺いします。よろしくお願いします。ページを追っていきますのでどんどん伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"７ページの「プラン２１」のところで、後ろのほうにも書いてありますけれども、特色ある学校づくりの展開というところも含めてなんですけれども、学校選択制を導入して選ばれる学校になるためにということで、システム、仕組みとして特色づくりを出すことによってと、この間、展開をしてあるわけなんですけれども、この次の９ページのところで、小中一貫教育の仕組みづくりをしていく中で。","respondent":"田村庶務課長、冠木指導課長、和氣小中一貫教育担当課長","answer":"ただ、ご存じのとおり、教員の超勤というのは基準法の４項目に限定ということで、なかなかその残っていたのが超勤４項目に該当するのか。私からは特色づくりのところですけれども、要は、システムとしては多くの学校で取り組んでいただける状況は完備されてきたです。私からは、専門外部評価についてご説明を差し上げます。","voiceIndex":45,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これは意見で終わります。外部評価のところの成果基盤型学校経営、これは前から使っていた言葉なんですか。どのくらい利用されているのかというのは関心があるところなので、そこをちょっと教えていただきたいなと思います。品川図書館は中央館ということで４１名なんですけれども、５館が職員ゼロになっているので、この辺の体制と、専門性が保たれているのかどうか、その辺をお伺いしたいと思います。","respondent":"田村庶務課長、和氣小中一貫教育担当課長、富田学務課長、小川品川図書館長","answer":"それと、利用率なんですが、記載しても構わないんですが、ちょっと難しいのは、平日の利用率と、あと、土曜日は利用率が若干低いんですね。成果基盤型学校経営は、「プラン２１」発足当初から、平成１２年度からずっと使ってご説明させていただいているところです。給食調理代行を受託している企業の数ということですが、９社でございまして、一番多いところで７校を担当しております。","voiceIndex":49,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、全国での学童機能の重要性というものがまた再認識されている中なので、ぜひ書いていただきたいなと思います。これはお願いです。図書館のところなんですが、ブロック体制の中でバックアップをしているから大丈夫ということなんですが、委託ですか、そういった窓口ではなくて中のほうもそうですよね。","respondent":"小川品川図書館長","answer":"特に一般図書に関しては、品川図書館で集中して点検をして、品川全体を見渡して満遍なく資料が収集できるような体制をとっております。そうした面で、根幹業務については職員がしっかりと体制を整えて執行しておりますので、その辺はご心配ございません。","voiceIndex":54,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問・要望","question":"一番最初の教育目標について、ちょっと飯沼委員に関連してなんですけれども、先ほどの答弁で、時代に合っている表記になっているかとか、わかりやすさということで毎年変えているということだったんですけれども、今回、そういうところだけの変更だったのか、それとも何らかの議論があって昨年と変わっているのか、変わったところの理由、そういう思いとかは教育委員会での決定ですので。","respondent":"田村庶務課長","answer":"（４）のところで、ＩＴ化の対応で、具体的に「「携帯電話しながわアクション」の趣旨に基づき」という形の具体的な記載をしているという内容です。","voiceIndex":56,"id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"毎年こういう形で基本目標のところの表記のところで、ここの部分で大きく子どもたち、教育委員会の主な区民にとってというところがあるかと思うんですが、ここの表記で、子どもたちに関連しての目標がもう少しあるのかなというふうに考えていたので、ここのところも少し昨年と変わっていて、子どもたち、この事務事業の教育委員会のほぼ８割方。","respondent":"市川教育次長、古川子ども未来事業部長、安井子育て支援課長、吉岡保育課長、伊崎待機児童対策担当課長、小林青少年育成課長","answer":"特別支援教育、これについても、これまで９年間を通しての特別支援教育の展開ということを考えて、あるいは実践してまいりましたので。７ページが子どもに関する施策の現状と考え方ですが、細かい点につきましては、これから各課長がそれぞれご説明申し上げます。次に９番目、幼児２人同乗用自転車レンタル事業に対する補助金交付ということで。乳幼児教育の充実の一環といたしましては、専門講師による巡回指導を行うほか、保幼小の連携を引き続き実施してまいります。","voiceIndex":58,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この入れなかったお子さんと待機児数のこの差は何なのかなということで、改めて待機児数の新しいカウントと旧カウントをちょっと教えてほしいのと、この入れなかったお子さんとの数字の差異は何なのかというのを改めてお伺いしたいのが１点目です。その点でお願いします。","respondent":"伊崎待機児童対策担当課長、吉岡保育課長","answer":"私から、待機児童に関するご質問に対してお答えを申し上げます。それによって認可保育園へ入った場合とほぼ同等の経済的なご負担で認証保育所へ通えるようにする、そのような考え方です。","voiceIndex":68,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"最初の待機児童のところなんですが、新基準と旧基準の中身を教えていただきたかったんです。それをもう一度お願いしたいんです。特別支援保育のところは、後で職員のところ、どのように対応しているのか教えてください。前のときもそうでしたか。そこの違いがちょっと認識がなかったので、前に受けていたけれども、今度の基準でだめになるような方がいるのかどうかというあたりをもう１回聞かせてください。","respondent":"伊崎待機児童対策担当課長、吉岡保育課長","answer":"そちらは新定義というものになっておりまして、こちらの数字で東京都を通じて国のほうに報告を上げておりますので、区としては旧定義というのは存在はしないというふうに考えております。認証保育所の助成ですけれども、今年度の条件の中に月１６０時間以上の月極め契約というようになってありますけれども、この部分は昨年も変わらず１６０時間以上となっています。","voiceIndex":71,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"新定義の基準の中身を知りたくてお伺いしたので、どういう基準なのかというのを改めてお願いします。これは要望です。この特に今日から始まった西五反田第二保育園の４・５歳のところの幼保連携並列型というのは、中身がどうなのか全くわからないので、４・５歳のところの内容を含めて、もうちょっとここを教えていただきたいと思っています。品川区独自というところも含めてそこを教えてください。","respondent":"伊崎待機児童対策担当課長、吉岡保育課長","answer":"旧定義につきましては、申しわけございませんが、先ほども申し上げましたような判断でおりますので、報告している数字がございましたら、また確認してまいりたいと思います。今日オープンいたしました第一日野すこやか園につきましては、この間の待機児童の増加ということも受けまして、保育園部門を当初の予定では０歳から３歳までという予定だったんですけれども、それを学校の施設を活用することによって。","voiceIndex":74,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その独自性をどういうふうに配慮しながら一緒に一体化していくのかというところがすごく引っかかっているところなので、ちょっとその辺の独自性をどう配慮を重ねていくのかなというあたりをひとつお聞かせいただきたいのと、あと、先ほどの待機児の新基準のところで改めてお伺いしたら、認証とかは除かれているし、４月以降の申し込みをした人のみが新基準の中でカウントされるわけですね。独自性はいいです。","respondent":"安井子育て支援課長、吉岡保育課長、小林青少年育成課長","answer":"これは制度的に自動的には移行できませんので、その方たち、それから、あとは中学校二。その中で幼保一体施設をやっているということの意味合いは、幼稚園に通おうと、保育園に通おうと。待機児との関係から言えば、数値、子どもは施設がこうだから何人に制限するとも、逆に子どもを必要だから何人産んでいただくとか。","voiceIndex":77,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"今の次世代育成のところなんですけれども、フレームを示していて具体的な計画はほかにということなんですが、具体的にどこに示されているのかというあたりと、必要に応じて対応していくというあたりでは、待機児に限ってお伺いしますが、保育の需要をどうとらえているのかというところでさっき質問させていただいたので、この計画では間に合わないのではないかなと思うんですが。","respondent":"小林青少年育成課長","answer":"今日は用意していないので申しわけないんですけれども、２５ページには、特に留意すべき項目ということで、例えば安心して産み育てることができる子育て環境づくりの１つの例としては、待機児解消に努めてまいりますという姿勢を明確にした上で。","voiceIndex":82,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"取り扱い方についてなんですけれども、認証保育所とか私立幼稚園、私立保育園というところのいろいろ補助金を出されていると思うんです。それを例えばこの委員会の中で話し合った意見とかいろいろなことについて、それぞれの認証保育所にフィードバックするというような形ができるのかどうか、その辺についてお伺いします。","respondent":"吉岡保育課長","answer":"日常的にも、今回ご説明した保護者への補助金ですとか、あるいは運営費についても助成を出しておりますので、そういう中では、一定、認証保育所に対する要望といいますか、こちらの意向はお伝えすることは考えておりますが、内容によるかなということがあります。","voiceIndex":84,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"品川区の保育の内容というものは非常に高いものですから、それに合わせて認証だからやらなくていいよというわけではなくて、やっぱり認可保育園に入りたいんだけれども入れないという方たちがあるからこういう助成制度があると思うんです。だから、そこら辺の責任のとり方というか、やっぱりちゃんと伝えるべきところのルートがあればいいのかなと思うんですけれども、その辺について伺います。","respondent":"吉岡保育課長","answer":"基本的には、委員おっしゃるとおりと考えてございまして、補助金を出せばそれでいい、それでおしまいということではもちろんございませんので、内容、今お話があった保育士が頻繁にかわるですとか、アレルギー食の対応ですとか。","voiceIndex":86,"id":"exchange-016"}]},{"id":"topic-02","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"日程的には月末は外していただきたいなと思うのと、これから内容にかかわってきますけれども、２泊３日にこだわらずして、１泊とかで。どうしてもここへ行きたいという内容だったら、実現するに当たって、ちょっとフレキシブルに考えていただいて、日帰りもあるし、１泊でもいいとか、やっぱりあそことあそことあそこというふうな感じでなくできたらいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-017"},{"speaker":"西本委員","kind":"意見","question":"日程はまだよくわからないんですけれども、８月の後半、３０日の週となると、地方だったら学校が始まっているかもしれないですが、行くところによりますが、子どもたちの様子を見たいとなると、学校が始まってからというふうになるのかな。そういうことだと６日の週になるのか、そこは第３回定例会の通告期限とか関連……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-018"},{"speaker":"井桁委員","kind":"意見","question":"以前、自民党の視察で大阪の門真市の「門真っ子クラブ」というところに視察に行かせていただいて、門真市の小中学校で勤務をされていた職員のＯＢの方によって、子どもたちの学習塾のようなものを開催しているということで、非常にここはおもしろいところなので、ぜひ文教委員会としてもこのような放課後の対策、もしくはまた学習の支援ということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-019"},{"speaker":"金野委員","kind":"提案","question":"あわせて、先ほどの事務事業概要の中にもあったんですが、スクールカウンセラーということで配置を、増員をするという区の流れもあるんですが、私どもがこれまで議会の中でも提案してきたスクールソーシャルワーカー、この点も１つ調査をしていきたいなと、このように希望しております。行き先は具体的にはありませんが、そのようなことを希望しています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"意見","question":"私も今のご発言で、不登校とか虐待問題で取り組んで前に進んでいるところがあったら知りたいなと思っていたのが１つと、あと、保幼小の連携がこの間、幾つか視察に行っていると書いてありますけれども、今の子どもたちの成長発達の困難さというところにおいて、家庭とか地域とか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-021"},{"speaker":"井上委員","kind":"提案","question":"子どもたちの生きる力というところで、食育なんかを取り込んだ教育ということで、香川県だと思ったんですが、お弁当の日を取り組んでいる。学年ごとに食育をしていく集大成として、５年生で自分たちのお弁当をつくっていくというお話は聞いたことがあるんですが、取り組みとして実際にそういった、全国各地で広がっている発祥の地というか、それを提案したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-022"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"武内委員長","kind":"提案","question":"ないようですので、今後の委員会運営について、私からご提案させていただきたいと思います。つきましては、委員の皆様から、文教委員会にかかわる所管事務で、年間を通して協議したい課題、調査事項等がありましたら出していただき、委員会日程等を考慮しながら、できる限り審査・調査し、委員会の活性化を図っていきたいと考えておりますが、いかがでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4700#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":47807,"voices":105}},{"id":"h22-20100601-5","meetingId":"h22-cm06","date":"2010年6月1日","dateIso":"2010-06-01","committee":"総務委員会","time":"午後１時０２分～午後２時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"何点か聞きたいんですけれども、１つは会計管理室のところなんですけれども、金融機関調査会というのがあるんですけれども、例えば、リーマンショックとか、いろいろ大きな動きがあったんですけれども、そういうときにはこの調査会というのはどういう動きをするのか、実際どんな動きをしていたのかというのと。","respondent":"福田会計管理者","answer":"評価でありますけれども、これはさまざまでございまして、それぞれ基本的には公表されているデータをもとにして、例えば、それぞれの金融機関のバランスシートですとか、キャッシュフローですとか、そういうものを見る中で、不良債権の処理が順調にいっているかどうか。","voiceIndex":55,"id":"exchange-001"},{"speaker":"宮崎委員","kind":"意見","question":"要するに、そういう大きな動きのときに、実際に委員会としてはどういう動きをするのかというのが、そこのところを聞きたかったんですけれども、あともう１つ、金融機関がそういう調査によって、差し支えなければ、内容として、大体どんな調査会の結論だったかと、そういうので報告できるものがあったら、こういう内容で調査会をやったというのを、お話ができるのであればと思ったんですけれども。","respondent":"福田会計管理者","answer":"評価でありますが、個々の金融機関につきましては、それぞれ評価をいたしますので、全般的に金融機関はこういう状況だという評価はしておりません。","voiceIndex":57,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"新たな事務事業評価ということですけれども、今までの事務事業評価とおおよそどういう考え方が変わってくるのか、全く同じなのかどうかということが１つと、事業全般に当たりということになっているんですけれども、前は幾つか抽出しながらやっていたんですけれども、どういう考え方でやっていくのか、これは事業全般ということになっているんですけれども、全部やるのかどうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-003"},{"speaker":"宮崎委員","kind":"意見","question":"答えられる範囲で結構なんですけれども、前回の事務事業評価の仕組み、途中で終わって、ＰＤＣＡサイクルのやつをやっていたんだというお話なんですけれども、そうすると、前回のところで、行革の２つのエンジンと説明していたんですけれども、要するに、それをやめた、ＰＤＣＡサイクルのほうに移行したんだというお話なんですけれども、前回の仕組みがどうして切り替わったのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"もう１つは、いろいろ仕事の確保という点も出てくるので、例えば、シルバー人材センターとか、そういうところでの仕事確保という点で、全戸配布というのはもうちょっと増やしたらどうかと思っているんですけれども、そこら辺の考え方を伺いたいということと、実は人事課のところで、休職のところだと、前回予算のときにちょっと聞いたんですけれども、実際に休職のところ。","respondent":"中川原広報広聴課長、榎本人事課長","answer":"そこで今回実証実験を行う中で、どういったことが課題なのか、どういったことをクリアすればできるのかということをまず検討しようということでやるものです。本人は復職したいと言っても、なかなか体がついてこなかったり、そういう場合がありますので、まずは主治医の意見と産業医の面談を経て、本人に対して慣らし勤務ということで、半日の勤務とか、６時間の勤務とかをして、慣らしながら。","voiceIndex":64,"id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"今のメンタルのほうなんですけれども、８０％から９０％、非常に高いと感じました。何でここだけなんだろうということというのは、私はどうもわからないんですけれども、そこのところ、さっきの年間２５０件しかないというところで、平均すれば、１日大体１人じゃないかということなんですけれども、なぜこういうところがそのまま残っているのかということも含めて、ちょっと伺いたいと思います。","respondent":"中山人権啓発課長","answer":"なぜ部落解放同盟なのかというところですが、委員がおっしゃるとおり、いろいろな団体がありますが、品川区と一緒に足並みをそろえて対応していける団体であるということと、それから、国内において全国規模で、一番多く会員数もいるというところで。","voiceIndex":67,"id":"exchange-006"},{"speaker":"宮崎委員","kind":"意見","question":"今の区の２５０件で、やる必要がないんじゃないかと。だから、あえてこれを１人置いておく必要がないということと、今、私、推薦、委嘱、この仕組みは毎年ちゃんとやっているのかどうなのか。しかも、２５０件というのは、営業日からすれば、１日大体１人です、ほとんど、そういうところにあえて１人置くということとあわせて、委嘱の仕方も含めて、どういうふうにやっているのか。","respondent":"中山人権啓発課長","answer":"私もごくごくプライベートなことですから、個人的にすべてのことを把握しているわけではありませんが、お話の中から、例えば、今こういう時期ですので、就職がなかなかしにくいというところもありますが、履歴書の書き方であるとか、断られたときに。","voiceIndex":69,"id":"exchange-007"},{"speaker":"宮崎委員","kind":"意見","question":"それをあえて何でここで品川区、２３区だともう同和相談室を持っているのは本当にわずかです。何でここで持たなければいけないのか。それともう１つちょっと聞きたいんですけれども、さっき言った、依頼する、委嘱する、このシステムの説明が全然ないんですけれども、実際毎年ちゃんとした、しっかりした依頼、これをやったのかどうなのか。大体１人当たり３２０万円の給料が出ているわけです。","respondent":"榎本人事課長","answer":"要は、まずは所管から依頼をして、本人がきちんとその期間についてこういう職についているという形での承諾書をもらうという形で、勤務内容を書いた調書も添えて、人事課に依頼が来て、それでもって初めてその年度の任用ができるという形になっておりますので。","voiceIndex":71,"id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、実際そこの人がどういうふうな立場にあるのか、どういうふうに把握するのか。議員にも見せないんです。だから、これは実際には、部落解放同盟に委嘱しているということではなく、個人だということであれば、この団体との話はどうなんでしょうかということと、もう１つは、何で事務所を議員にも見せないのか。","respondent":"中山人権啓発課長","answer":"この専門非常勤につきましては、同和問題に理解と認識を持ち、社会福祉、人権感覚を有しているということで、うちのほうでしっかりと部落解放同盟東京都連品川支部に推薦を依頼しています。推薦を受けて、あと本人と雇用契約という形でやっているところです。","voiceIndex":74,"id":"exchange-009"},{"speaker":"宮崎委員","kind":"意見","question":"今、部落解放同盟品川支部に依頼しているとおっしゃいましたけれども、私、どうもこの事務所が、部落解放同盟品川支部というのはないんじゃないかと。電話番号を調べても出てこない。そういういかがわしいところです。大体同和問題で、これを利権にして、利権あさりしている、そういう団体なんだということをしっかり把握して、こういう関係をもうやめるべきだということを言っておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":77,"id":"exchange-010"},{"speaker":"林委員","kind":"質問","question":"注意されてもなかなかやまないので、あれだけれども、先ほど出た行財政改革について、企画部の概要の資料の中には、「行財政改革担当（１人）」となっていて、事務事業概要の説明をするのに、本来ならば、企画財政課の次に行財政改革担当というページがあってもいいように思うんだけれども、先ほどの委員長のご指導のお話だと、行財政改革の委員会があるから、そこで説明をしようということになって。","respondent":"久保田行財政改革担当課長","answer":"この中の企画財政課のうちの、私のほうでも企画財政課長と連携しながら、これらの事務を私も担当させていただいているというところでございまして、先ほど委員長のお話がございましたのは、事務事業評価の仕組み等については、行財政改革特別委員会の調査事項概要になりますので。","voiceIndex":78,"id":"exchange-011"},{"speaker":"林委員","kind":"質問","question":"しつこく言うけれども、企画部の組織図には企画担当と載っているんですね。ですから、組織図に、ここに突出して１つだけ担当というものがあるのが不思議なんです。その説明をしてほしい。行財政改革担当というのだけが、２ページの図でいうと、企画部からつながっている企画財政課以下、４つの課と同格に担当という組織が入ってきているんだけれども、この意味を聞きたいんです。","respondent":"久保田行財政改革担当課長","answer":"私のほうの、先ほどスタッフという説明をさせていただいたんですけれども、例えば、具体的にお話をさせていただければ、企画財政課の事務事業概要の３ページのところに書かれております企画担当の職務が幾つかありますけれども、それの中で、例えば、６番、行政組織に関すること。","voiceIndex":80,"id":"exchange-012"},{"speaker":"林委員","kind":"質問","question":"あなたは直接の関係があるからもう答えないでいいです。企画部長に聞きます。企画部という中に、行財政改革担当という仕事を預けるところを、これだけ重要なことだったならば、行財政改革課というのをつくる意味が出てくるんじゃないのかと思うんですけれども、いかがですか。","respondent":"日下部企画部長","answer":"そういう意味も込めまして、企画財政課の１つのスタッフ、企画部のスタッフといいますか、そういう形で位置づけをしているですので、ご理解をいただければと考えています。","voiceIndex":82,"id":"exchange-013"},{"speaker":"林委員","kind":"質問","question":"そうすると、さまざまな組織の中で、ゼロという年代、あるいは１けたの年代という人たちもいらっしゃる。この１７８人という数字、去年も１００人を超えていたと思うんだけれども、そういう時期が来ていて、先ほどの行財政改革じゃないけれども、品川区の中の組織を検討しなければいけないことというのは起きてこないんですか。どちらか、企画で言うのか、人事課長からなのか。","respondent":"榎本人事課長","answer":"今後は、逆に行くと、今５０代が一番多いんですけれども、あと１０年たつと５０代の方がいなくなるということで、その部分でどんなふうに若手を人材育成しながら、仕事の継承をしていくかというのが一番大きな課題になっていまして、それに向けて。","voiceIndex":84,"id":"exchange-014"},{"speaker":"林委員","kind":"質問・要望","question":"区役所に来てというか、区のいろいろな仕事を知っていく上で、若い２０代前半の人たちが区というものを説明していって、スポンサー、いわゆる税金を払う区民の人たちに仕事をわかってもらうというか、理解してもらうということに対して、これから研修をいろいろやっていかれると思うんだけれども、そういう意味で、１７０人を超す人たちへ区の説明というか。","respondent":"榎本人事課長","answer":"コミュニケーションというのは、自分が発信するだけではなくて、相手にわかって、伝わらないとコミュニケーションにならないということが一番わかってほしいところで、例えば、今、携帯電話でメールが多いんですけれども、メールというのは着いて。","voiceIndex":86,"id":"exchange-015"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"本多委員","kind":"意見","question":"先ほど事務事業概要で企画部のところでも説明いただいた都区のあり方、地方分権改革への対応ということで、平成２１年度の総務委員会の所管事務調査で挙げられた項目なんですけれども、いよいよ今年度は事務の具体的な最終的のお金の話に手をつけていく時期だと思いますので、もし、可能であれば、そういった部分が取り上げられればと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1854#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":35083,"voices":96}},{"id":"h22-20100602-14","meetingId":"h22-cm06","date":"2010年6月2日","dateIso":"2010-06-02","committee":"行財政改革特別委員会","time":"午後１時０２分～午後２時５１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"同じく共産党の安藤泰作です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-001"}]},{"id":"topic-02","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"説明のところで「厳しい財政環境を踏まえ」ということであるんですけれども、確かに今、国中で国家的な財政危機が連日報道されていまして、叫ばれているところなんですけれども、区としては、いつも理事者の方も説明されるように健全財政を誇っているというところで、さらにこれからさまざまな目黒駅の開発ですとかに１００億円単位の、ここは２００億円ですか。","respondent":"金子企画財政課長","answer":"厳しい財政環境を踏まえというところで目的を書かせていただいておりますが、そこに何かご疑問があるということなので、改めて、簡単にですけれども、ご説明させていただければ、一昨年のリーマン・ショック以来、世界の同時経済危機というのが始まりまして。","voiceIndex":26,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"そうした中で区長も施政方針で今年、３つの緊急対策ということもうたっていたわけですけれども、公有地、跡地などを有効に活用していくという上で、こういう切実なニーズに極力こたえる方向での活用というのは当然、考えていくべきだと思うんですが、区としては、主な今の区民のニーズの中でさまざまありますけれども、重点的にこれが区民のニーズなんだ。","respondent":"久保田行財政改革担当課長","answer":"１点目、事務事業評価の拘束力というんでしょうか、どういった形で反映されていくのかというご質問ですけれども、こちらにつきましては、事務事業評価の結果につきましては、資料でもご説明いたしましたように、予算編成に。","voiceIndex":28,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"最初のほうの質問なんですが、何を無駄かと聞いたというよりも、地方自治法に書かれている住民の福祉の増進を図るという地方公共団体の目的が書いているわけですけれども、この目的を度外視して、この３つの必要性、代替性、効率性ということで考えてはいけないと思うんですが、この住民福祉の増進という担保というんですか、この評価の中にどこに書かれているのか。","respondent":"久保田行財政改革担当課長","answer":"予算編成の反映につきましても、私どもといたしましては６月以降、一次評価を行いまして、その後、二次評価という形です。そうした予算編成の作業の中で、あわせて事務事業評価を行ってまいりますので、そうした中で予算には十分反映できると認識しています。","voiceIndex":30,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"そういう精神がおありであるならば、きちんとそれを明記をこの評価基準の中にすべきだと思うんですが、もしそれが大前提で書く必要もありませんというのであれば、それは当然、今の精神を踏まえてやっていくということの宣言ということで受けとめてよろしいのかどうかをお伺いします。","respondent":"久保田行財政改革担当課長","answer":"文章で云々というお話がございましたけれども、例えば資料の１番目のところですけれども、目的の４行目のところに、「区民サービスとして真に必要な事業、重点を置くべき事業の着実な前進を図る」というところが書いてありますので、そういう意味では。","voiceIndex":32,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問・要望","question":"委員長にお伺いしたいんですけれども、事務事業評価の調査項目を、今年されようとする調査項目について、ここの委員会でも調査をするということだったんですけれども、進捗状況などの報告を受けるということなのか、今、粛々とこれから進めようとするものについて、当委員会で何を調査しようとされるのか、正副委員長と理事者との協議でそういうふうに決めましたということなんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"ですからほかの方が、もしいろいろとご意見があれば、ここのことでは何をするかというのはこの委員会で決めればいいことだと思うので、正副委員長でこうですということがないのであれば、皆さんで意見をいただいて進めていただきたいなというのが１点です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問","question":"これのテーマを挙げたときに、今、ちょっと話も出ていますけれども、基本的に今回の事務事業評価に関しては、行政が行う事務事業評価であって、議会が行う事務事業評価ではないということが大前提でスタートしていると、ですから、この報告いただくのは、行政側としてつくった事務事業評価をどうとらえるかというのが、これが我々の１つですけれども、もしそれ以上にやるとすると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-008"},{"speaker":"井上委員","kind":"質問・要望","question":"どう判断するのかということが途中で出なければ、順番として一番最後の予算編成のそこに反映するという、その時期でないと出てこないわけですよね。それができるのであれば、今、鈴木委員のおっしゃったことはできると思いますけれども、どう判断するのかというのは。でなければ難しくないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それは議員の評価であって、それを、議会からの要望は理事者の方が受けとめて、どう判断するか、来年度予算にまた結びつけていく、行政は行政の中で既に評価はしているので、その点についてはこういう対応を考えているという答えも出てくると思うので、ですから、今、行政がやろうとしているこの事務事業評価は、そのまま出てきて私はおかしくないと思う。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-010"},{"speaker":"井上委員","kind":"質問","question":"今、鈴木委員が出されたものをそれはそれでと言ったけれども、出されたものがこの委員会の終わりの時期なわけです。最後の最後、１回あるかないかという時期に出されて、何をするんですかということを言いたいんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-011"},{"speaker":"須藤委員","kind":"質問","question":"私自身は、ここへ入ってくる前に、いろいろな今年度やろうとしていることが、前回やったことのいろいろな反省点を入れて、非常に煩雑であるということで今度は基本評価というのを前は６つあったのを３つにしましたとかというような話があるんだけれども、果たしてそういう仕組みがいいのかなということはちょっと疑問に思っているんだけれども、そのあたりは、今、井上委員が言ったように。","respondent":"堺委員長","answer":"最終的には３月の予算編成時には評価について公表できるという流れですから、その後には間違いなく公にされるわけでありますが、その前段階で、さっき申し上げたような可能かどうか等についてはちょっとまた検討させていただきたいと思います。","voiceIndex":41,"id":"exchange-012"},{"speaker":"菊地委員","kind":"意見","question":"先ほどの井上委員からの発言の部分で、概要のところで、今も委員長から発言があった一次評価が６月といいますから、これから始まるんだと思いますけれども、現実の問題として、この一次評価が終了するというのはどの時点になるのか、もちろん当委員会は毎月１回ぐらいずつのペースで進んでいくわけですけれども、部長の時点で一次評価が幾つか出されてくるという時点で、実際問題として、区から。","respondent":"久保田行財政改革担当課長","answer":"作業的なものですが、現在は６月になっておりますけれども、この時点、６月中いっぱいをかけまして、事業部長による一次評価を予定しています。提出されましてすぐと、その後は我々のほうで、企画のほうでいろいろ作業が必要だという段階です。","voiceIndex":43,"id":"exchange-013"},{"speaker":"菊地委員","kind":"意見","question":"今、先ほど言われた事務事業評価を進めていくための基本的な考え方とかという点では先ほど出されましたけれども、そのことを、今日の委員会でそれをやると、あとは年度末という感じになっていくことになってしまうから、どうしてもこれは調査項目として成り立たないというふうになっていくんじゃないのかなと思いますけれども、今の、行政内部での評価だということで出せないという話だったんだけれども。","respondent":"久保田行財政改革担当課長","answer":"私どもはまた正副委員長からもご指示をいただいているんですけれども、それぞれの評価基準等の詳しい仕組みについて、また時期を見ましてこちらの行財政改革特別委員会に報告したいと考えておりまして、そうした中で、いろいろご意見をいただく中で。","voiceIndex":45,"id":"exchange-014"},{"speaker":"井上委員","kind":"質問・要望","question":"制度の仕組みを聞いて、そこに意見をもらって反映していくということがこの委員会でやることなのかなというのが、今もう仕組みとしてあるわけで、今おっしゃった外部意見の聴取などのご意見などって、それは今、私が言おうとしていることなので、もうそんなに途中経過の仕組みの、仕組みは既にできていて、こういうふうにやりますよといったときに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-015"},{"speaker":"鈴木委員","kind":"質問","question":"ですからその評価をするのは、今、各委員会もあるし、決算特別委員会というものもあるけれども、この中でも、その基準はどうなんだという聞き方はまたできると思うんです。あくまで基準の判断をこの委員会でやっていくべき流れじゃないかなと私は思っています。","respondent":"堺委員長","answer":"今、鈴木委員、須藤委員等がおっしゃっておられましたように、今日、この事務事業評価実施に関しての概要についてご説明いただいたわけですが、具体的には、さっき申し上げましたように、この評価については。","voiceIndex":48,"id":"exchange-016"},{"speaker":"井上委員","kind":"提案","question":"これはもう提案でご検討いただければいいかと思うんですが、政策評価として、それぞれの議員の団体、会派でも既に行っているかもしれないんですけれども、ここは特別委員会なので、他の所管を横ぐしを刺してできるところだと思いますので、各委員からのテーマを１つ募集して、それについて議会、行財政改革特別委員会として区民の意見を盛り込んだ、行政よりもさらに市民の目線でというところで。","respondent":"久保田行財政改革担当課長","answer":"私どもとしましては、事務事業評価の結果につきましては議会に報告した後に区民に公表していく予定ですので、そうした中でご意見等があれば、お聞きしながら、よりよいものに改善していきたいなと考えております。","voiceIndex":50,"id":"exchange-017"},{"speaker":"井上委員","kind":"質問・要望","question":"では早速、外部の意見は必ず聴取していただきたいと意見をここで申し述べますが、次の段階というのは一体いつのことをおっしゃっているのか、それから区民に公表していくということですが、その公表は、そのことについて決定事項ではなく、きちんと区民の意見を反映して見直していくという姿勢で取り組まれていこうとしているのか、２点伺います。","respondent":"久保田行財政改革担当課長","answer":"次の段階はいつですけれども、この場で何年の何月からということはちょっとお約束できないところですが、今年度の経過を踏まえまして、見直した中で、そういったご意見等も取り入れられるような仕組みを検討して。","voiceIndex":52,"id":"exchange-018"},{"speaker":"井上委員","kind":"質問","question":"次のところ、さっき３つ説明いただいたので、３番目のところなんですけれども、主な区有施設の地区別一覧というところに、ここに特別養護老人ホームとか、障害者施設とか、まだほかにも区有施設、区全体のバランスを把握するには必要な区有施設はたくさんあるはずですけれども、なぜこの項目に絞られたのかをお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"なぜこの施設をですけれども、こちらにつきましては、議会側からこういった施設を載せてもらいたいということでお話がございましたので、区民の貸出施設に加えまして、保育園、幼稚園のいわゆる待機児関係、今、話題になっています待機児の関係も含めまして。","voiceIndex":54,"id":"exchange-019"},{"speaker":"井上委員","kind":"質問・要望","question":"委員会とのやりとりの中で出されたということはわかりました。これは委員長にお願いです。データのところで、シルバーセンターの利用率の表記なんですが、もう少し利用率ってあると思うんですが、品川第一地区の北品川だと１２％とか、すごく低いんですけれども、このデータは何をもってこのカウントになっているのか、そこがちょっと理解できないので、そこを説明いただけますでしょうか。","respondent":"久保田行財政改革担当課長","answer":"申しわけございません。私の説明が漏れてございました。","voiceIndex":56,"id":"exchange-020"},{"speaker":"井上委員","kind":"質問・要望","question":"これはちょっと入り過ぎてしまうかもしれないんですけれども、これもデータであれなんですが、これから大変団塊の世代の方が増えてこられて、シルバーセンターが多分、いっぱいいっぱいになったときに、どういうふうにシルバーセンターも含めて活用していくかということが、すごい施設的には空きがなくなってしまうのではないかと思っているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-021"},{"speaker":"鈴木委員","kind":"確認","question":"事務局との調整もあると思いますので、設置の段階の確認を、お願いします。幾つあるのかということを１点確認します。そこの確認を、それで、平成１７年度は完了が５件になっているから、そこら辺の数の流れ、ですから、もしＤという評価なりＣという評価をしたとして、Ｃは見直し、同じ事業が今年も見直し、翌年も見直しということがあったのかどうか、そこら辺を確認で教えてください。","respondent":"久保田行財政改革担当課長","answer":"事務事業の数ですけれども、私どもがざっと把握しているのは、予算事務事業のベースで考えますと、８００から９００の間ぐらい数があるです。","voiceIndex":59,"id":"exchange-022"},{"speaker":"渡部委員","kind":"質問・要望","question":"前回との比較の部分での質問と、先ほど来ちょっと話があって、私も頭の中でちょっと迷いがあって、１つまた委員長にお願いという部分等がありますので、このいわゆる事務事業評価というものを本年度やるということ自体が、いわゆるこの行革の一環なのかなと認識しています。ですから行政がやる事務事業評価に対して、その事業１つ１つを私たちがどうこう見直すとかという必要は私はないと思います。要望です。","respondent":"久保田行財政改革担当課長","answer":"今回、４年ぶりに事務事業評価という形になりましたが、いつまでということはありますけれども、当面の間はこうした形でよりよい形で発展させていきながら、事務事業評価は継続していきたいと考えています。","voiceIndex":61,"id":"exchange-023"},{"speaker":"渡部委員","kind":"質問","question":"やってみて、本当にこれが有効であれば、それは継続していくことが必要だと思います。１つ、私の聞き漏らしかあれなんですけれども、これは各事業に対して１つの書式なり、フォーマットを用いて、それを同じような書き方で、それに対してみんなで事業部内会議とかで評価していくんでしょうか。","respondent":"久保田行財政改革担当課長","answer":"本日こちらはつけてございませんけれども、１つの様式を定めまして、その中でそれぞれの項目について記入していただきまして、そうした数字的なものもありますけれども、そうしたものも記入した上で事業部長のほうで一次評価をしてもらうという形になってあります。","voiceIndex":63,"id":"exchange-024"},{"speaker":"菊地委員","kind":"質問・要望","question":"その中で民間委託をされていったりしているんですけれども、実際にこの５年間の事務事業評価の中で、どれぐらいのコストとして相対的に削減されたのかということと、それに伴って職員数、それから、いわゆる職員ではないですけれども、区の中でアルバイトなり派遣なりという形で働いている労働者というのはどれぐらいになっているのかという問題と。","respondent":"久保田行財政改革担当課長","answer":"それと目標ですけれども、特段私ども今の段階で目標の数値というものではなくて、それぞれの事業を見直している中で、より適正な形で事務事業の見直しを図っていきたいと考えているところです。","voiceIndex":65,"id":"exchange-025"},{"speaker":"菊地委員","kind":"質問","question":"そういうご答弁であれば、これは委員長に、今、課長からありましたように、その辺の数字のことについては後ほど出してくださるということなんでしょうか。ぜひその辺の資料をお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-026"},{"speaker":"渡辺委員","kind":"質問","question":"公有地活用のところで１点、伺います。そういう中で、そういう報告ができるケースがあるかどうかと、あと、これから事業のテーマに沿って国や都の公有地、この辺の折衝も必要になるんじゃないかということで、取得に対する行政の今のスタンス、考え方を教えていただければと思います。","respondent":"久保田行財政改革担当課長","answer":"ただ、そうした場合には、やはりその財源というか、購入するためにはお金を払わなければいけませんので、財源の確保といった観点もありますので、それら費用対効果も図りながら、これまでも検討してまいりましたし、そうした形で公有地の取得等についても考えていきたいなと。","voiceIndex":68,"id":"exchange-027"},{"speaker":"渡辺委員","kind":"確認","question":"これはちょっと感覚的な話になってしまうんですが、こういうことって、例えば国や都と折衝するときに、跡地というものが発生してから動くものなのか、それとも常に情報収集をする、あるいは情報の前に現在、国や都で活用されているけれども、区としてという働きかけをするものなのか、ケース・バイ・ケースだとは思うんですが、取得というものへのこれからの力の入れぐあい、今のお話だと。","respondent":"日下部企画部長","answer":"ただ、昨年から長期計画がスタートしましたけれども、区民ニーズにどれだけこたえていくかということで、その区民ニーズを受けて、行政側としてしっかりとこれは進めていかなければいけないと、そういう１つの軸はありますので、そういう観点に沿って、できるだけ。","voiceIndex":70,"id":"exchange-028"},{"speaker":"須藤委員","kind":"質問・要望","question":"１番目の目的で、先ほどもちょっと出たけれども、頭のところに「厳しい財政環境を踏まえ」とわざわざ断ってあったけれども、通年、きちんとやっていますよというお話なので、こういうふうに書いてきてしまうと、厳しくない財政のときはやらないのかなというような話になってくるので、こう構える必要はないんじゃないかなと思ったのが１点と、それから、選択と集中という意味が。","respondent":"久保田行財政改革担当課長","answer":"ただ、先ほどもご説明いたしましたが、今回は行政の内部評価として実施していきますが、こうしたものの中で議会、また区民の方からご意見等をいただきながら、次の段階として、より発展した事務事業評価の仕組みというものをつくっていきたいと考えているところです。","voiceIndex":72,"id":"exchange-029"},{"speaker":"金野委員","kind":"質問・要望","question":"今の須藤委員に関連して、必要性というところを教えていただきたいんですが、そうすると今のご説明でいくと、必要性あるいは代替性という、点数ではなくて、１つ１つで見たときに、これは必要か、必要じゃないかという判断基準というんですか、そういうのというのは非常に難しいものであろうと思うんですが、そこら辺はどのように判断をして、そのように必要か。","respondent":"久保田行財政改革担当課長","answer":"ただ、その後、スタートして時が経ちまして、年数がたった段階で、こうした事業の役割というものが一定、役割を果たして終えているんじゃないかといったところもありますので、まずはそういう観点から。","voiceIndex":74,"id":"exchange-030"},{"speaker":"金野委員","kind":"質問","question":"そこら辺の判断基準って非常に難しいなというところを、この事務事業の評価というものは非常に大事なことである、その一方で、そこをどういうふうに必要性を判断するかということは非常にデリケートな問題なので、そこら辺のところを非常に、どう説明していいんでしょうか、区民の皆さんのほんのわずかな人でも必要としている事業はあるわけで、そこら辺の評価のところをくみ取っていく評価の仕方というのを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-031"},{"speaker":"稲川委員","kind":"質問・要望","question":"確認でお願いしたいんですが、公有地の活用とか、跡地の活用ということをよく言われていて、最大限に用地をうまく利用していくということはこれから求められるところなんですが、この活用という意味合いが、要するに区民ニーズを反映している、そういう意味の活用なのか、それとも土地とか施設とかがもともと兼ね備えている資質というのか、それを最大限に活かすのを活用というものなのか。","respondent":"久保田行財政改革担当課長","answer":"例えば跡地の活用におきまして、土地として跡地になった場合に、そこに新たに区民ニーズが、区全体の行政需要に基づいて施設を建てるといったところもありますし、場合によっては、なかなか例がないんですけれども、例えば財産としての活用といったものもあるのかなと。","voiceIndex":77,"id":"exchange-032"},{"speaker":"井上委員","kind":"質問","question":"さっき発展的な仕組みをつくっていくんだということでは、前回で途中で終わってしまった外部評価委員のこういうのも視野に入れて、今、検討していると理解をしていいのかどうかをお伺いします。","respondent":"久保田行財政改革担当課長","answer":"また別の２点目の質問ですけれども、私ども今回は行政が主体となって、区が主体となって事務事業評価を実施してまいりますが、そうした中で、次の段階として外部の意見を反映させるというようなことも必要だというところもありますので。","voiceIndex":79,"id":"exchange-033"}]},{"id":"topic-03","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"前年度の行財政改革特別委員会で一定程度、まとめみたいに出されていて、そのまとめを読むと、土木事務所や何かはこれからもう少し検討、調査していくことが必要だと、杜松小学校、荏原第四中学校については、こういうことに留意して進めてくださいねという項目だったと思うんですけれども、その辺の前年度の行財政改革特別委員会のまとめとの関係、どういうふうにその辺は考えていくのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":83,"id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問","question":"議長から区長にもう回っているはずなので、ですからそこが変わると、ここの委員会で審議したのがまた変わってしまうと議会の意思が変わったよということになると思うので、そこら辺は確かに今、菊地委員がおっしゃった部分、もむのは当然もむ話にはなっていくと、同じ提言になるのか、全く別の提言になるかということもあるので、ちょっとその辺は正副委員長で調整していただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"だから単純に考えると、一次評価に関してはなかなか意見が言えないのかなと思うんですけれども、先ほどの話の中で、私としても、そうしたどういうふうな観点で評価していくのかということに関しても、いろいろ委員会としても必要な報告を受けながら議論していきたいというお話しになったと思うので、ぜひ私もそういった観点は大事だと思いますので、よろしくお願いしたいなと私としては思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-036"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほど資料の要望をしまして、議会運営委員会の中でそういう判断はなかったということだったんですけれども、委員会で新構成メンバーが決まった後での詳しい内容というのは、そちらのほうが私は優先されていいものだと思いますので、議会運営委員会の中ではこの大きな枠組みの中は決定されたかと思いますが、中ではどういう議論を進めていくか、進め方の問題だと思いますので、その辺を配慮していただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5884#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":33350,"voices":89}},{"id":"h22-20100603-15","meetingId":"h22-cm06","date":"2010年6月3日","dateIso":"2010-06-03","committee":"環境対策特別委員会","time":"午後１時０３分～午後２時２２分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"川西委員","kind":"質問","question":"１つだけ。勉強不足でちょっとお聞きしたいんですけれども、水辺とみどりという理念なんですけれども、これについては、平成２０年５月に新・水とみどりのネットワーク構想というのをつくって、それから次の運河ルネサンス推進で、推進地区というものが２カ所書いてある、ここにありますけれども、これというのは、予算上は都の関係とかというのを手当しているんですか。","respondent":"藤田水とみどりの課長","answer":"ということで、予算的には当該地区の方々がみずから活動するための資金を集め行っていくということで、区あるいは東京都のほうでこのことに対して予算をつけて何かをやるという事業ではございません。","voiceIndex":41,"id":"exchange-001"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、自発的に団体の方が申請の手続をするとして、区を経由して東京都に申請をするという手続になっているんですか。東京都に直接おやりになって、こういうところが推進地区になったよというふうに許可がおりてきてしまうのか、どっちですか。","respondent":"藤田水とみどりの課長","answer":"勝島・浜川・鮫洲につきましては、地域の方々が自主的に動き初めて、区のほうに話があって、東京都のほうに連携して働きかけた、そんなような経過になってあります。","voiceIndex":43,"id":"exchange-002"},{"speaker":"若林委員","kind":"質問","question":"１つだけ。里山再生なんですが、先日、早川町に崖崩れがありましたけれども、それとここの事業と関連があったのかどうか教えていただけますか。","respondent":"工藤環境課長","answer":"里山再生にかかわる崖崩れの件ですけれども、私どもも今、情報を入手しているところでございまして、詳細な部分はまだはっきりつかんでいない状況です。","voiceIndex":45,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"提案","question":"朝ですからパトロール時間外の話なんですね。私は何回も見ているわけですから、さてそれを声をかけてもいけないし、１度、確かに実際に話をしたこともあるんですけれども、自分たちの生活がかかっているから、あなたがどう提案しようがどうだと言われたこともありました。だけれども、この目的を達成するためには、今までのパトロールだけでおさまらない感じがしますので、その辺の考え方をお聞かせください。","respondent":"工藤環境課長、太田品川区清掃事務所長","answer":"環境経営支援事業に関しましては、新規事業ですけれども、今、私のほうで５つ、環境経営支援事業の中でメニューをご説明したわけなんですけれども。これは区職員で実施をしていますけれども、今年度につきましては、平成２２年度の予算審議の中でもご説明をさせていただきましたけれども、従来の職員数に比べまして、非常勤職員を３名に増やしました。","voiceIndex":47,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどからそれぞれの課から進めている事業の説明があったと思うんですけれども、そもそも品川区として地球温暖化対策やＣＯ２の削減等をそれぞれ進めている事業がどうかかわっているのか、どこを目指しているのか、そこの関係が、それぞれの説明の中で、なぜかお題目どおりに掲げられているだけで、なかなか中身が見えてこないなという気がしてならなかったんですね。","respondent":"工藤環境課長","answer":"そして最後に区は率先して行動するです。こちらのほうの取り組み方針の中に、今、事業概要で説明したそれぞれの施策といいますか、それぞれの事業がぶら下がっている、位置づけられているというのが大きな考え方です。","voiceIndex":52,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"対策にぶら下がっている、位置づけられているんだというお話ですけれども、この推進計画を、不十分な点もあると思いますが、つくったわけですよね。ただそれでは不十分になるかどうか、推進計画もつくってさらに進めていこうというわけですから、この進めるにあたって、品川区が抱えている課題とか問題点、どういう考え方を今、お持ちなのか、ご説明いただけますでしょうか。","respondent":"工藤環境課長","answer":"したがいまして、私どもとしましては、やはり自治体としましては、一人一人が行動を起こせるように、国や東京都の制度に対しまして情報を提供しましたり、それに対して、例えば上乗せの補助をして、施策を加速するというのも１つですし。","voiceIndex":54,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"当然全庁的にはなるんですけれども、そういうのはだれがリードしていくのか、逆にどこの部隊がチェックをするというのか、報告を求めるというのか、そういうのはどういう仕組みになっていらっしゃるんですか。最後にそこだけ教えていただけますか。","respondent":"工藤環境課長","answer":"温暖化対策に関しましては、当然庁内、オール品川で進めなければいけない事業だと考えています。","voiceIndex":56,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"推進会議で大きな方向性を決めているとおっしゃっているので、今、どういう報告がされているのか、どういうふうに会議が行われているのかわからないんですけれども、しっかりその報告は委員会にしていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-008"},{"speaker":"川西委員","kind":"提案","question":"この特別委員会の中身だと思うんですよ。ですから、やっていることを一々チェックするだけじゃなくて、私どもがこの１年間にどうやって環境対策をより前へ進めるお手伝いができるかというのがこの委員会だと思うんです。ですから、そういうふうに積極的にいきたいと思うんですけれども、いかがでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-009"},{"speaker":"中塚委員","kind":"意見","question":"今の品川区の環境対策について、当然議会のほうからこういう対策があるんじゃないか、こういう工夫や改善があるんじゃないか、大いにその辺は議論していきたいと思います。そのためにも目標がどこにあるのか、そして現状がどこにあるのか、それがなければ課題が見えてきませんからね。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-010"},{"speaker":"阿部委員","kind":"質問","question":"理事者側に質問というよりは、委員である私たちが考えるべきことだと思うんですけれども、最初のご説明の中で本当にたくさんこの委員会の中で扱うべき項目が出てきました。具体的な方法から、啓発から、産業から、水辺から、水族館から、リサイクルから。そういう進め方でいいのかなと。ある程度重点的にやっていきながら、ほかのことも適宜ということなのか、その辺は何かお考えがありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-011"},{"speaker":"浅野委員","kind":"質問・要望","question":"エコクリーン事業所の認定事業というのもやっていると思うんですけれども、そういうことに積極的にかかわっていくというのも、区側としても適正というんでしょうかね、継承していっていただきたいなと考えますけれども、その点が１点です。そして、やはりこれらの中小企業につきましては、都の排出量の報告書整理ですね。ちょっととりとめのない話になりましたけれども、前半の部分ですね。","respondent":"工藤環境課長、福島ものづくり・経営支援課長","answer":"考え方としまして、この事業所の認定に関しましては、要件としましては、ＩＳＯの１４００１を取っているということと、もしくは環境会計の導入、環境報告書の公表を実施しているというのが１つの大きな要件です。この環境ビジネス支援事業というものに参加している、あるいは申し込まれた企業がすべてエコクリーン事業所認定事業にかかわっているかということにつきましては、まだここでは確認できないんですけれども、助成を行いました今年の２社。","voiceIndex":63,"id":"exchange-012"},{"speaker":"浅野委員","kind":"質問・要望","question":"ものが違うのでこういう言い方はあまりしたくないんですけれども、区としての環境という問題への取り組みですね。やはり区の連携をぜひともとっていっていただきたいなと思うんですね。そういう観点でぜひとも全庁的な取り組みを本当にしていかなかったら、この２５％の削減というのは難しいと思いますので、ぜひともそういう連携をこれから密にとっていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-013"}]},{"id":"topic-02","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"伊藤委員","kind":"提案","question":"は先ほど阿部委員がおっしゃったように、これから１０回程度の中で、この中で何を重点項目としてとらまえた上で議論をしていくかということを進めていきませんと、環境というのは非常に大きなテーマですから、重点項目を中心にやっていきませんと、非常にぼやけた感じになってしまうし、先ほど来話あったように、議会から提案するにしたとしても。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-014"},{"speaker":"阿部委員","kind":"意見","question":"この平場の中では、今さらもう１回そもそも区はどうなのだというところから始まるのではなくて、それを皆さんで共有した上で展開できるようなことがあるといいなと考えています。最後にしますけれども、あともう１点は、近隣の自治体の中でいろいろ先進的なことをされているところもあると思いますけれども、そういったところは視察をしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-015"},{"speaker":"中塚委員","kind":"意見","question":"３つの調査事項概要ということですけれども、地球温暖化対策について、ある一定の目標に通じている情報とか話題もあると思いますけれども、ＩＰＣＣの気候変動に関する政府間パネル、そこの議事録や報告書を出発点にしながら、最終的には自治体として何ができるのか、どういう工夫が必要なのか、そういう各委員の意見を交わすことができる、そんな委員会運営ができたらなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-016"},{"speaker":"浅野委員","kind":"質問・要望","question":"ですから、いろいろ話も出る中、また資料も作成していただく中で、国とか都の流れとどのようにかかわっているのかということを、これを少し入れていただければ理解も深まるのかなと思うので、この点はぜひともお願いしたいなと思います。今、視察の話が出ましたけれども、私もぜひともいろいろなところ、先進的なところに視察をしていきたいと思います。多々申し上げましたけれども、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-017"},{"speaker":"川西委員","kind":"質問・要望","question":"ちょっと抽象的な発言になるかもしれませんが、この非常に窓口の広い事業、その中で中心的には区民、事業者の協力を、参加を求めて項目がありますね、どんな中にも。ですから、私は今、区が進めているいろいろな事業の中で、区民、事業者をどうやってもっと拡大して、より効率的、効果的、効果が上げられるかというようなところに選定をしていただければ、いっぱいある中で何を取り上げていくか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-018"},{"speaker":"大沢委員","kind":"質問","question":"そこのところで注釈というか、ここまでお願いしていいものかどうかわからないんですが、新しい分野ですよね、この環境というものは。ですから、我々もちょっと理解しづらい文言も出てくると思うので、そこら辺を、そこは私がわからなくても委員長がわかっている場合もあるかと思うんですが、委員長のご判断で、また注釈なり箇条書きなりしていただければ、より理解も進むのではなかろうかなと思うんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6188#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":24101,"voices":78}},{"id":"h22-20100628-6","meetingId":"h22-cm06","date":"2010年6月28日","dateIso":"2010-06-28","committee":"区民委員会","time":"午前１０時０２分～午後０時４３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５７議案、品川区立区民活動交流施設条例","agenda":"第５７議案、品川区立区民活動交流施設条例","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"その中の１つとして車をご利用される方がいると思うんですが、そのほかの施設等に載っていなかったので、その辺、どのように配置されているのかお知らせいただきたいのと、２階のＮＰＯ等の公益団体が使われる活動拠点室なんですが、先ほど見させていただいた中で、既存のものを活用していただくというのは、非常にコストも下げられてむだもなくいいなと思うんですが。","respondent":"堀越文化スポーツ振興課長、秋山協働・国際担当課長","answer":"確かに八潮団地のバス便というのはかなりの間隔でバスも出ていますので、バスのご利用いただける方はできるだけご利用いただきたいと考えていますし、ちょっとグラウンドの、ちょっと説明できなかったんですが。２階の旧スチューデントシティーのところの活動拠点室ですけれども、当然各室の扉には鍵は、セキュリティのほうは確保していますけれども、そこを使う団体同士の意見交換というか、隣の団体が何をやっているのかなとか。","voiceIndex":9,"id":"exchange-001"},{"speaker":"石田委員","kind":"質問・要望","question":"２部屋があって、２つの団体がよく協働している団体であればいいんでしょうけれども、お互い初めての団体が一緒になったときに、さまざまな問題が出てしまうんじゃないかというのが危惧されるので、その辺のセキュリティを聞いたんですが、協働でやられるというのは、例えばほかのスペースを使って皆さんでいろいろ、私たちの団体はこういうことをやっているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-002"},{"speaker":"山内委員","kind":"確認","question":"２つお伺いさせてください。確認なんですけれども、今回こういう形で区民活動交流施設を整備されるということで、アンケートをとられたということで先ほど課長のほうからご説明がありました。それからあと、これも確認なんですけれども、整備の予算が幾らなのかということと、これは自主財源で行っているのかということ、まずこの２点をお伺いします。","respondent":"堀越文化スポーツ振興課長","answer":"これは八潮まちづくり検討委員会からの提言として区のほうに提出されておりまして、その内容をもとに、また八潮の活性化という面と合わせ考えまして、区のほうといたしましても、こういった提言を受けてこのような計画をつくったということです。","voiceIndex":15,"id":"exchange-003"},{"speaker":"山内委員","kind":"質問","question":"それはもちろん皆様がいろいろとご尽力されて、いろいろ周知活動にも努めていくと思うんですけれども、その辺の利用率についてをどのようにまず考えているのかということをお伺いさせてください。学校の跡地活用という形で考えていっても、もちろんこれは行革という意味では大事なことだと思うんですけれども、そういった声をどのように今後考えていくのかということを伺いたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"ちょっと順番がずれてしまいますけれども、パソコンルームのご質問がございました。これはパソコンを今２０台ぐらい設置して、お貸ししてお使いいただくという予定をしています。","voiceIndex":17,"id":"exchange-004"},{"speaker":"山内委員","kind":"確認","question":"その辺、確かにそういう文化施設ができ上がるということで、地域の方々にとっては、ある意味ランドマーク的と言ったらあれなんですけれども、そういう形で人が集まってくるような、そういう形での交流を深めるような施設ということで、大変重要なところなのかと思っていますので、そのバランスというところを伺いたかったというところもあって質問させていただきました。それはどうなるんですか。","respondent":"堀越文化スポーツ振興課長","answer":"地域センターはそのままです。新たな施設として今回区民活動交流センターがオープンするものです。","voiceIndex":19,"id":"exchange-005"},{"speaker":"山路委員","kind":"質問・要望","question":"地元の要望どおりに既存の施設を整備するということで、非常に効果的にやられているかなとは思ったんですね。全く別な取り扱いなのか、まずそこを１つ聞きたいです。２点目は２階の活動拠点ですね。あの狭さで１万円ではちょっと高いんじゃないかという気がしたんですけれども、その辺の整合性はどうなんでしょうか。そういう関係でこういうのもできるかどうか、その３点について。","respondent":"堀越文化スポーツ振興課長、秋山協働・国際担当課長","answer":"地域の方々に使っていただいて、地域の方々がほかの方々を呼び込んでいただければ、まさに我々が期待しているところですので、そういった面においてもご活用いただけるのではないかなと思っていますし、区のほうもいろいろな意味で。八潮という場所柄というのもありますので、今のところ、教室の半分ですので、約３２m2ぐらいありますので、それで１万円というのは比較的低廉なほうであると考えております。","voiceIndex":23,"id":"exchange-006"},{"speaker":"山路委員","kind":"意見","question":"ＮＰＯ団体は品川全体のいろいろ協働をやっていただく方ですよね。そうなってくると、もう少し割引してもいいんじゃないかという勝手な想像なんですけれども、そうすると、あの部屋で１万円というのは高いような気がするんですけれども、その辺は妥当だという判断で今回設定されたわけですね。","respondent":"秋山協働・国際担当課長","answer":"１万円という算出につきましては、近隣の施設等を考えた上で、あの広さ等を考えて１万円というのを算出しまして、この程度が妥当であると判断したです。","voiceIndex":28,"id":"exchange-007"},{"speaker":"山路委員","kind":"質問","question":"もう１点のパソコン講習室というのは、高齢者の方でも今までやったことがあるとか、やっているとか、こういう方を対象にしている。ですので、全くパソコンにさわったことのない人を集めて教えて、覚えたらあとは自由に、そういうのをこしらえたらどうですかという意味なんですが。","respondent":"堀越文化スポーツ振興課長","answer":"失礼いたしました。私のほうもこれまで初心者教室という形で、高齢者の方を中心にパソコン講習という形で講座を区のほうで実施していますので、そのような面も含めてやっていきたいと思います。","voiceIndex":30,"id":"exchange-008"},{"speaker":"山路委員","kind":"質問・要望","question":"いろいろお聞きしましたけれども、高齢化率が高くて若い人が少ない。まちづくりが大きな目的ですので、活性化につながっていく。それを前提として、品川全体の方が活用できるような施設を要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問・要望","question":"２つ目が空調の関係の確認で、今日はもちろん季節柄工事中で非常にあれでしたが、ほぼ各部屋、廊下も含めて完備されるのかどうか、空調について。３つ目が、スポーツ室、既存の体育館等の利用という中で、今新しいところだと、シャワー室というのが要望として多いと思うんですが、その辺の有無、あとこの図面で言うところの旧小学校時代のプールの空間スペース、この活用を伺いたい。","respondent":"堀越文化スポーツ振興課長","answer":"現状のままという形になります。それから屋外トイレにつきましては、こちらの部分についてはトイレ改修の予定はございません。中の部分についてだけ改修という形になっております。","voiceIndex":33,"id":"exchange-010"},{"speaker":"渡辺委員","kind":"質問・要望","question":"その辺を要望というか、再度聞きたいなと。これも含まれないかなという不安があるので、再度確認です。これはちょっと関連してくるんですが、何かそのままというのも、これだけの規模で一斉整備するときに、疑問を持たれないのかなと思いますので、今現在はともかくとして、今後の可能性なんかを伺いたいと思います。アスレチック広場というのは、どういう方を想定しているのかなと思いまして、お伺いします。","respondent":"堀越文化スポーツ振興課長","answer":"はあわせて高齢者の方から若い方までこのままでご利用いただきたいということで考えておりまして、健康増進の部屋もございまして、介護予防を行いましたり、そういったところを使った事業についても展開していきたいと考えております。","voiceIndex":35,"id":"exchange-011"},{"speaker":"菊地副委員長","kind":"質問","question":"いわゆる八潮の文化センター的な位置づけでもって生かすのだとすれば、一般の品川区内に５館ある文化センターの条例で済んでいくのかなと思うんですね。ですから、その５年という設定の考え方の基本を教えてもらいたいんです。それからもう１つ、先ほど委託で管理をしていくということだったんですけれども、指定管理という方式になるんでしょうかね。","respondent":"堀越文化スポーツ振興課長、秋山協働・国際担当課長","answer":"今すぐできるのかといいますと、今、施設の規模も大きいですし、まだそこまでの組織的な対応は不可能であるという形で、ただ思いとしてはおありで、いろいろなＮＰＯの設立の動きもあると聞いておりますので、そういった面を踏まえて。５年たった後どうなるかということですけれども、ある程度の規模になって、もっと大きく展開していくので、その場合は出て行く場合もあるでしょうし、５年後はもう一度新たに、新たにというよりも。","voiceIndex":37,"id":"exchange-012"},{"speaker":"菊地副委員長","kind":"質問","question":"１つだけ。そうすると、先ほど山内委員が言っておられた、では、ほかの地域はどうなんだといったときに、新しい位置づけが必要な施設だということであれば、単純に八潮だけに当てはまる問題でもないのかなと思うんですね。そうすると、品川全体にそういう位置づけのものを、施設規模はもちろんいろいろ違いがあるんだろうけれども、そういうのを展開していくということではないんですか。","respondent":"宮地地域振興事業部長","answer":"前に創業支援センターが初め天王洲、西大井とつくりまして、武蔵小山ができた時点で、トータルの創業支援センターができて、場所の名前がそれぞれ条例で加えられましたけれども、これももしかしたら第１号は八潮ですけれども、２号、３号と。","voiceIndex":40,"id":"exchange-013"}]},{"id":"topic-02","title":"お昼ではありますが、このまま続けます。請願・陳情審査に入ります。平成２２年度陳情第１１号、指定喫煙所に関する陳情","agenda":"お昼ではありますが、このまま続けます。請願・陳情審査に入ります。平成２２年度陳情第１１号、指定喫煙所に関する陳情","exchanges":[{"speaker":"菊地副委員長","kind":"質問","question":"私もたばこを吸いますのであまり言えないんですけれども、あそこから移動することも困難、それからボックスをつくることも困難だということであれば、今、大井町駅周辺にあそこを含めて３カ所喫煙場所がありますけれども、ここでは書かれていませんけれども、撤去をするということはいかがなものでしょうかね。","respondent":"矢部生活安全担当課長","answer":"ただ大井町の地区におきまして、私としましては、現在３カ所の喫煙所は最低のラインと考えており、特にここの喫煙所を撤去した場合に、大井町の下のほうになりますけれども、吸う場所がないという状態になりますので、今のところは撤去はせずに。","voiceIndex":64,"id":"exchange-014"},{"speaker":"菊地副委員長","kind":"質問","question":"何らかの形で対応というその何らかというのは、先ほどの最初の説明であったように、移動もできないし、ボックスをつくることもできませんよという話ですから、何らかの形というのはあり得ないんだと思うんですよね。今、受動喫煙の問題がこれほど大きく問題になっている中で、あの場所があのままでいいとは思えないんですね。","respondent":"矢部生活安全担当課長","answer":"何らかの形で検討したいというのは、移設する場所もないということで、根本的な解決には当然ならないと思っています。ただ歩道側に寄って吸わないようなメッセージをしていく。","voiceIndex":66,"id":"exchange-015"},{"speaker":"菊地副委員長","kind":"質問","question":"むしろあの場所に喫煙所を置いておくことそのものが、私みたいにたばこを吸う人間にとってみれば、もっと大きな非難を浴びるということになっていくわけですから、もう一度そこは考えるべきではないかなと思うんですけれども、撤去のことも含めて、もう一度考えてみる余地がないのかどうか、そこをちょっと。","respondent":"宮地地域振興事業部長","answer":"やはり３基を２基にすれば、当然こっそり吸っては捨てるとか、いろいろまた目が届かなくなるものも一方ではありますので、ポイ捨て禁止という観点から考えれば、一定程度、駅周辺には３から４基は置くという方針のもとでやってきましたので。","voiceIndex":68,"id":"exchange-016"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"最後は意見・要望なんですが、陳情そのものは私は採択すべき中身だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-017"},{"speaker":"渡辺委員","kind":"意見","question":"この陳情要旨にある分煙については、今のご答弁の地域性の問題、必要性の問題ということで十分承知をしました。移設の経緯は、すごく最近移設をした経緯があるというのがあります。そういう意味で、この陳情に対しては、自民党としては、趣旨採択とということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-018"},{"speaker":"山路委員","kind":"意見","question":"ポイ捨ての問題と設置の問題、両方うまくいかなければいけない問題にかかっていると思うんですね。陳情者の意見はよくわかるんですけれども、区もそれに対してもずっと長年やってこられた。そういう両面を考えると、陳情者の趣旨を生かして趣旨採択、そういう気持ちです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-019"},{"speaker":"菊地副委員長","kind":"意見","question":"私はポイ捨ての問題以前に、やはり副流煙の問題というのがあの場所では一番大きなものだと思います。採択と先ほど言ったんですが、趣旨採択のご意見が多いようですので、趣旨採択ということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":75,"id":"exchange-020"},{"speaker":"石田委員","kind":"質問・要望","question":"つい最近も区民の要望をいただいて移動したという経緯もあるので、私もいろいろ問題があると思いますが、国のほうも、公共の場で喫煙というのは考えているので、そういったのも注視していただきながら趣旨を生かしていただければと思うので、趣旨採択でよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-021"},{"speaker":"高橋委員","kind":"質問・要望","question":"趣旨採択で。マナーアップ指導を徹底してやっていただきたいということと、もう１つは、ＪＴなんかでいろいろな灰皿があると思うので、スペースの関係もあると思いますけれども、今、いろいろな灰皿の種類が幾つかあるみたいですので、その辺のことも検討していただければありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2582#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":26038,"voices":81}},{"id":"h22-20100628-7","meetingId":"h22-cm06","date":"2010年6月28日","dateIso":"2010-06-28","committee":"厚生委員会","time":"午前１０時０１分～午後３時２５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を95件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５２号議案、平成２２年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第５２号議案、平成２２年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"南委員","kind":"質問","question":"その辺でのご認識を伺いたい。それから、この雇用期間は、緊急雇用ということなので、実施が短期間だと思っているんですけれども、そのあたりをどういうふうに考えていられるのか、どの程度設定されているのか。それから、人材が厳しいという点で、短期雇用で果たしていいのかどうか、その辺の見解も、ちょっと伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"介護福祉の現場での厳しい雇用の状況ということを、まず一番最初にお尋ねですが、平成２１年度以降、介護処遇改善交付金が国において処置をされ、介護報酬自体も３％上がってきたというところで、いっときの厳しい状況に比べれば、改善はされつつあると理解をしております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"単年度ということなので、人材確保のきっかけにするという話なんですけれども、しかし現実的に人材確保がなかなか厳しいという状況の中で、そういうチャンスをつくるということは大事なことなんですけれども、それが施設の側に恒常的に反映できる条件があるかどうかという、その辺についても、どういうふうに見ておられるのか、ちょっと伺います。","respondent":"冨岡高齢者福祉課長","answer":"私の表現が足りなかったのなら申しわけないんですけれども、介護報酬が第４期に改定になったということプラス、介護職員処遇改善交付金という制度が新たにできました、１万５,０００円と言われておりますが。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことがなくて、改善されているんだということは、一般的に報道されている中では、そうなんですかと、なかなか了解、認められないと、私は思うので、そこの辺の確認をしたいと思いますので、具体的な数字で示していただければと思います。","respondent":"冨岡高齢者福祉課長","answer":"手元にちょっと資料が出ておりませんけれども、特に区内の５法人については結果が出ておりますので、また調べてご報告をします。","voiceIndex":9,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"この審査をするにあたって、そこが大きなポイントになってくるのではないかと認識しておりますので、ぜひ、具体的な数字を教えていただきたい。ほかの方の質問の最後でもいいですので、ぜひ、そういうふうに計らっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"有資格者未就業者の人材活用検討経費ですけれども、仕組みづくりということですけれども、どれぐらいの確保を目標としているのか、どういう状況を目指しているのか、その仕組みづくりに際して大事な点だと思いますので、そこの目標値といいますか、改善値といいますか、そこをご説明いただけますでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"どのぐらいの確保、あるいはどういう状況を目標としているかという、次の有資格未就業者の人材活用検討経費ですが、これにつきましては、今、考えておりますのは、例えば介護福祉専門学校を卒業された方も５００人以上おいでになるわけです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"はじめに、この補正を組んだ理由、区立の部分は４月からやったけれども、民間の部分は、４月からやりたかったけれどもできなかったので、今回、補助金があったのでやったというご説明なのでしょうか。必要であるならば、当初予算になぜ組まなかったのか、なぜ４月から実施できなかったのか、そこをご説明いただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"目標値とか全部決まっていれば、すぐに事業化は簡単にできるんですが、これからどういうふうに、そういう方たちが何人ぐらいおられるのかということも含めた事業ですので、何人を目指して、どのように雇用して、どちらにつなげていくかという形はこれからつくっていく。","voiceIndex":14,"id":"exchange-006"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"いろいろ施設の方のお話を伺うと、実際に仕事をしながら教わるということもあって、必要なところもあるけれども、なかなか十分に教わり切れないという話もよく伺うので、どういうふうに、この研修事業をそれぞれの施設で進めていくというお考えなのか、区の考えを教えていただきたい。どこの施設からも、人材確保が厳しくなっている緊急度が切実に述べられているわけですよね。","respondent":"冨岡高齢者福祉課長","answer":"それについては、私どももちゃんと認識しているところでありまして、あわせて、こういうふうに潜在的な介護の人たち、お勤めになっていない方たちをどうやってつなげていくかというところで、さらに私どもは補うような意味で、こういう事業を考えているわけでございまして。","voiceIndex":16,"id":"exchange-007"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"スキルアップについては、施設での対応というお話ですけれども、ぜひ現場の状況はしっかりつかんでいただきたいと思います。介護報酬の引き上げ、それから人材配置も、３対１から２対１への改善、その公費を入れても介護保険料に連動しない仕組みづくりが必要だと、私は思いますけれども、品川区自身、人材不足の原因は何か、そしてその対応策をどう考えているのか、最後にご説明いただけますでしょうか。","respondent":"木下健康福祉事業部長","answer":"このような状況は、ここ数年変わっていないわけです。介護職員の確保が難しいといろいろ言われている中でも、品川区の中ではそういう状況だと。","voiceIndex":18,"id":"exchange-008"},{"speaker":"大沢委員","kind":"質問・要望","question":"この中で、いろいろな事業内容があると思うんですけれども、１,０８０万円の中にスキルアップするための人件費、研修手数料みたいな、そういうもろもろのものが入るのか。施設によって、緊急雇用創出であるので、必要であれば人件費も入ってこようかと思うんですけれども、そこら辺、どのような使い方をされるのか、おわかりになりましたら説明いただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"見積もりの関係ですけれども、人件費は４０万円でお２人という形で考えております。残りにつきましては、事務費ということで考えておりまして、民間の特別養護老人ホームと老人保健施設が１カ所、計５カ所という形で考えているところです。","voiceIndex":20,"id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"先ほど、中塚副委員長の質問のご答弁で、私が伺いたかったことの概要が示されましたので、それはそれで承ったとしたいと思います。委員長がおっしゃったように、それはそれとして、私も受けとめましたので、いいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-010"},{"speaker":"三上委員","kind":"質問・要望","question":"先ほどの健康福祉事業部長の答弁を伺うと、介護職の人たちは、比較的待遇的に少し改善されてきた。今、非常に厳しいのは看護職だというお話があったわけで、この人件費４０万円×２人という算出根拠になるんでしょうか、そういうお話があったんですけれども、そういうことから考えると、主に看護職員ということで受けとめていいのか、どうか。こういう相談が、実はあったんです。","respondent":"冨岡高齢者福祉課長","answer":"原則は看護師だと聞いております。","voiceIndex":25,"id":"exchange-011"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、そういった点での予算要求の部分については、やっぱり次の段階に向けても大きく、単年度限りでは困ると、部課長会でもしっかりと、そういう意見は述べていっていただければと思います。やっぱり継続できるという方向性になるように、福祉法人の事情によってやめますなんていうことにはならないようにしていただきたいと、要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"うちは賛成なんですけれども、今、三上委員がおっしゃった最後の部分、やっぱりこの雇用期間が終わったら、その人に限らず、いなくなってしまうということになると、また大変さが復活してしまうということですから、当委員会としても、きちんとそういう意見を伝えていくということが大事なのではないかなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-013"},{"speaker":"南委員","kind":"提案","question":"転倒等々によって入院する機会も、他の年代に比べれば一層高くなっているという現状がありますので、そういう場合に、入院したことによってかかる費用の一部でも負担軽減できるようにする必要があるのではないかと、そういうところで、今回、３回目になるわけですけれども、条例提案を、再度、していきたいということで提案いたしました。施行日は、平成２２年１２月１日といたします。以上です。","respondent":"鈴木委員長","answer":"議案提出者を代表して、南委員からの説明が終りました。ただいまの説明に対しまして、ご質疑等ございましたら、ご発言を願います。","voiceIndex":34,"id":"exchange-014"},{"speaker":"大沢委員","kind":"質問・要望","question":"第一に、これは繰り返しになるかもしれませんけれども、所得制限をつけないということの考え方。それから、これも以前にも出た質問かもしれませんけれども、１万円にするということの根拠。先ほどもちょっとお話を伺いましたけれども、そこを改めて、なぜ施行日を早くさかのぼらせたのかという説明をいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-015"},{"speaker":"南委員","kind":"提案","question":"しかし、品川区は、１年間に基金として、さらに積み増している額があります。こういう制度がもし実現したならば、最大限、入院したすべての方々にご利用していただきたいという思いは、もちろん多くあるんですけれども、現状は、なかなかそこまでいっていないというの実態のようですから、そのこともあわせて、今言ったのが適切なのかどうかはありますけれども、そのことをあえてご紹介したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-016"},{"speaker":"大沢委員","kind":"意見","question":"７５歳以上の方のすべてという形で、今、南委員は答弁をされていました。しかしながら、生存権がありまして、すべての国民という見地から言った場合に、確かに気持ちはわかりますけれども、世代間の公平性という見地から見た場合に、ちょっと私には納得ができない部分があるんですけれども、そこら辺のところは、どういうふうにお考えになりますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"先ほども申し上げたつもりなんですけれども、所得、あるいは、その方が暮らしておられる１世帯ごとの経済状況にとらわれずに、長く７５歳まで、あるいはそれ以上まで生きてこられた、その間の社会貢献というのは、やっぱりそれなりにきちんとあるわけですから、そういう社会的貢献というところを見たときに、財政状況がどうか、経済状況がどうかということで区別はしない、すべての方々に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-018"},{"speaker":"山元委員","kind":"質問・要望","question":"私も、ずっと前回、前々回のを見させていただいた中で、何かおっしゃっているところで、ちょっとやっぱり疑問のところがあるのが、第２条では、あくまでも医療機関に入院している者、制限はつけないと書いてあるんですが、そうしますと、入院はしていないけれども、ご自宅で介護というか、見ていらっしゃる方もいると思うんですが、そういうことを考えると、公平さというんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-019"},{"speaker":"南委員","kind":"提案","question":"介護を受けている方であっても、何らかの健康状態の変化の中で入院した場合には、その方も、当然支給をしていく対象になっていくということですから、入院時の負担軽減ということですので、ぜひ、そういうことでのご理解をいただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-020"},{"speaker":"三上委員","kind":"提案","question":"一つ、先ほど、提案者が自分で答えられなかった、基金の積み増しをしているということについて、それについて、現状はどうなっているのか。そこのところを、理事者のほうでおわかりになる方は答弁いただけますか。要するに、積み増ししたという話は出たけれども、基金として、要するに、一昨年よりずっと増えてそのままきているのか。そこのところをお願いしたい。","respondent":"木下健康福祉事業部長","answer":"ご指摘の基金は、品川区全体の基金のことを指しておられるのかと思いますけれども、必要があって基金として設置しておりまして、その都度、今回も、それなりの額を取り崩ししておりますから、一方的に積み増しをしているわけではなく、政策的な必要のために準備をし。","voiceIndex":42,"id":"exchange-021"},{"speaker":"三上委員","kind":"提案","question":"共産党が出してきた、これまでのいろいろな条例改正を含めた、このような予算を伴う提案について、あるときは、きちっと財源を明確にして、予算書を修正する形で出してきている。それで果たしていいのかどうかと、思います。３回目だから、これでもうわかっているんでしょうみたいな提案の仕方となってくると、これはちょっとあまりにもお粗末過ぎる。特に区長選が１０月あるという。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-022"},{"speaker":"南委員","kind":"提案","question":"それが一つです。そういうところを見たときに、やっぱり病気になったときに、早く健康を取り戻していただきたいという期待を示していく、そういうメッセージを送るという点でも大事なことになるのではないかという思いで、この条例をつくったものであり、そして、そういう状況を何とか実現したいということで、３回にわたって提案をしているものであります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-023"},{"speaker":"三上委員","kind":"意見","question":"冒頭、財源的な部分で、基金のことで、何がどうなのかさっぱりわからないので、何を言われたのか、理事者のほうでちょっと通訳できたらしてもらいたいんですけれども。","respondent":"木下健康福祉事業部長","answer":"先ほど、ご指摘がありましたように、通常、予算を伴う法律案とか、条例案というのは、基本的には、同時に出すのが一般的かと思いますので、その点については、一般的なルールとしては、そういうやり方になっているということは、そのとおりかと思います。","voiceIndex":48,"id":"exchange-024"},{"speaker":"三上委員","kind":"質問","question":"これは不誠実ですよね。本来だったら、これを実現したいということであるならば、もっと細かに、丁寧に、そして何とかこれを、皆さんどうでしょうかと、感情論に訴えたって、このことについて実現したいんですと、してあげたいんですという思いというのは、全く通じてきませんよ。そういうことであるということは、私はやっぱり不誠実だと言わざるを得ない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-025"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"今のご質疑を聞いていたんですけれども、まず、財源について、はじめに提出者の南委員から、積み増し部分を充てるという説明があったと思うんですけれども、そこをもう一度ご説明いただきたいと思います。大沢委員に伺いたいんですけれども、世代間の公平性というのはどういう意味なのか、ちょっと教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"その年齢、ずっと長生きしてこられて、社会的貢献をずっとしてこられた、その方々が高齢になって健康を崩されたときに、一日でも早く健康を取り戻してくださいというところの支援ですから、やっぱり世代の中で不公平になるのではないかというとらえ方というのは正しくないと思いますので、先ほどもそういうふうに申し上げたんですけれども、同じだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-027"},{"speaker":"中塚副委員長","kind":"提案","question":"先にすみません。今回の提案は、年度内ですから、その積み増し分を削るということなので、先ほどの健康福祉事業部長のご指摘は当たらないと思います。それから、大沢委員に伺いたかったのは、先ほどのお話の中で、世代間の公平性という問題があるとの指摘があったので、それはどういった意味なのか、ご主張なのか、そこをご説明いただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-028"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"区民の実態を聞いているだけです。議案審査に関して、区に資料、意見を求めるのは…。","respondent":"山田副区長","answer":"それで、今、財政調整基金というお話がございましたけれども、やはり、基金ごとの整理という形でトータルでやっているわけでございまして、今、新たなものが出てきて、ここからすぐにということは、いわゆる財政調整基金でしたら。","voiceIndex":57,"id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"もちろん、私が答弁する立場でありますので、私のほうにさまざまなご質問をしていただいていいんですけれども、しかし、理事者のほうに質問できないということではありませんので、それぞれの質問者が、自分の質問の思いの中で、理事者のほうに質問するということだってできるわけで、そこを制限するということにはならないのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-030"},{"speaker":"中塚副委員長","kind":"提案","question":"議員提案であるから、必要な資料について、区から説明が求められないという委員会運営はおかしいと、私は思います。先ほど、伺ったのは、今の区民の実態についてお伺いしたわけで、高齢者が入院した際に、何がどれぐらいかかるのか、それから、高齢者の収入について、主に国民年金の方が多いと思いますけれども、どれぐらいなのか、１カ月分について、ご説明いただきたいと思います。","respondent":"本城国保医療年金課長","answer":"年金の受給額が、区内で平均どれぐらいかということについては、私ども資料を持っておりませんので、お答えできないところです。","voiceIndex":62,"id":"exchange-031"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"今、品川区からは、入院は、平均でしょうか、３万５,５００円だと。南委員に伺いたいんですけれども、実際に入院した際に、何がどれぐらいかかってくるのか、ご説明いただきたい。そして、年金の支給額の実態がどれぐらいなのか。要するに、入院時の区民の負担の実態、そこをご説明いただけますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"それに幾らか、どのぐらいかわからないというか、さまざまなので、一概にこれだけかかるということは申し上げられませんけれども、病院に払う費用のほかにさまざまな費用がかかるという状況であるということがわかりますし、その辺のご事情については、それぞれの委員が地元のさまざまなご相談の中で伺っている部分があると思いますので、あえてこの事例にとどめておきますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-033"},{"speaker":"中塚副委員長","kind":"提案","question":"実際に私の周りでも、よく高齢者が、おじいちゃんにしろ、おばあちゃんにしろ、入院したときに、ご家族の方に伺うと、家族のだれかが入院したときに、途端に生活そのものが成り立たなくなってしまうという話も伺います。これが最後ですので一括して言いますけれども、改めて、南委員から、今回の条例の提案の理由をもう一度、ご説明いただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-034"},{"speaker":"南委員","kind":"提案","question":"提案理由ということなんですけれども、先ほど紹介したように、４０日間の入院で１４万円余、プラス紙おむつ等々の日用生活品費。したがって、私どもは、それを、今回、条例にして提案をしたわけです。元気で長生きをしていただきたいという思いの中で、せめて病気になったときは医療費の一部でも負担ができるように、かかった費用の一部でも負担できるようにという思いで、今回の条例を提案したものです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-035"},{"speaker":"中塚副委員長","kind":"提案","question":"最後なんですが、品川区に伺いたいんですけれども、先ほど、制度内の負担が基本だというお話がありました。実際に、提案者からありましたけれども、２３区の中でも、千代田区や新宿区、中野区、それぞれ制度の中身は若干違いますけれども、入院時にかかる日用品についての軽減策を打ち出しているわけです。私は、軽減策は、品川区もしっかり考えるべきではないかと思うんですけれども、いかがでしょうか。","respondent":"本城国保医療年金課長","answer":"費用負担の問題につきましては、今、前段でもご説明させていただいたところでございまして、現在の制度の中を見ましても、例えば、先ほど高額療養費を一つご紹介させていただきましたが、それについても、高齢者と一般の人と比べると。","voiceIndex":70,"id":"exchange-036"},{"speaker":"三上委員","kind":"確認","question":"それについて、これは雑所得になるのか。要するに収入という形になってきたときに、これに対する税法上の扱いというのは、どういうふうに確認してきているのか。どうなんですか、日の出町なんかやっていると、今、それはそれなのかどうかわからないけれども、それはどういう形でクリアされているのか、ちょっとお伺いしておきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-037"},{"speaker":"南委員","kind":"提案","question":"お粗末という言葉が、今、飛びましたけれども、しかし、先ほどから申し上げておりますように、区民で入院された高齢者の方々の生活をどういうふうに支えるかと、そこが中心で、そこのところをしっかりと皆さんとご議論させていただいて、成立したときには、事務方の協力もいただいて検討していくという、こういうふうに考えておりますので、提案の趣旨を十分にくんでいただいて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-038"},{"speaker":"三上委員","kind":"質問","question":"別に答える必要はない話ですよね。要するに、私のほうが質問して、聞いているわけですから、それについて、そちらのほうが答えるべきであって、それに対して、そういうふうなことを言うこと自体が、痛いところを突かれて、自分たちが不勉強だったということを出しているだけの話で、それだけでとめておけばいい話です。それはやっぱり、出す前にきちっと勉強しておく必要がある話です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-039"},{"speaker":"南委員","kind":"意見","question":"基金のところで、一つ一つの基金に、東京都が事業目的を示しているものがあるので、検討を要するんだと、先ほどご説明いただいたんですけれども、そのとおりだと思うんですが、しかし、どの基金でどういうふうに流用するのかというのは、やっぱり定められた範囲の中ではありますけれども、基金がいろいろ幅広く設定されているものについては、政治姿勢の問題だと、私は思っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-040"},{"speaker":"三上委員","kind":"提案","question":"それは、やはり、高額医療の部分で、所得の少ない方たちに対しての限度額、いろいろあるでしょうけれども、そういった点も見直しながら、そういう高額医療費、月８万円ということについて、それを４万円に減額するという、国の制度としてそういうことができないかどうかということを、私どもは提案しておりますので、それが仮に国で議論され、そしてまた、そういう形になっていくとなれば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-041"},{"speaker":"中塚副委員長","kind":"提案","question":"先ほど、自民党の大沢委員に、世代間の公平性について伺ったんですけれども、その答弁がなかったことは残念です。公明党の三上委員から、高額医療費の見直しについて、お話がありましたけれども、そこを見直しても、日用品費の負担軽減にはつながらないわけですから、今回の提案は、医療費だけではなく日用品費も含めた負担軽減ですので、ぜひご賛同いただきたいと思います。改めて、賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":81,"id":"exchange-042"},{"speaker":"稲川委員","kind":"質問","question":"先ほどからさまざまな意見をお伺いしてきました。公平とか、平等とかということが非常に多く、南委員のほうから声が出ていましたけれども、これを見る限り、平等とか、公平というのがアリバイ的に使われているような気が非常にしていまして、私としても、賛同しかねます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-043"}]},{"id":"topic-02","title":"平成２２年請願第９号、子宮頸がんから女性を守ることを求める請願および(2)平成２２年請願第１０号、子宮頸がん予防ワクチン接種の公費助成を求める請願","agenda":"平成２２年請願第９号、子宮頸がんから女性を守ることを求める請願および(2)平成２２年請願第１０号、子宮頸がん予防ワクチン接種の公費助成を求める請願","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"ただいま、説明いただきましたが、２２医療機関で行っているということです。この医療機関で行ううえにおいて、行政サイドで、事務、啓発活動について、いろいろもろもろな手続上の書類などを作成する、また送付しなければいけない作業が生じてくると思うんですが、組織変更がありました。今、そこの組織変更後の対応方、十分にできる態勢なのかどうか、教えていただきたいと思います。","respondent":"山岡健康課長","answer":"今、申し上げた区内の２２医療機関というのは、検診のことです。検診につきましては、すべての検診について、私ども健康課のほうで案内、それから、受診券を用意しまして、対象となる方に直接お送りしております。","voiceIndex":90,"id":"exchange-044"},{"speaker":"稲川委員","kind":"質問・要望","question":"１点、勉強させていただきたいんですが、子宮頸がんのワクチンを接種するまでの流れはどうなっているのか、お伺いしたいんです。ただ、１２歳とか、１０歳代前半の方が行ってやるものなのか。それとも、実際に１回検診を受けて、注射をするのか、しないのかという流れになるのか。どういう流れでワクチン接種までいくのか、ちょっと知りたいんです。","respondent":"吉田保健予防課長","answer":"ですから、ご希望の方は、医療機関でご説明を受け、納得された上で注射を打っていただくといった流れです。","voiceIndex":92,"id":"exchange-045"},{"speaker":"南委員","kind":"質問・要望","question":"大体、皮下注射３回と請願書には書いてあるんですけれども、接種そのものが、どういうものなのかも、ちょっと改めて教えていただきたい。確かにそうだと思います。したがって、請願第１０号にも、「女性の成長と健康についてきちんと理解できるよう学校での性教育を強めること」、そういうことも必要だと述べてありますけれども、ほんとうにそのとおりだなと思うんです。","respondent":"吉田保健予防課長","answer":"予防につきましては、成人への予防ということでは、今後、品川区としてもホームページ等を活用して啓発に努めてまいりたいと考えていますが、学校教育については、所管ではございませんので、これはお答えが難しいところです。","voiceIndex":94,"id":"exchange-046"},{"speaker":"南委員","kind":"質問・要望","question":"その辺の見解についても、伺いたいと思います。それから、学校教育等々については、確かに所管ではないんですけれども、あえて聞かせていただいたのは、そういう教育が必要ではないかと思うので、予防と区民の健康に関する所管として、その辺の認識をどういうふうに持っておられるのか伺いたかったので、あえてまた再度、その点も質問させていただきたいと思います。","respondent":"吉田保健予防課長","answer":"学校等につきましては、従来、任意接種につきましては、私ども、連携させていただいて啓発等も行っておりますので、こちらにつきましても、連携は必要だろうと考えています。","voiceIndex":96,"id":"exchange-047"},{"speaker":"南委員","kind":"質問・要望","question":"その点について、やっぱり検診が重要というのは当然だし、もっともっと受診率を高めていく対策はとっていただきたいと思うんですけれども、受診ができる公費助成をしっかり広げていくということが、とりわけ求められる病気への対策だと思うので、その辺について、どういうふうに思われるのか、ぜひ広げていただきたいというところで、ちょっと再度伺いたいと思います。","respondent":"山岡健康課長","answer":"これは最大の啓発だと考えていますけれども、まだまだ、特に異常を感じていない方は、まあいいと思われるかもしれませんけれども、やはり、もし何かあった場合、早期に手当ができるということでありますので、この検診の重要性を、まずないがしろにしてほしくないと。","voiceIndex":98,"id":"exchange-048"},{"speaker":"山元委員","kind":"質問・要望","question":"私もずっと何度か、子宮頸がん等では、いろいろな形で質問させていただきました。その辺、この質問が合うかどうかわかりませんが、医療のほうの薬品会社というんですか、一つが１万何千円もするというのは、何とか安くならないのか。ちょっと質問が合うかどうかわかりませんが、心情的に、受けるために何かできなのか、何かそういう情報があれば、教えていただきたいと思うんですけれども、いかがでしょうか。","respondent":"山岡健康課長、吉田保健予防課長","answer":"検診の啓発について、お答えします。先ほど、申し上げたように、対象となる方に、直接ご案内と受診券を送る。これは最大の啓発だと思っています。それ以外に、毎月、がんの検診につきましては、広報に載せております。ただ、第１回定例会でもご答弁申し上げたように、今後は、性感染症対策としての啓発という部分は進めてまいりたいと思っています。次に、製薬会社の薬価の問題ですが、ワクチンにつきましては、通常、薬価収録がございません。","voiceIndex":100,"id":"exchange-049"},{"speaker":"山元委員","kind":"質問","question":"今、お話を聞いていると、個別に送ってくださっているとか、いろいろ努力をなさっているのは確かなんですけれども、人が集まるところ、女性が集まるところを考えると、例えばスーパーマーケットとか、美容院とか、何か女性の目に届くところに啓発をしていただくと、もっとパーセンテージも上がっていき、啓発運動ができるのではないかと考えていますが、その辺は、いかがでしょうか。","respondent":"山岡健康課長","answer":"これからの課題として研究します。","voiceIndex":103,"id":"exchange-050"},{"speaker":"山元委員","kind":"質問・要望","question":"ぜひともしていただきたいと同時に、あとは対象年齢が２０歳ということで、産婦人科というか、病院自体に抵抗にあるということも事実なんです。そういう意味では、私も、男性の病院よりは女性のほうがいいなという思いがあるものですから、やはり対象年齢、若いお嬢様たちということを考えると、そういう心情的なものも考えていただくと、もっと足が運ばれるのではないかと思います。","respondent":"山岡健康課長","answer":"ちょっと男の立場ですので、どこまで言えるのかわかりませんけれども、常に標榜してやっていらっしゃいますので、特に問題はないと考えております。","voiceIndex":105,"id":"exchange-051"},{"speaker":"山元委員","kind":"質問・要望","question":"いずれにいたしましても、やはり防げるがんということでありますので、その辺をよくよく考えていただきたいと思いますので、どうかよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-052"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"二つだけなんですけれども、一つは、冒頭に、５月、国のほうで検討を開始したというお話がありましたけれども、どんな検討をしているのか、その中身を教えていただきたいと思います。要するに、国のほうがどのような問題意識を持っているのか、そこをちょっとご説明いただきたいと思います。現状についてどうなっているのか、今後の方向性についても、あわせてご説明いただけますでしょうか。","respondent":"吉田保健予防課長","answer":"５月の検討内容についてですが、あまり詳しい情報は、国からも我々のところにおりて参っておりません。ただ、政府与党が、実際に公費助成について検討を始めるということが、情報としてはあるところです。","voiceIndex":108,"id":"exchange-053"},{"speaker":"中塚副委員長","kind":"質問","question":"直接的には担任の先生なのか、保健の先生なのかとは思いますけれども、そこでの保健所や健康課との連携というのは欠かせないのではないかと思うんです。とりわけ、今回は子宮頸がんということなので、その点について、現状の取り組みと、今後、ぜひしっかりやるべきだと思うんですけれども、方向性についてご説明いただけますでしょうか。","respondent":"吉田保健予防課長","answer":"しかし、啓発等につきましては、今後、これまで以上に連携をしていく必要はあると考えていますので、お互いに情報交換を進めながら対応してまいりたいと考えています。","voiceIndex":110,"id":"exchange-054"},{"speaker":"中塚副委員長","kind":"質問","question":"その学校と連携するときに、保健所としてどういう姿勢で連携していくのか。繰り返しですけれども、なぜならば、子どもたち、とりわけ女性の成長と健康について、しっかり理解していく、そういう役割というのは、学校現場の役割と、あとは保健所としての役割もあるわけですから、保健所としての役割、連携について、現状と方向性について伺いたいと思います。","respondent":"吉田保健予防課長","answer":"ワクチンの内容につきましては、我々としては、接種が可能ということで、学校だけではなく、いろいろな媒体を使って周知はしていく予定です。連携の方向性といたしましては、学校保健委員会等を通じて意見交換をしながら進めていくということを考えております。","voiceIndex":112,"id":"exchange-055"},{"speaker":"三上委員","kind":"質問・要望","question":"時間が迫っていますから、簡単に伺います。私は、そこまで意識はなかった。ワクチンそのものが始まったばかりですから、どのぐらいどうなのかということは、これからずっと注意して見ていかなければならないということだと思いますけれども、そういった点での薬効的な部分について、きちっとした知識というか、そういった点も常に入手するように、これは努力していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-056"},{"speaker":"大沢委員","kind":"質問・要望","question":"今回の本会議の中でも、我が党の質問より、区側の積極的な意見、前向きな答弁をいただきました。よって、これについては採択をしていただきたいと、自民党は考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-057"},{"speaker":"山元委員","kind":"質問・要望","question":"公明党といたしましても、結論としては採択をお願いしたいということで、ぜひとも認めいただきたいことがたくさんありますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-058"},{"speaker":"大沢委員","kind":"意見","question":"自民党、まずこの制度を創出するということが大事で、請願項目の１番目にある、品川区におきましては、予防ワクチンについては、無料という形はとっていない。よって、請願者の新日本婦人の会の品川支部長および賛同者の方々の趣旨が十分に読み取れますので、これに関しては趣旨採択ということで、お願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-059"},{"speaker":"山元委員","kind":"質問・要望","question":"今、大沢委員がおっしゃったように、我が公明党も、やはり無料ということに対して、もう一歩踏み出すことができません。それから、次の、国に向けて子宮頸がん予防ワクチン接種に助成を行うよう要望というのは、もう既に国自体も、方向性として向かっておりますので、そういう意味では、やはり私たちも趣旨採択ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-060"},{"speaker":"南委員","kind":"意見","question":"私は、採択をするべきだと主張しますけれども、しかし、趣旨というところで、意を酌むということでまとまるのであれば、別に否定はしませんので、賛成、採択をしていきたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":137,"id":"exchange-061"},{"speaker":"稲川委員","kind":"意見","question":"請願項目に無料という言葉が入っておりまして、私も、その無料を議論する前に、まずは制度をしっかり確立をして、子宮頸がんというものはどういうものなのか、しっかりと啓発をしていくのが先だと思いますので、趣旨採択ということでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":138,"id":"exchange-062"}]},{"id":"topic-03","title":"平成２２年請願第１２号、「後期高齢者医療制度廃止法案」を即時に提出し、老人保健制度に戻す請願","agenda":"平成２２年請願第１２号、「後期高齢者医療制度廃止法案」を即時に提出し、老人保健制度に戻す請願","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"請願趣旨と請願事項、趣旨ということは、今、朗読いただいたのでわかります、後期高齢者医療制度の廃止ということなんですが、請願事項の標記の仕方についてなんですけれども、後期高齢者医療制度法案ということで、法案ということになっておりますけれども、地方自治体で条例制定は可能なんですが、法律をつくることは無理なわけでして、ここの表現が正しいのかどうか、ちょっと教えていただきたい。","respondent":"本城国保医療年金課長","answer":"今、委員、お話がございましたように、正式には法律ですので、国が国会で行うということでございまして、区自体が提案ということは、その意味では正確ではないと思います。","voiceIndex":147,"id":"exchange-063"},{"speaker":"南委員","kind":"質問・要望","question":"この制度そのものが、実施されて３年目になるんですけれども、当初は、今の説明でも、混乱があったと。その点について、認識をどういうふうに持っておられるかということを一つ伺いたいと思います。ですから、医療が大幅に制限されるという、そこのところがどういうふうになってきているのか、一つ知りたいところです。今、品川区はどのような状況になっているのか、まずその辺から伺いたいと思います。","respondent":"本城国保医療年金課長","answer":"全般的な今の運営状況につきましては、先ほど、平成２０年度当初に、周知不足等ももしかしたら手伝って、いろいろございましたが、それに対する政策的対応もありまして、現在は、窓口等の対応において見る範囲では、かなり安定的に運営がなされていると。","voiceIndex":149,"id":"exchange-064"},{"speaker":"南委員","kind":"質問・要望","question":"徴収についてなんですけれども、特別徴収も、普通徴収も、７５歳以上の高齢者が３万数千人だと思っているんですけれども、その数で見たら、とりわけ普通徴収から口座振替に切り替えた方を含めて大体半々だという理解でいいんですか。そういう状況をどう見るかということも、ちょっと認識として、伺いたいと思います。とりあえず、そこまで。","respondent":"本城国保医療年金課長","answer":"その方々に対しては、文書、あるいは電話等によって、保険料のご案内をするとともに、その方が置かれている状況を聞ける範囲でお教えいただいて、即時の全額納付が難しい場合につきましては、ご事情に応じた分納で対応させていただいたり、窓口を通じて。","voiceIndex":151,"id":"exchange-065"},{"speaker":"南委員","kind":"質問・要望","question":"短期証の発行というのは、高齢者の場合、即、命の問題にもなってくると思うので、できるだけそういうことはやめて、それこそきめ細かい相談というのであれば、それはそれで短期証発行とは別にして相談態勢をとるべきだと思っているんですけれども、この短期証との関係で、どういうふうに考えているのか、その辺を伺いたいと思います。","respondent":"本城国保医療年金課長","answer":"ただ、そういうものであっても、保険証の期間だけを見ると、短くなっているのは事実ですので、高齢者の置かれている状況を、一般の若い方以上に踏まえるために、ご本人との接触等をより一層きめ細かくして、被保険者は、先ほど、９８％以上ご納付いただいているわけですので。","voiceIndex":153,"id":"exchange-066"},{"speaker":"南委員","kind":"質問・要望","question":"徴収方法のところで、どれだけの７５歳以上の方が分かれて存在しているのかというのは、一概には言えない部分があるけれども、でも大枠で、収入状況がどうなっているのか、ちょっとつかめるかと思って伺いたかったんです。医療制限はないと、品川区としては考えているのか、どうかを、再び質問したいと思います。","respondent":"本城国保医療年金課長","answer":"診療報酬の関係ですが、導入当初に一番話題となりましたのは、先ほどもご説明させていただきました終末期医療等の問題について、かなり焦点が当たった形でご批判の声がいろいろあったところだと認識しておるところですが、現在については、それについては廃止されたり。","voiceIndex":155,"id":"exchange-067"},{"speaker":"南委員","kind":"提案","question":"特別徴収と普通徴収、ちょっとこだわって悪いんですけれども、この委員会でさまざまな議論が、これから報告も受けながら始まっていくんですけれども、そういう委員会として、ベース状況をしっかり把握しておくということは必要なことなのではないかと思いますので、そういう意味で伺いたいという質問をしたんです。その辺のご見解はどうでしょうか。","respondent":"本城国保医療年金課長","answer":"先ほどの短期証につきましても、前段でご質問がございましたので、それについても、若干補足して説明しますと、一つは、現在、いろいろ状況を把握しながら準備をしていると申し上げましたが、その中で、短期証の発行で対応せざるを得ないと考えている方は。","voiceIndex":157,"id":"exchange-068"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"それはどういう中身かというと、後期高齢者医療制度廃止法案の提出と、老人保健制度に戻すこと、その意見書を出してくださいということなので、決して品川区が法案を国会に出すという趣旨ではないので、ぜひ、ご理解をいただきたいと思います。ちょっと先ほどのご説明の中身がよくわからなかったので、あわせてご説明いただきたいと思います。","respondent":"本城国保医療年金課長","answer":"先ほどの請願の趣旨の中で、一つの保険制度では無理があるという、大臣の発言がどの場でなされたものなのか、今、具体的に承知しているものではございませんが、現在、厚生労働大臣主催の高齢者医療制度改革会議の場におきまして。","voiceIndex":159,"id":"exchange-069"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"先ほど、伺ったのは、現役並み所得以下の人からも取り上げるのかと。あわせて、今までの老人保健制度では、いかなる理由があっても、高齢者から保険証は取り上げてはならないという条文が法律に書き込まれていたと思いますけれども、伺いたいんですけれども、なぜ今まで老人保健制度では、高齢者からの保険証の取り上げが禁止となっていたのか、そこの理由を、区はどう考えているのかご説明ください。","respondent":"本城国保医療年金課長","answer":"〔「取り上げ禁止の理由」と呼ぶあり〕今、老人保健制度自体がなくなっている中なので、老人保健制度発足時点から、細かい経緯について、ちょっとこの場で詳しく把握しているわけではございませんが、少なくとも、現行の後期高齢者医療制度の関係では、今。","voiceIndex":161,"id":"exchange-070"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"先ほどから伺っているのは、現役並み所得以下の人、もっと絞って言えば、月額１万５,０００円以下の人にも短期証を発行するのかと、それを検討しているのかと聞いているんです。老人保健制度時代に、なぜ、短期証、資格証は高齢者には発行されてこなかったのか、その背景をご説明いただきたいと思います。","respondent":"木下健康福祉事業部長","answer":"むしろ老人保健制度のほうが特例的な、いわゆる老人医療費無料化のいろいろな諸問題を解決するための暫定的制度としてつくりましたので、そういう経過的な制度の中で、そういう対応になっていたんだろうと思います。","voiceIndex":163,"id":"exchange-071"},{"speaker":"中塚副委員長","kind":"質問","question":"では残りの１割はどんな方なんですか。先ほどから伺っているのは、一つの例として、１カ月１万５,０００円を切る収入の人にも、区は短期証を出すと、そんなひどいことまで検討しているのかと。改めて伺いますけれども、残りの１割というのはどういう方なのか、品川区は、月１万５,０００円以下の方にも短期証を発行することを、今、準備しているのか。私は、そんなことはやめるべきだと思います。","respondent":"木下健康福祉事業部長","answer":"今、想定している中で、窓口負担１割の方もおられますけれども、この方々の保険料、いわゆる滞納されている額は、ある程度の額以上になっておりますので、全部精査はしておりませんが、いわゆる年間年金１８万円。","voiceIndex":166,"id":"exchange-072"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"最後に、結局、明言できないわけですよね。私は、年１８万円、月１万５,０００円以下の人には短期証は発行しないと、そのことははっきりと言うべきだと思いますので、そこはもう一度、ご答弁いただきたいと思います。私は、これは命の問題だと思うんです。","respondent":"本城国保医療年金課長","answer":"かなり未納になっている額が高額で、なおかつ、いろいろ交渉をする中でも、対応が難しい方ということに絞られているですので、委員からご指摘があったような方に対する短期証の発行は予定しておりません。","voiceIndex":168,"id":"exchange-073"},{"speaker":"大沢委員","kind":"意見","question":"自民党としては、旧老人保健制度に戻すことは根本的な問題の解決にはならないということを、会派の中で議論をさせていただきました。先ほども理事者の話にもありましたが、これは国の話ですけれども、新たな制度の創設が必要と考えますので、本請願については不採択ということで、お願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":178,"id":"exchange-074"},{"speaker":"三上委員","kind":"意見","question":"私どもも、不採択です。特にいろいろ財政的な責任を明確にするとか、現役世代の負担をどうするかとかいうことについて、非常に議論がされていかなければいけない問題点を抱えている。特に私どもは、ここにうたわれている後期高齢者医療制度については推進してきた立場とすれば、それを廃止することについては、やっぱり応ずるわけにはいかない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":179,"id":"exchange-075"},{"speaker":"南委員","kind":"提案","question":"あまりにも問題の多い差別的な内容の色濃い法律ですから、しかも、多くの国民から、廃止にしてほしいという声がずっと出て、それをいまだに下回ることなくずっと維持されているという珍しい法律ですよね。民主党も、社民党も、国民新党もこぞって廃止法案を提案したという点では、民主党の態度が非常に注目されるわけであります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":180,"id":"exchange-076"}]},{"id":"topic-04","title":"平成２２年請願第１３号、中小企業センター隣のＪＴ社宅跡地等に特別養護老人ホームの建設を求める請願","agenda":"平成２２年請願第１３号、中小企業センター隣のＪＴ社宅跡地等に特別養護老人ホームの建設を求める請願","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"特別養護老人ホームの入所申請状況について、この間の、平成１９年度、２０年度、２１年度、そして今年の３月の時点での入所状況についても、教えていただきたいと思います。そして、何人が区内の特別養護老人ホームに入所できたのか、あるいは、入所申請をされた方の内訳の数字を、まず教えてください。","respondent":"冨岡高齢者福祉課長","answer":"したがいまして、ちょっと説明が難しいんですが、一応、手元の資料で申し上げますと、平成２１年度の１回目が、お申し込みになった方が５２５名です。これが、前回の３月の申込み者です。その前が５５０名です。","voiceIndex":188,"id":"exchange-077"},{"speaker":"南委員","kind":"質問","question":"半年ずつずれているので、前回の入所申請をされた方のうちで入った方が、今回も入所申請をしたうちに入っているという関係ですよね。したがって、例えば、平成２２年３月に何人申し込みをされていたか。残念ですけれども、亡くなられた方もおいでかもしれませんので、もしそういう方がおいででしたら、その数も含めて、平成２１年度分だけで教えてください。","respondent":"冨岡高齢者福祉課長","answer":"そのうち、再申込みが２３９名。２回目が５５１名でございました、そのうち再申込みが２５８名。入所された方が、１年分ですけれども、１９９名です。その他、今、おっしゃった、取り下げ、つまり亡くなったりした方が１４１名です。","voiceIndex":190,"id":"exchange-078"},{"speaker":"南委員","kind":"確認","question":"取り下げは７０人、こういうことでいいんですか。そうすると、１００人＋７０人で１７０人で、５００人から１７０人を引いた３３０人は、お元気でいられるけれども、また、再度、９月の申請なり、あるいは、再申込みは翌年の１月まで待たなければいけないのか、ちょっとその辺を確認したいんです。","respondent":"冨岡高齢者福祉課長","answer":"今、おっしゃったように、その方たちは、要介護度が高ければ、１回か２回ぐらいの申込みでお入りになれるということと、あとは、どうしても個々の事情で施設に入る必要性がおありになる場合は、個々のケアマネージメントの中で対応する。","voiceIndex":192,"id":"exchange-079"},{"speaker":"南委員","kind":"質問・要望","question":"区のほうは、区民の熱い要望になっているという、その辺の認識については、どういうふうに考えていられるのか、一つ伺いたいと思います。要介護４ですから、費用負担が３０万６,０００円。在宅でも耐えられるんだと見ているのかということを、ちょっとまず伺いたいと思います。その辺を、今までの答弁からもう少し突っ込んだ姿勢を示していただきたいと思っているんですけれども、いかがでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"したがいまして、個々のケースは、最後のケースも含めて、いつも対応をし、それなりにどうすればいいのかということで、悩みつつ決めているです。","voiceIndex":194,"id":"exchange-080"},{"speaker":"南委員","kind":"質問","question":"最初に質問した、５００人の応募に対して１００人しか入れないという事態を、数字の上と現実との話なんですけれども、どういうふうに思っているのか、そこもあえて伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"いずれにしましても、それを放置していいとは思っておりません、対応しなければいけないと思い、絶えず、そういう形で取り組んでいるところです。それは、ご理解をいただきたいと思います。","voiceIndex":196,"id":"exchange-081"},{"speaker":"南委員","kind":"質問","question":"特別養護老人ホームがこんなに区民の要求になって、区議会でも毎回、請願が出され、議会でもいろいろ取り上げられているという現状を見たときに、ほんとうに区民の実態はどうなのかと、その気になって現状をつかもうと思えばつかめるわけですよ、事業所をきちんと把握していらっしゃるわけですから。その点が二つ目です。その辺の見解というのはどうなんですか。","respondent":"木下健康福祉事業部長","answer":"うちのほうの政策的な位置づけでも、介護のセーフティネットとしての特別養護老人ホームと言っておりますから、それは経済的な問題もありますけれども、身体レベルも厳しい方々のための施設であり、在宅介護をしている方の限界に対して適切に対応するための施設であります。","voiceIndex":198,"id":"exchange-082"},{"speaker":"南委員","kind":"質問・要望","question":"つまり、経済的な負担だけではなくて、身体的な負担というか、身体的な大変さ、身体機能がずっと落ちて、要介護４とか、５とか、ほんとうに重くなってしまった状況の方々しか入れない施設になってしまうのであれば、これは一つの社会空間ですから、身体状況とか、能力とか、いろいろなところはありますけれども、そういう閉ざされた一つの社会の中で。","respondent":"冨岡高齢者福祉課長","answer":"区の中でも、用地情報については、私どもでお話をして、積極的に情報を集めているということであり、あとは町会とか、区のほかの関連団体とかにもお声かけをして、用地があれば情報等を適宜お教えくださいと話をしています。","voiceIndex":201,"id":"exchange-083"},{"speaker":"三上委員","kind":"質問・要望","question":"ちょっと確認させていただきたいんですが、これはもう表題に、中小企業センター隣のＪＴ社宅跡地等とついているけれども、ここをまず購入しろという要望があって、先ほど、ご説明では、持ち主のほうは難しいというお話でした。これは、きちっと接触して、交渉された経緯というのがあるのであれば、もう少しお話をしていただきたいと思います。","respondent":"冨岡高齢者福祉課長、山田副区長","answer":"問い合わせをしたときの話ですが、本件地は事業財産として管理しておりまして、活用方法は社内で活用するという方針ですと、そういう回答があったところです。したがって、困難だと申し上げたところです。もちろん無償ではないわけでございまして、有償で貸し出しをしますし、第一日野小学校の移転に際しても、一定の便宜を図るという話で進んでいると、私は聞いております。","voiceIndex":203,"id":"exchange-084"},{"speaker":"三上委員","kind":"質問・要望","question":"だから、そこらあたりについては、やはり厚生委員会の所管部分ではないと言いながらも、厚生委員会としては、やはり候補用地として挙がってくる以上は、情報の共有化ということだけはきちっとしておいていただきたい。今後も同じようなことは起きてくる可能性はあるのではないかと思いますので、それはきちっと答弁できるように考えておいてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":206,"id":"exchange-085"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"冒頭の説明で、用地情報について、今、情報がないという話ですけれども、どういった用地を探しているのか、ご説明いただきたい。緊急性にふさわしく、どう考えているのか、ご説明いただきたいと思います。要するに、もともとは国営企業ですからもともとは国有地なわけですよね。それから、数字のことは、やりとりがあったのに、結局よくわからなかったので、もう一度伺いたいんです。","respondent":"冨岡高齢者福祉課長","answer":"用地の情報ですけれども、前々から申し上げていますが、一定規模の土地がありませんと、経営上うまく安定的な経営ができないというような状況がありますので、やはり、小さい土地では難しいという形で対応しています。","voiceIndex":207,"id":"exchange-086"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"確かに一定規模の土地がないとだめだと、かといって小規模も否定しないと。今年の区長の所信表明演説の中でも、高齢者の生活支援推進というのを緊急対策に挙げておられましたけれども、緊急というのであれば、それを具体的に進めるべきだと思うんですけれども、そこはどう考えているのか。冒頭説明した具体化の計画を、緊急にふさわしい具体化を進めるべきだと思うんですけれども、いかがでしょうか。","respondent":"木下健康福祉事業部長","answer":"先般、公明党のご質問の中で、小規模特別養護老人ホームのお話がございましたので、小規模特別養護老人ホーム、つまり２９人にグループホーム１８人を組みあわせるようなものは検討の余地はあるかなと。これは、具体的に出てきた用地の状況によるだろうと思います。","voiceIndex":209,"id":"exchange-087"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"どういう事業を進めるために、では、この場所だったらこれができる、こういう規模だったらこれができる、区の主体性が全く見えてこないんですけれども、しっかりと敷地があいたら考えるというのではなくて、しっかりと区の計画、目標、テンポを具体化すべきではないかと思うんですけれども、その点を教えていただきたいと思います。","respondent":"山田副区長","answer":"そのための整備、検討とうたわせていただいておりますので、特別養護老人ホームについても、下にあります老人保健施設についても、これからも同じスタンスで臨んでまいりたいと考えています。","voiceIndex":211,"id":"exchange-088"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"こっちは数字を掲げて進めていくと。私も聞いたんですけれども、今年の３月の審査のときに、１０２歳、要介護５の方が申し込んだけれども、入れなかったという話を伺いました。ぜひわかってほしいのは、こういう家族の状況を伺うと、みんな言うのは、悲惨だという言葉を使うんですよ。ぜひ目標値を立てて、計画に向けて具体化を進めていただきたいと思いますけれども、最後にいかがでしょうか。","respondent":"木下健康福祉事業部長","answer":"特別養護老人ホームは何で書かないのかという部分については、これは再三申し上げておりますけれども、大変区民の関心も高い事項でありますので、そういう点では、用地の確保の見通しがついた段階で明らかにするのが、むしろ行政としての責任だろうと考えていますので。","voiceIndex":214,"id":"exchange-089"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"最後に、健康福祉事業部長が、区民の関心が高いから、決まってから発表だとおっしゃいましたけれども、私は、区民の関心が高いからこそ、品川区はしっかり整備計画をもってそれを目標に照らして具体化を進めていく、そのための計画を進めることこそ区民要望を受け入れるものだと、私は思います。最後に意見だけです。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":216,"id":"exchange-090"},{"speaker":"大沢委員","kind":"質問・要望","question":"私どもは、特別養護老人ホーム等々の整備に関しては、十分にニーズを把握しており、また必要だと考えています。区も、用地確保がなかなか難しい中で、それからさまざまな複雑な事情が重なりながらも、積極的に取り組んでいくという基本方針を、先ほど態度のほうで伺いました。しかしながら、本請願、内容、あるいは言っていることは別にしまして、これについては不採択にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":225,"id":"exchange-091"},{"speaker":"三上委員","kind":"質問","question":"考えてみると、この表題で中小企業センター隣のＪＴ社宅跡地ということをうたっているわけですから、ここのところについてどうなのかということを考えてみると、ここについては、交渉しても、結局自社の中で有効活用するという基本方針があり、売る考え方はないと言っている人様の土地に対して、それをあえて、買えという結論を出すということについては、私どもはこれは不誠実だと考えますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":226,"id":"exchange-092"},{"speaker":"南委員","kind":"意見","question":"特別養護老人ホーム、そして特に老人保健施設は区内には１カ所しかない。これは、２３区のほかの区と比べても、水準的には低いですよね。したがって、これは一刻も早く２カ所目を建設するめどを、ぜひ、立てていくべきだと思います。したがって、一刻も早くそういう具体的な計画を持つべきだという意見も付して、ぜひ、賛成をしていきたいと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":227,"id":"exchange-093"},{"speaker":"稲川委員","kind":"確認","question":"なおかつ、先ほど、高齢者福祉課長からもご答弁がありましたように、確認をしたら、社内利用が決まっているということを、品川区が強制力を発揮して、そこまでして購入する必要性もないと思います。なぜ、ＪＴ社宅跡地なのか、土地があいているから、そこに老人保健施設とかを建てるというのは、あまりにも安直な部分だと思います。そういうことも考えると、僕は、不採択にしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":228,"id":"exchange-094"},{"speaker":"鈴木委員長","kind":"質問","question":"私のほうから、今定例会の一般質問にかかわる所管質問について、ご案内を申し上げます。ご承知のように、本件は委員会活動の活性化という観点から、各常任委員会において当該会期中の一般質問に係わる当該委員会の所管質問を行うというものです。質問なさりたい委員がいらっしゃいましたら、この場で通告をしていただきまして、翌日、理事者に答弁をしていただくことになります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":231,"id":"exchange-095"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3270#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":72208,"voices":233}}]);
